(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-201":{scenario:{legacy:"KK-201"},learning:{summary:{vi:"Chuyên viên chứng từ xuất nhập khẩu lập, kiểm tra và hoàn thiện bộ chứng từ cho từng lô hàng: hóa đơn thương mại, phiếu đóng gói, vận đơn, giấy chứng nhận xuất xứ, bảo hiểm và bộ chứng từ xuất trình theo thư tín dụng (L/C). Mục tiêu là chứng từ khớp nhau, khớp điều kiện L/C và đúng Incoterms để ngân hàng thanh toán và hàng thông quan đúng hạn.",en:"An import-export documentation specialist prepares, checks and completes the document set for each shipment: commercial invoice, packing list, bill of lading, certificate of origin, insurance and the presentation set under a letter of credit (L/C). The goal is documents that match each other, comply with the L/C and the right Incoterms so the bank pays and goods clear on time."},responsibilities:{vi:["Lập hóa đơn thương mại, phiếu đóng gói theo hợp đồng và điều kiện L/C.","Đặt chỗ, theo dõi vận đơn và kiểm tra thông tin tàu, cảng, ngày giao hàng.","Xin giấy chứng nhận xuất xứ (C/O) phù hợp hiệp định thương mại của nước nhập khẩu.","Kiểm tra bộ chứng từ xuất trình, phát hiện bất hợp lệ trước khi nộp ngân hàng.","Lưu hồ sơ lô hàng và phối hợp với kinh doanh, hãng tàu, ngân hàng, hải quan."],en:["Issue the commercial invoice and packing list in line with the contract and L/C terms.","Book space, track the bill of lading and check vessel, port and shipment dates.","Obtain the certificate of origin (C/O) matching the importing country's trade agreement.","Check the presentation set and catch discrepancies before submitting to the bank.","Archive shipment files and coordinate with sales, carriers, banks and customs."]},competencies:[{name:{vi:"Đối chiếu chứng từ",en:"Document matching"},desc:{vi:"So khớp từng trường giữa hóa đơn, phiếu đóng gói, vận đơn, C/O và điều khoản L/C.",en:"Match every field across invoice, packing list, bill of lading, C/O and L/C clauses."}},{name:{vi:"Incoterms & thanh toán quốc tế",en:"Incoterms & trade finance"},desc:{vi:"Hiểu nghĩa vụ, chi phí, rủi ro của các điều kiện giao hàng và phương thức L/C, D/P, T/T.",en:"Understand duties, costs and risks of delivery terms and L/C, D/P and T/T payments."}},{name:{vi:"Chính xác số liệu",en:"Data accuracy"},desc:{vi:"Kiểm soát trọng lượng, số kiện, trị giá và mô tả hàng thống nhất trên mọi chứng từ.",en:"Keep weights, packages, values and descriptions consistent on every document."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Không lùi ngày, không sửa chứng từ sai sự thật; đề xuất sửa L/C hoặc phương án hợp lệ.",en:"Never backdate or falsify documents; propose an L/C amendment or a compliant alternative."}},{name:{vi:"Quản lý thời hạn",en:"Deadline management"},desc:{vi:"Bám sát ngày cắt máng, hạn giao hàng và hạn xuất trình chứng từ.",en:"Track cut-off times, latest shipment dates and presentation deadlines."}}],knowledge:{vi:["Incoterms 2020 của ICC: EXW, FOB, CFR, CIF, DAP, DDP và phân chia rủi ro, chi phí.","UCP 600 về thư tín dụng và chuẩn mực kiểm tra chứng từ ISBP của ICC.","Các loại vận đơn đường biển, vận đơn hàng không và yêu cầu ký phát.","Quy tắc xuất xứ và các mẫu C/O theo FTA như ATIGA (mẫu D), AJCEP (mẫu AJ), VJEPA (mẫu VJ).","Nghĩa vụ mua bảo hiểm hàng hóa theo CIF/CIP và điều kiện bảo hiểm ICC (A), (B), (C)."],en:["ICC Incoterms 2020: EXW, FOB, CFR, CIF, DAP, DDP and the split of risks and costs.","UCP 600 for letters of credit and the ICC ISBP standard for document examination.","Types of ocean and air waybills and their issuance requirements.","Rules of origin and FTA C/O forms such as ATIGA (Form D), AJCEP (Form AJ) and VJEPA (Form VJ).","Cargo insurance duties under CIF/CIP and Institute Cargo Clauses (A), (B), (C)."]},tools:["ECUS / VNACCS","Cổng eCoSys cấp C/O điện tử","Microsoft Excel","Hệ thống booking của hãng tàu","Phần mềm quản lý lô hàng (TMS)"],kpis:{vi:["Tỷ lệ bộ chứng từ L/C được ngân hàng chấp nhận lần đầu.","Số lô hàng trễ cắt máng do chứng từ (mục tiêu bằng 0).","Thời gian hoàn thiện bộ chứng từ sau ngày tàu chạy.","Số lỗi sai lệch phát hiện trước khi xuất trình."],en:["Share of L/C presentations accepted by the bank first time.","Shipments missing cut-off because of documents (target zero).","Time to complete the document set after vessel departure.","Discrepancies caught before presentation."]},day:[{time:"08:00",vi:"Kiểm tra email khách hàng, hãng tàu và lịch tàu của các lô trong tuần.",en:"Check customer and carrier emails and this week's vessel schedule."},{time:"09:30",vi:"Đối chiếu bản nháp vận đơn với phiếu đóng gói và điều kiện L/C.",en:"Compare the draft bill of lading with the packing list and L/C terms."},{time:"13:00",vi:"Nộp hồ sơ xin C/O và cập nhật hóa đơn theo Incoterms đã thỏa thuận.",en:"Apply for the C/O and update the invoice to the agreed Incoterms."},{time:"15:30",vi:"Xử lý yêu cầu gấp từ kinh doanh, báo cáo rủi ro trước giờ cắt máng.",en:"Handle urgent sales requests and flag risks before the cut-off time."},{time:"17:00",vi:"Hoàn thiện bộ chứng từ, gửi ngân hàng và lưu hồ sơ lô hàng.",en:"Finalize the set, send it to the bank and archive the shipment file."}],mistakes:{vi:["Để Incoterms trên hóa đơn khác điều kiện L/C (ví dụ FOB thay vì CIF).","Ghi trọng lượng trên vận đơn không khớp phiếu đóng gói đã xác nhận.","Chấp nhận lùi ngày vận đơn để được thanh toán, gây rủi ro gian lận chứng từ."],en:["Invoice Incoterms differing from the L/C (for example FOB instead of CIF).","Bill of lading weight not matching the certified packing list.","Agreeing to backdate a bill of lading to get paid, creating document fraud risk."]},career:[{vi:"Nhân viên chứng từ xuất nhập khẩu",en:"Export documentation assistant"},{vi:"Chuyên viên chứng từ & thanh toán quốc tế",en:"Documentation & trade finance specialist"},{vi:"Trưởng nhóm xuất nhập khẩu",en:"Import-export team lead"},{vi:"Quản lý chuỗi cung ứng & xuất nhập khẩu",en:"Supply chain & import-export manager"}],glossary:[{term:"L/C",vi:"Thư tín dụng: cam kết thanh toán của ngân hàng khi người bán xuất trình chứng từ phù hợp.",en:"Letter of credit: a bank's undertaking to pay against complying documents."},{term:"B/L",vi:"Vận đơn đường biển: biên nhận hàng, bằng chứng hợp đồng vận chuyển và chứng từ sở hữu.",en:"Bill of lading: receipt of goods, evidence of carriage contract and document of title."},{term:"Packing List",vi:"Phiếu đóng gói liệt kê số kiện, quy cách, trọng lượng tịnh và cả bì của lô hàng.",en:"List of packages, specifications, net and gross weights of the shipment."},{term:"Discrepancy",vi:"Bất hợp lệ: điểm chứng từ không khớp L/C hoặc không thống nhất giữa các chứng từ.",en:"A point where documents do not comply with the L/C or with each other."},{term:"Cut-off",vi:"Giờ cắt máng: thời hạn cuối giao hàng hoặc chứng từ cho hãng tàu trước khi tàu chạy.",en:"The last time to deliver cargo or documents to the carrier before sailing."}],quiz:[{q:{vi:"Theo CIF, ai có nghĩa vụ mua bảo hiểm hàng hóa?",en:"Under CIF, who must buy cargo insurance?"},options:{vi:["Người mua","Người bán","Hãng tàu","Ngân hàng mở L/C"],en:["The buyer","The seller","The carrier","The issuing bank"]},answer:1,explain:{vi:"CIF yêu cầu người bán mua bảo hiểm cho người mua với mức tối thiểu theo ICC (C).",en:"CIF requires the seller to insure for the buyer, at least on ICC (C) terms."}},{q:{vi:"Trọng lượng trên vận đơn khác phiếu đóng gói đã xác nhận. Bạn làm gì?",en:"The B/L weight differs from the certified packing list. What do you do?"},options:{vi:["Giữ nguyên vì hãng tàu đã cân","Sửa phiếu đóng gói cho khớp vận đơn","Xác minh và sửa vận đơn theo số liệu đã xác nhận trước phát hành","Bỏ qua vì chênh lệch nhỏ"],en:["Keep it because the carrier weighed it","Change the packing list to match","Verify and correct the B/L to the certified figure before issue","Ignore it as a small gap"]},answer:2,explain:{vi:"Chứng từ phải thống nhất; phải xác minh nguồn và sửa trước khi phát hành để tránh bất hợp lệ.",en:"Documents must be consistent; verify the source and correct before issue to avoid discrepancies."}},{q:{vi:"Quy tắc nào điều chỉnh việc kiểm tra chứng từ theo L/C?",en:"Which rules govern document examination under an L/C?"},options:{vi:["UCP 600 và ISBP","Incoterms 2020","Luật Hải quan","ISO 9001"],en:["UCP 600 and ISBP","Incoterms 2020","Customs Law","ISO 9001"]},answer:0,explain:{vi:"UCP 600 quy định nghĩa vụ các bên trong L/C; ISBP hướng dẫn chuẩn kiểm tra chứng từ.",en:"UCP 600 sets L/C obligations; ISBP guides the standard of document examination."}},{q:{vi:"Kinh doanh đề nghị lùi ngày vận đơn để kịp hạn L/C. Phương án đúng là gì?",en:"Sales asks to backdate the B/L to meet the L/C deadline. What is right?"},options:{vi:["Đồng ý nếu trưởng phòng cho phép miệng","Chờ đến khi hết giờ cắt máng","Tự sửa ngày trên bản scan","Từ chối, báo cáo và đề nghị sửa L/C hoặc đổi chuyến hợp lệ"],en:["Agree if the manager says so verbally","Wait until the cut-off passes","Edit the date on the scan yourself","Refuse, escalate and request an L/C amendment or a compliant sailing"]},answer:3,explain:{vi:"Lùi ngày vận đơn là gian lận chứng từ; phải từ chối và tìm phương án hợp lệ.",en:"Backdating a B/L is document fraud; refuse and find a compliant option."}}]}},"KK-202":{scenario:{company:"Lotus Gate Trading",supervisor:{name:"Phạm Quang Huy",role:{vi:"Trưởng phòng Thủ tục Hải quan",en:"Customs Compliance Manager"}},ref_code:"TK-0942",title:{vi:"Đúng mã HS. Đúng trị giá. Đúng luật.",en:"Right HS code. Right value. Right law."},brief:{vi:"Bạn khai tờ khai nhập khẩu TK-0942 cho 400 máy pha cà phê gia dụng chạy điện. Hóa đơn ghi FOB 12000 USD, cước biển 600 USD, phí bảo hiểm 60 USD. Đối chiếu tờ khai nháp với bộ hồ sơ đã duyệt, sửa mã HS và số thuế nhập khẩu (thuế suất trong bài mô phỏng 20%), rồi lập báo cáo có căn cứ.",en:"You are filing import declaration TK-0942 for 400 electric household coffee makers. The invoice shows FOB 12000 USD, ocean freight 600 USD and insurance 60 USD. Compare the draft declaration with the approved file, correct the HS code and the import duty (training rate 20%), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phân loại & trị giá đã duyệt · TK-0942",en:"Approved classification & valuation file · TK-0942"},fields:[{id:"HS_CODE",label:{vi:"Mã HS khai báo",en:"Declared HS code"},initial:"8509.40",expected:"8516.71",choices:["8509.40","8516.71","8419.81"],reference:"Phiếu phân loại HS",hint:{vi:"Đọc chú giải chương 85: máy pha cà phê gia dụng gia nhiệt bằng điện thuộc nhóm 85.16.",en:"Read the Chapter 85 notes: electro-thermic household coffee makers fall under heading 85.16."}},{id:"DUTY_USD",label:{vi:"Thuế nhập khẩu (USD)",en:"Import duty (USD)"},initial:"2400",expected:"2532",reference:"Bảng tính trị giá hải quan",ref_value:{vi:"Trị giá tính thuế = FOB 12000 + cước 600 + bảo hiểm 60; thuế suất 20%",en:"Customs value = FOB 12000 + freight 600 + insurance 60; duty rate 20%"},hint:{vi:"Trị giá tính thuế nhập khẩu phải cộng cước và bảo hiểm đến cửa khẩu nhập đầu tiên.",en:"The dutiable value must include freight and insurance to the first port of import."}}],sop32:{vi:"Trị giá hải quan = giá FOB + cước vận tải + phí bảo hiểm đến cửa khẩu nhập; thuế nhập khẩu = trị giá hải quan x thuế suất (bài mô phỏng 20%).",en:"Customs value = FOB price + freight + insurance to the port of import; import duty = customs value x duty rate (training rate 20%)."},context:{label:"TỜ KHAI NHÁP / TK-0942",metrics:[{label:{vi:"Giá FOB",en:"FOB price"},value:"12,000 USD"},{label:{vi:"Cước + bảo hiểm",en:"Freight + insurance"},value:"660 USD"},{label:{vi:"Thuế suất mô phỏng",en:"Training duty rate"},value:"20%"}]},crisis:{vi:"Phòng kinh doanh nhắn: “Khai mã 8509.40 cho thuế thấp hơn đi, hải quan ít khi kiểm tra lô nhỏ. Lô hàng phải thông quan trong chiều nay.”",en:"Sales messages you: “Declare 8509.40 to get a lower rate, customs rarely inspects small shipments. The goods must clear this afternoon.”"},options:{safe:{vi:"Khai đúng mã 8516.71 theo hồ sơ phân loại, giải trình bằng tài liệu kỹ thuật và báo trưởng phòng; nếu còn băn khoăn thì đề nghị xác định trước mã số.",en:"Declare the correct code 8516.71 per the classification file, support it with technical documents and inform the manager; request an advance ruling if doubt remains."},shortcut:{vi:"Khai mã 8509.40 cho kịp giờ, nếu bị kiểm tra thì khai bổ sung sau.",en:"Declare 8509.40 to meet the deadline and amend later if customs checks."},wait:{vi:"Tạm dừng khai báo và chờ kinh doanh tự quyết định mã HS.",en:"Stop filing and wait for Sales to decide the HS code."}},questions:{vi:["Vì sao chọn mã 8516.71 thay vì 8509.40? Hồ sơ nào chứng minh phân loại của bạn?","Trình bày cách tính trị giá hải quan và rủi ro nếu tính thuế trên giá FOB."],en:["Why did you choose 8516.71 instead of 8509.40? Which documents support your classification?","Explain how you calculated the customs value and the risk of computing duty on the FOB price."]},hints:{vi:["Đặt bản nháp cạnh phiếu phân loại HS và đánh dấu dòng mã số đang sai.","Cộng đủ FOB, cước và bảo hiểm trước khi nhân thuế suất ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi áp lực đổi mã HS phải được báo cáo, không được khai sai."],en:["Place the draft next to the HS classification sheet and flag the wrong code line.","Add FOB, freight and insurance before applying the rate in SOP 3.2.","Re-read SOP 4.2: any pressure to change the HS code must be escalated, never misdeclared."]}},learning:{summary:{vi:"Chuyên viên khai báo hải quan điện tử lập và nộp tờ khai xuất nhập khẩu trên hệ thống VNACCS/VCIS, phân loại hàng hóa theo mã HS, xác định trị giá hải quan, tính thuế và xử lý phản hồi của cơ quan hải quan. Công việc đòi hỏi đọc hiểu chứng từ thương mại, nắm chắc quy định và giữ hồ sơ đủ căn cứ để sẵn sàng kiểm tra sau thông quan.",en:"A customs declaration specialist prepares and submits import and export declarations on VNACCS/VCIS, classifies goods by HS code, determines customs value, calculates duties and handles customs feedback. The role requires reading trade documents, knowing the regulations and keeping a well-evidenced file ready for post-clearance audit."},responsibilities:{vi:["Kiểm tra bộ chứng từ: hợp đồng, hóa đơn, phiếu đóng gói, vận đơn, C/O trước khi khai.","Phân loại hàng hóa theo Danh mục HS và 6 quy tắc tổng quát giải thích.","Xác định trị giá hải quan, tính thuế nhập khẩu, thuế GTGT và các khoản thuế khác.","Truyền tờ khai, theo dõi phân luồng xanh, vàng, đỏ và phối hợp kiểm tra thực tế.","Lưu trữ hồ sơ, khai bổ sung đúng hạn và chuẩn bị cho kiểm tra sau thông quan."],en:["Check the document set: contract, invoice, packing list, bill of lading and C/O before filing.","Classify goods using the HS nomenclature and the six General Interpretative Rules.","Determine customs value and calculate import duty, VAT and other taxes.","Submit declarations, follow green, yellow and red channel results and coordinate physical inspections.","Archive files, file amendments on time and prepare for post-clearance audits."]},competencies:[{name:{vi:"Phân loại HS",en:"HS classification"},desc:{vi:"Áp dụng chú giải phần, chương và quy tắc tổng quát để chọn mã 8 số chính xác.",en:"Apply section and chapter notes plus the general rules to choose the correct 8-digit code."}},{name:{vi:"Trị giá hải quan",en:"Customs valuation"},desc:{vi:"Xác định trị giá giao dịch, các khoản phải cộng, được trừ và phương pháp thay thế khi cần.",en:"Determine transaction value, required additions and deductions, and fallback methods when needed."}},{name:{vi:"Đọc chứng từ thương mại",en:"Trade document review"},desc:{vi:"Phát hiện sai lệch giữa hóa đơn, phiếu đóng gói, vận đơn và hợp đồng.",en:"Spot discrepancies between invoice, packing list, bill of lading and contract."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Từ chối khai sai dù chịu áp lực, báo cáo rủi ro và lưu bằng chứng.",en:"Refuse misdeclaration under pressure, escalate risks and keep evidence."}},{name:{vi:"Phối hợp & giải trình",en:"Coordination & explanation"},desc:{vi:"Làm việc với hải quan, hãng tàu, kho bãi và giải trình rõ ràng bằng văn bản.",en:"Work with customs, carriers and warehouses and explain clearly in writing."}}],knowledge:{vi:["Luật Hải quan số 54/2014/QH13 và các nghị định hướng dẫn.","Thông tư 38/2015/TT-BTC (sửa đổi bởi Thông tư 39/2018/TT-BTC) về thủ tục hải quan.","Thông tư 39/2015/TT-BTC về trị giá hải quan hàng hóa xuất nhập khẩu.","Danh mục hàng hóa xuất nhập khẩu Việt Nam theo AHTN/HS 2022 và 6 quy tắc tổng quát.","Quy tắc xuất xứ trong các FTA (ATIGA, CPTPP, EVFTA) và các mẫu C/O tương ứng."],en:["Customs Law No. 54/2014/QH13 and its implementing decrees.","Circular 38/2015/TT-BTC (amended by Circular 39/2018/TT-BTC) on customs procedures.","Circular 39/2015/TT-BTC on customs valuation of imports and exports.","Vietnam's import-export nomenclature based on AHTN/HS 2022 and the six general rules.","Rules of origin under FTAs (ATIGA, CPTPP, EVFTA) and the matching C/O forms."]},tools:["VNACCS/VCIS","Phần mềm khai báo ECUS","Cổng Một cửa Quốc gia (VNSW)","Biểu thuế XNK điện tử","Microsoft Excel"],kpis:{vi:["Tỷ lệ tờ khai đúng ngay lần đầu, không phải khai bổ sung.","Thời gian thông quan trung bình mỗi lô.","Số lỗi phát hiện khi kiểm tra sau thông quan (mục tiêu bằng 0).","Tỷ lệ hồ sơ lưu trữ đầy đủ, tra cứu được trong 5 phút."],en:["Right-first-time declaration rate with no amendments.","Average clearance time per shipment.","Errors found in post-clearance audits (target zero).","Share of complete files retrievable within 5 minutes."]},day:[{time:"08:00",vi:"Rà soát chứng từ lô hàng đến cảng hôm nay, đối chiếu hóa đơn với phiếu đóng gói.",en:"Review documents for today's arrivals and match invoices with packing lists."},{time:"10:00",vi:"Phân loại mã HS cho mặt hàng mới, lập bảng tính trị giá và thuế.",en:"Classify a new item, build the valuation and duty worksheet."},{time:"13:30",vi:"Truyền tờ khai, nhận kết quả phân luồng và chuẩn bị hồ sơ giải trình.",en:"Submit declarations, receive channel results and prepare explanations."},{time:"15:30",vi:"Phối hợp kiểm tra thực tế hàng hóa tại kho với đội hiện trường.",en:"Coordinate a physical inspection at the warehouse with the field team."},{time:"17:00",vi:"Cập nhật sổ theo dõi tờ khai và lưu hồ sơ điện tử.",en:"Update the declaration log and archive the electronic file."}],mistakes:{vi:["Tính thuế trên giá FOB mà quên cộng cước và bảo hiểm.","Chọn mã HS theo tên thương mại thay vì theo cấu tạo, công dụng và chú giải.","Đổi mã HS theo yêu cầu kinh doanh để giảm thuế, dẫn tới truy thu và xử phạt."],en:["Computing duty on the FOB price without adding freight and insurance.","Choosing an HS code from the trade name instead of composition, function and notes.","Changing the HS code at Sales' request to cut duty, leading to back taxes and penalties."]},career:[{vi:"Nhân viên chứng từ hải quan",en:"Customs documentation assistant"},{vi:"Chuyên viên khai báo hải quan",en:"Customs declaration specialist"},{vi:"Trưởng nhóm tuân thủ hải quan",en:"Customs compliance team lead"},{vi:"Quản lý xuất nhập khẩu & tuân thủ thương mại",en:"Trade compliance & import-export manager"}],glossary:[{term:"HS code",vi:"Mã số phân loại hàng hóa theo Hệ thống hài hòa của Tổ chức Hải quan Thế giới.",en:"Goods classification code under the World Customs Organization Harmonized System."},{term:"CIF",vi:"Điều kiện giao hàng gồm giá hàng, phí bảo hiểm và cước vận tải đến cảng đích.",en:"Delivery term covering cost, insurance and freight to the destination port."},{term:"VNACCS/VCIS",vi:"Hệ thống thông quan tự động và cơ sở dữ liệu thông tin nghiệp vụ của Hải quan Việt Nam.",en:"Vietnam Customs automated clearance system and intelligence database."},{term:"Phân luồng",vi:"Kết quả xử lý tờ khai: xanh (thông quan), vàng (kiểm tra hồ sơ), đỏ (kiểm tra thực tế).",en:"Declaration routing result: green (cleared), yellow (document check), red (physical inspection)."},{term:"C/O",vi:"Giấy chứng nhận xuất xứ hàng hóa, căn cứ hưởng thuế suất ưu đãi theo hiệp định.",en:"Certificate of origin used to claim preferential FTA duty rates."}],quiz:[{q:{vi:"Trị giá hải quan hàng nhập khẩu thường gồm những khoản nào?",en:"What does the customs value of imported goods usually include?"},options:{vi:["Chỉ giá FOB","Giá FOB + cước + bảo hiểm đến cửa khẩu nhập","Giá bán lẻ tại Việt Nam","Giá FOB trừ chiết khấu thương mại"],en:["FOB price only","FOB price + freight + insurance to the port of import","Retail price in Vietnam","FOB price minus trade discount"]},answer:1,explain:{vi:"Trị giá giao dịch phải cộng các chi phí vận chuyển và bảo hiểm đến cửa khẩu nhập đầu tiên.",en:"Transaction value must include transport and insurance costs to the first port of import."}},{q:{vi:"Căn cứ ưu tiên khi phân loại mã HS là gì?",en:"What takes priority when classifying an HS code?"},options:{vi:["Tên hàng trên hóa đơn","Chú giải phần, chương và nội dung nhóm","Mã HS nhà cung cấp gợi ý","Mã có thuế suất thấp nhất"],en:["The name on the invoice","Section and chapter notes and heading texts","The code suggested by the supplier","The code with the lowest rate"]},answer:1,explain:{vi:"Quy tắc 1 yêu cầu phân loại theo nội dung nhóm và chú giải phần, chương.",en:"Rule 1 requires classification by heading texts and section or chapter notes."}},{q:{vi:"Tờ khai bị phân luồng đỏ nghĩa là gì?",en:"What does a red channel result mean?"},options:{vi:["Được thông quan ngay","Kiểm tra hồ sơ giấy","Kiểm tra thực tế hàng hóa","Tờ khai bị hủy"],en:["Immediate clearance","Paper document check","Physical inspection of goods","Declaration cancelled"]},answer:2,explain:{vi:"Luồng đỏ yêu cầu kiểm tra hồ sơ và kiểm tra thực tế hàng hóa.",en:"The red channel requires both document and physical inspection."}},{q:{vi:"Kinh doanh yêu cầu khai mã HS thuế thấp hơn để kịp giờ. Bạn làm gì?",en:"Sales asks you to declare a lower-duty HS code to save time. What do you do?"},options:{vi:["Làm theo rồi khai bổ sung sau","Khai đúng mã, giải trình và báo cáo cấp trên","Bỏ qua và chờ hết giờ","Hỏi hãng tàu chọn mã"],en:["Comply and amend later","Declare the correct code, document it and escalate","Ignore it until the deadline","Ask the carrier to choose the code"]},answer:1,explain:{vi:"Khai sai mã để giảm thuế là vi phạm; phải khai đúng, lưu căn cứ và báo cáo áp lực.",en:"Misdeclaring to cut duty is a violation; declare correctly, keep evidence and escalate the pressure."}}]}},"KK-203":{scenario:{company:"Bluewave Home Appliances",supervisor:{name:"Tạ Minh Khoa",role:{vi:"Trưởng phòng Mua hàng Quốc tế",en:"Head of Global Sourcing"}},ref_code:"PO-4471",title:{vi:"Đúng Incoterms. Đúng bậc giá. Đúng giá trị PO.",en:"Right Incoterms. Right price break. Right PO value."},brief:{vi:"Bạn lập đơn đặt hàng PO-4471 mua 6400 bộ linh kiện từ nhà cung cấp nước ngoài. Hàng đóng container; người bán làm thủ tục xuất khẩu và giao cho hãng vận tải do người mua chỉ định tại cảng cạn (ICD) gần nhà máy. Báo giá: dưới 5000 bộ 2,40 USD/bộ; từ 5000 bộ 2,15 USD/bộ; phí khuôn một lần 1200 USD. Bản nháp ghi FOB và đơn giá 2,40 USD. Hãy sửa điều kiện giao hàng và giá trị PO, rồi lập báo cáo có căn cứ.",en:"You are raising purchase order PO-4471 for 6400 component sets from an overseas supplier. Goods are containerized; the seller clears export and hands over to the buyer's nominated carrier at the inland container depot (ICD) near the factory. Quote: under 5000 sets 2.40 USD/set; 5000 sets or more 2.15 USD/set; one-time tooling 1200 USD. The draft shows FOB and 2.40 USD. Correct the Incoterm and the PO value, then write an evidence-based report."},reference_title:{vi:"Quyết định chọn nhà cung cấp & báo giá đã duyệt · PO-4471",en:"Approved supplier award & quotation · PO-4471"},fields:[{id:"INCOTERM",label:{vi:"Điều kiện giao hàng (Incoterms 2020)",en:"Delivery term (Incoterms 2020)"},initial:"FOB",expected:"FCA",choices:["EXW","FOB","FCA"],reference:"Quyết định chọn nhà cung cấp đã duyệt",ref_value:{vi:"Hàng container; người bán thông quan xuất khẩu và giao cho người chuyên chở tại ICD",en:"Containerized; the seller clears export and delivers to the carrier at the ICD"},hint:{vi:"Xác định điểm chuyển giao rủi ro thực tế: khi hàng lên tàu hay khi giao cho người chuyên chở tại ICD.",en:"Find where risk actually passes: on board the vessel or on handover to the carrier at the ICD."}},{id:"PO_VALUE",label:{vi:"Giá trị PO (USD)",en:"PO value (USD)"},initial:"15360",expected:"14960",reference:"Báo giá nhà cung cấp đã duyệt",ref_value:{vi:"Số lượng 6400 bộ; dưới 5000: 2,40; từ 5000: 2,15 USD/bộ; phí khuôn 1200 USD",en:"Quantity 6400 sets; under 5000: 2.40; 5000 or more: 2.15 USD/set; tooling 1200 USD"},hint:{vi:"Chọn đúng bậc giá theo tổng số lượng của PO và cộng các khoản phí một lần đã thỏa thuận.",en:"Pick the price break for the total PO quantity and add agreed one-time charges."}}],sop32:{vi:"Giá trị PO = số lượng x đơn giá theo bậc số lượng áp dụng cho toàn bộ đơn hàng + phí một lần (khuôn, mẫu) theo báo giá đã duyệt.",en:"PO value = quantity x unit price of the applicable volume break for the whole order + one-time charges (tooling, samples) in the approved quote."},context:{label:"ERP / PO-4471",metrics:[{label:{vi:"Số lượng đặt",en:"Order quantity"},value:"6,400"},{label:{vi:"Đơn giá từ 5000 bộ",en:"Unit price from 5000"},value:"2.15 USD"},{label:{vi:"Phí khuôn một lần",en:"One-time tooling"},value:"1,200 USD"}]},crisis:{vi:"Đại diện nhà cung cấp nhắn riêng: “Nếu chị duyệt PO này và các đơn sau cho bên em, em gửi chị 2% giá trị vào tài khoản cá nhân. Đối thủ chào rẻ hơn nhưng chị cứ báo là họ không đạt kỹ thuật.”",en:"The supplier's rep messages you privately: “If you approve this PO and future ones for us, I will send 2% of the value to your personal account. The rival quoted lower, but just say they failed the technical check.”"},options:{safe:{vi:"Từ chối, lưu bằng chứng tin nhắn, báo Trưởng phòng Mua hàng và Tuân thủ; đánh giá lại nhà cung cấp minh bạch theo tiêu chí đã duyệt và khai báo xung đột lợi ích.",en:"Refuse, keep the message as evidence, report to the Head of Sourcing and Compliance; re-evaluate suppliers transparently on approved criteria and declare the conflict of interest."},shortcut:{vi:"Nhận 2% và duyệt PO vì giá chênh lệch giữa hai bên không nhiều.",en:"Take the 2% and approve the PO since the price gap is small."},wait:{vi:"Không trả lời, để PO treo đến khi cấp trên hỏi tới.",en:"Do not reply and leave the PO pending until management asks."}},questions:{vi:["Vì sao điều kiện giao hàng phải là FCA và giá trị PO đúng là 14960 USD? Hãy dẫn báo giá và quyết định chọn nhà cung cấp.","Đề nghị 2% của nhà cung cấp vi phạm nguyên tắc nào và bạn bảo vệ tính minh bạch của quy trình mua hàng ra sao?"],en:["Why must the delivery term be FCA and why is the correct PO value 14960 USD? Cite the quote and the supplier award.","Which principles does the supplier's 2% offer breach and how do you protect the transparency of the sourcing process?"]},hints:{vi:["Xác định nơi người bán giao hàng cho người chuyên chở trong quyết định chọn nhà cung cấp.","Tra bậc giá theo tổng số lượng 6400 bộ rồi cộng phí một lần ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải từ chối và báo cáo bằng văn bản."],en:["Find where the seller hands goods to the carrier in the supplier award.","Look up the price break for the total 6400 sets, then add one-time charges per SOP 3.2.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên mua hàng quốc tế tìm kiếm, đánh giá và lựa chọn nhà cung cấp nước ngoài, đàm phán giá, Incoterms, điều khoản thanh toán, chất lượng và tiến độ, lập đơn đặt hàng và theo dõi đến khi hàng về kho. Nghề tạo lợi thế chi phí và nguồn cung ổn định cho doanh nghiệp, đòi hỏi hiểu tổng chi phí sở hữu (TCO), thương mại quốc tế, ngoại ngữ và tính liêm chính tuyệt đối.",en:"An international purchasing officer finds, evaluates and selects overseas suppliers, negotiates price, Incoterms, payment terms, quality and lead time, raises purchase orders and follows them until goods reach the warehouse. The role gives the company a cost edge and a stable supply, and requires a grasp of total cost of ownership (TCO), international trade, languages and absolute integrity."},responsibilities:{vi:["Tìm kiếm nguồn hàng, gửi yêu cầu báo giá (RFQ) và so sánh nhà cung cấp.","Đánh giá năng lực, chất lượng, tài chính và rủi ro của nhà cung cấp.","Đàm phán giá, bậc số lượng, Incoterms, thanh toán và thời gian giao hàng.","Lập đơn đặt hàng, hợp đồng và theo dõi tiến độ sản xuất, vận chuyển.","Xử lý sai lệch chất lượng, khiếu nại và đánh giá định kỳ nhà cung cấp."],en:["Source products, issue requests for quotation (RFQ) and compare suppliers.","Assess supplier capability, quality, finances and risk.","Negotiate price, volume breaks, Incoterms, payment and lead time.","Raise purchase orders and contracts and track production and shipping.","Handle quality deviations and claims and review suppliers periodically."]},competencies:[{name:{vi:"Đánh giá tổng chi phí",en:"Total cost evaluation"},desc:{vi:"So sánh nhà cung cấp theo TCO: giá, vận chuyển, thuế, chất lượng, rủi ro và vòng đời.",en:"Compare suppliers on TCO: price, freight, duties, quality, risk and life cycle."}},{name:{vi:"Incoterms & thương mại quốc tế",en:"Incoterms & international trade"},desc:{vi:"Chọn điều kiện giao hàng khớp phương thức vận tải và năng lực thông quan của các bên.",en:"Choose delivery terms matching the transport mode and each party's clearance capability."}},{name:{vi:"Đàm phán",en:"Negotiation"},desc:{vi:"Chuẩn bị phương án thay thế, tận dụng bậc số lượng và điều khoản thanh toán có lợi.",en:"Prepare alternatives and use volume breaks and favourable payment terms."}},{name:{vi:"Quản lý nhà cung cấp",en:"Supplier management"},desc:{vi:"Theo dõi chất lượng, giao hàng đúng hạn và phát triển nhà cung cấp chiến lược.",en:"Track quality and on-time delivery and develop strategic suppliers."}},{name:{vi:"Liêm chính mua hàng",en:"Procurement integrity"},desc:{vi:"Từ chối hoa hồng, quà tặng, khai báo xung đột lợi ích và chấm điểm minh bạch.",en:"Refuse kickbacks and gifts, declare conflicts and score bids transparently."}}],knowledge:{vi:["Incoterms 2020 của ICC: 11 điều kiện, điểm chuyển giao rủi ro và phân chia chi phí.","Tổng chi phí sở hữu (TCO) và giá vốn nhập kho: giá mua, vận chuyển, bảo hiểm, thuế, lưu kho, chất lượng.","Công ước Viên 1980 (CISG) về hợp đồng mua bán hàng hóa quốc tế, có hiệu lực với Việt Nam từ 01/01/2017.","Phương thức thanh toán quốc tế T/T, D/P, D/A, L/C và rủi ro tương ứng.","ISO 9001 và tiêu chí đánh giá, phê duyệt nhà cung cấp.","Quy tắc ứng xử mua hàng: xung đột lợi ích, quà tặng, phòng chống hối lộ."],en:["ICC Incoterms 2020: 11 rules, transfer of risk and allocation of costs.","Total cost of ownership (TCO) and landed cost: price, freight, insurance, duties, storage and quality.","The 1980 Vienna Convention (CISG) on international sale of goods, in force for Vietnam since 1 January 2017.","International payment methods T/T, D/P, D/A, L/C and their risks.","ISO 9001 and supplier evaluation and approval criteria.","Procurement code of conduct: conflicts of interest, gifts and anti-bribery."]},tools:["ERP purchasing module","e-Sourcing / RFQ platform","Supplier scorecard","Landed cost calculator","Contract management system","Shipment tracking portal"],kpis:{vi:["Mức tiết kiệm chi phí so với ngân sách hoặc giá cơ sở.","Tỷ lệ giao hàng đúng hạn, đủ số lượng của nhà cung cấp.","Tỷ lệ lô hàng đạt chất lượng ngay lần kiểm tra đầu.","Tỷ lệ PO có sai lệch giá, điều kiện so với báo giá đã duyệt (mục tiêu bằng 0)."],en:["Cost savings versus budget or baseline price.","Supplier on-time, in-full delivery rate.","Share of lots passing first inspection.","Share of POs deviating from the approved quote (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra email nhà cung cấp ở các múi giờ khác và cập nhật tiến độ đơn hàng.",en:"Check supplier emails from other time zones and update order status."},{time:"09:30",vi:"So sánh báo giá RFQ mới theo tổng chi phí sở hữu.",en:"Compare new RFQ quotes on total cost of ownership."},{time:"11:00",vi:"Đàm phán qua video với nhà cung cấp về bậc giá và thời gian giao.",en:"Negotiate price breaks and lead time on a video call with a supplier."},{time:"14:00",vi:"Lập và trình duyệt PO, kiểm tra Incoterms và điều khoản thanh toán.",en:"Raise and submit POs, checking Incoterms and payment terms."},{time:"16:00",vi:"Phối hợp kho, chất lượng và logistics về lô hàng sắp về.",en:"Coordinate with warehouse, quality and logistics on incoming shipments."}],mistakes:{vi:["Dùng FOB cho hàng container giao cho người chuyên chở tại ICD, sai điểm chuyển giao rủi ro.","Áp đơn giá bậc thấp dù tổng số lượng đã đạt bậc giá ưu đãi, hoặc quên phí khuôn mẫu.","Chọn nhà cung cấp chỉ theo đơn giá mà bỏ qua vận chuyển, thuế, chất lượng và rủi ro."],en:["Using FOB for containers handed to the carrier at an ICD, misplacing the risk transfer.","Applying the small-quantity price when the total qualifies for a better break, or forgetting tooling.","Choosing suppliers on unit price alone, ignoring freight, duties, quality and risk."]},career:[{vi:"Nhân viên mua hàng",en:"Purchasing assistant"},{vi:"Chuyên viên mua hàng quốc tế",en:"International purchasing officer"},{vi:"Trưởng nhóm tìm nguồn chiến lược",en:"Strategic sourcing lead"},{vi:"Giám đốc Mua hàng / Chuỗi cung ứng",en:"Procurement or supply chain director"}],glossary:[{term:"Incoterms",vi:"Bộ quy tắc của ICC xác định nghĩa vụ, chi phí và điểm chuyển rủi ro giữa người bán và người mua.",en:"ICC rules defining duties, costs and the risk transfer point between seller and buyer."},{term:"FCA",vi:"Giao cho người chuyên chở: người bán thông quan xuất khẩu và giao hàng cho người chuyên chở tại địa điểm chỉ định.",en:"Free Carrier: the seller clears export and delivers to the carrier at the named place."},{term:"TCO",vi:"Tổng chi phí sở hữu: toàn bộ chi phí mua, vận chuyển, thuế, lưu kho, chất lượng và vận hành.",en:"Total cost of ownership: all purchase, freight, duty, storage, quality and running costs."},{term:"Price break",vi:"Bậc giá theo số lượng: đơn giá thấp hơn khi tổng số lượng đặt đạt ngưỡng.",en:"A volume tier where the unit price drops once the order reaches a threshold."},{term:"RFQ",vi:"Yêu cầu báo giá gửi nhiều nhà cung cấp với cùng thông số để so sánh công bằng.",en:"Request for quotation sent to several suppliers with the same specs for fair comparison."}],quiz:[{q:{vi:"Hàng container được người bán giao cho người chuyên chở tại ICD. Theo Incoterms 2020 nên dùng điều kiện nào?",en:"Containers are handed to the carrier at an ICD. Which Incoterms 2020 rule fits?"},options:{vi:["FOB","CFR","FCA","EXW"],en:["FOB","CFR","FCA","EXW"]},answer:2,explain:{vi:"ICC khuyến nghị FCA cho hàng container giao cho người chuyên chở trước khi lên tàu; FOB dành cho hàng giao lên tàu.",en:"ICC recommends FCA for containers handed to the carrier before loading; FOB is for goods delivered on board."}},{q:{vi:"Đặt 8000 cái; dưới 5000 cái 1,20 USD; từ 5000 cái 1,05 USD; phí mẫu 300 USD. Giá trị PO là bao nhiêu?",en:"Order 8000 pieces; under 5000 at 1.20 USD; 5000 or more at 1.05 USD; sample fee 300 USD. What is the PO value?"},options:{vi:["9900 USD","8700 USD","8400 USD","9600 USD"],en:["9900 USD","8700 USD","8400 USD","9600 USD"]},answer:1,explain:{vi:"Giá trị PO = 8000 x 1,05 + 300 = 8700 USD.",en:"PO value = 8000 x 1.05 + 300 = 8700 USD."}},{q:{vi:"Tổng chi phí sở hữu (TCO) khác giá mua ở điểm nào?",en:"How does total cost of ownership (TCO) differ from purchase price?"},options:{vi:["Tính thêm vận chuyển, thuế, lưu kho, chất lượng và chi phí vòng đời","Chỉ là giá sau chiết khấu","Chỉ gồm giá FOB","Không tính chi phí chất lượng"],en:["It adds freight, duties, storage, quality and life cycle costs","It is just the discounted price","It is only the FOB price","It excludes quality costs"]},answer:0,explain:{vi:"TCO phản ánh toàn bộ chi phí phát sinh từ khi mua đến hết vòng đời sử dụng.",en:"TCO captures every cost from purchase to the end of the item's life."}},{q:{vi:"Nhà cung cấp mời bạn đi du lịch miễn phí ngay trước kỳ chấm thầu. Bạn làm gì?",en:"A supplier offers you a free trip right before bid evaluation. What do you do?"},options:{vi:["Nhận vì không ảnh hưởng kết quả","Nhận nhưng không kể với ai","Đi rồi chấm điểm công bằng","Từ chối, khai báo theo quy tắc quà tặng và báo cấp trên"],en:["Accept since it changes nothing","Accept but tell no one","Go and still score fairly","Decline, declare it under the gifts rule and inform your manager"]},answer:3,explain:{vi:"Quà tặng trong giai đoạn lựa chọn nhà cung cấp tạo xung đột lợi ích và phải được từ chối, khai báo.",en:"Gifts during supplier selection create a conflict of interest and must be declined and declared."}}]}},"KK-204":{scenario:{company:"Seabridge Logistics",supervisor:{name:"Lý Văn Tâm",role:{vi:"Trưởng bộ phận Hiện trường Cảng",en:"Port Field Operations Lead"}},ref_code:"BKG-6618",title:{vi:"Đúng loại container. Đúng VGM. Đúng niêm phong.",en:"Right container type. Right VGM. Right seal."},brief:{vi:"Bạn phụ trách hiện trường lô xuất khẩu BKG-6618 tại cảng. Container thực tế là loại 40 feet cao (high cube) hàng khô, biển CSC ghi trọng lượng vỏ 3880 kg. Hàng gồm 2150 thùng tổng 17760 kg, pallet và vật liệu chèn lót 540 kg. Hãng tàu yêu cầu VGM theo phương pháp 2 của SOLAS. Bản nháp khai mã kích thước - loại 42G1 và VGM chưa gồm vỏ container. Hãy sửa hai trường trước giờ cắt máng và lập báo cáo có căn cứ.",en:"You are the field officer for export booking BKG-6618 at the port. The actual container is a 40-foot high cube dry box; its CSC plate shows a tare of 3880 kg. Cargo is 2150 cartons totalling 17760 kg, with 540 kg of pallets and dunnage. The carrier requires VGM under SOLAS method 2. The draft declares size-type code 42G1 and a VGM without the container tare. Correct both fields before cut-off and write an evidence-based report."},reference_title:{vi:"Phiếu EIR, biển CSC & phiếu cân đã xác nhận · BKG-6618",en:"Confirmed EIR, CSC plate & weighing slips · BKG-6618"},fields:[{id:"ISO_TYPE",label:{vi:"Mã kích thước - loại container (ISO 6346)",en:"Container size-type code (ISO 6346)"},initial:"42G1",expected:"45G1",choices:["22G1","42G1","45G1"],reference:"Phiếu giao nhận container (EIR)",ref_value:{vi:"Dài 40 feet, cao 9 feet 6 inch (high cube), container hàng khô thông dụng",en:"40 feet long, 9 feet 6 inches high (high cube), general purpose dry container"},hint:{vi:"Ký tự đầu của mã là chiều dài, ký tự thứ hai là chiều cao: 2 là 8 feet 6 inch, 5 là 9 feet 6 inch.",en:"The first character is length and the second is height: 2 means 8 feet 6 inches, 5 means 9 feet 6 inches."}},{id:"VGM_KG",label:{vi:"VGM khai báo (kg)",en:"Declared VGM (kg)"},initial:"18300",expected:"22180",reference:"Phiếu cân hàng và biển CSC",ref_value:{vi:"Hàng 17760 kg; pallet, chèn lót 540 kg; vỏ theo biển CSC 3880 kg",en:"Cargo 17760 kg; pallets and dunnage 540 kg; CSC plate tare 3880 kg"},hint:{vi:"Phương pháp 2 cộng toàn bộ hàng, vật liệu đóng gói, chèn lót và trọng lượng vỏ container.",en:"Method 2 adds all cargo, packing, dunnage and the container tare."}}],sop32:{vi:"VGM (phương pháp 2) = khối lượng hàng + pallet, vật liệu đóng gói, chèn lót + trọng lượng vỏ container theo biển CSC; VGM phải gửi hãng tàu trước giờ cắt máng.",en:"VGM (method 2) = cargo mass + pallets, packing and dunnage + container tare per the CSC plate; submit VGM to the carrier before cut-off."},context:{label:"PORT OPS / BKG-6618",metrics:[{label:{vi:"Vỏ container theo CSC",en:"CSC plate tare"},value:"3,880 kg"},{label:{vi:"Khối lượng hàng",en:"Cargo mass"},value:"17,760 kg"},{label:{vi:"Pallet và chèn lót",en:"Pallets & dunnage"},value:"540 kg"}]},crisis:{vi:"Chủ hàng gọi: “Container đã kiểm hóa và niêm phong rồi. Em cắt seal cho bên anh đóng thêm 120 thùng chưa khai, bấm seal mới rồi hạ bãi luôn, tờ khai để sau tính.”",en:"The shipper calls: “The container has been inspected and sealed. Cut the seal so we can load 120 more undeclared cartons, fit a new seal and send it to the yard. We will deal with the declaration later.”"},options:{safe:{vi:"Từ chối cắt seal, báo Trưởng bộ phận hiện trường; nếu cần bổ sung hàng thì làm thủ tục khai bổ sung hoặc tờ khai mới theo quy định và cập nhật VGM trước khi hạ bãi.",en:"Refuse to cut the seal and inform the field operations lead; if cargo must be added, file an amendment or a new declaration as required and update the VGM before gate-in."},shortcut:{vi:"Cắt seal, đóng thêm hàng và bấm seal mới cho kịp tàu.",en:"Cut the seal, add the cargo and fit a new seal to make the vessel."},wait:{vi:"Không xử lý, để container nằm ngoài bãi chờ chủ hàng tự lo.",en:"Do nothing and leave the container outside the yard for the shipper to sort out."}},questions:{vi:["Vì sao mã đúng là 45G1 và VGM là 22180 kg? Hãy dẫn phiếu EIR, biển CSC, phiếu cân và yêu cầu SOLAS.","Cắt seal để đóng thêm hàng chưa khai gây rủi ro pháp lý, an toàn gì và bạn báo cáo cho ai?"],en:["Why is the correct code 45G1 and the VGM 22180 kg? Cite the EIR, the CSC plate, the weighing slips and the SOLAS rule.","What legal and safety risks arise from cutting the seal to load undeclared cargo, and whom do you report to?"]},hints:{vi:["Đối chiếu chiều dài, chiều cao container thực tế trên EIR với cấu trúc mã ISO 6346.","Cộng đủ ba thành phần khối lượng theo phương pháp 2 ở SOP mục 3.2.","Đọc SOP mục 4.2: không cắt seal hay thay đổi hàng sau kiểm hóa khi chưa có thủ tục hợp lệ."],en:["Match the actual length and height on the EIR with the ISO 6346 code structure.","Add all three mass components under method 2 in SOP 3.2.","Re-read SOP 4.2: never cut a seal or change cargo after inspection without a valid procedure."]}},learning:{summary:{vi:"Chuyên viên hiện trường xuất nhập khẩu đại diện doanh nghiệp tại cảng, cửa khẩu, kho bãi: làm thủ tục giao nhận container, phối hợp kiểm hóa với hải quan, kiểm tra seal, VGM, chứng từ lấy hàng, thanh lý tờ khai và xử lý sự cố phát sinh. Nghề giúp hàng thông quan và lên tàu đúng giờ, đòi hỏi am hiểu thủ tục hải quan, vận tải container, khả năng ứng biến và nguyên tắc liêm chính tại hiện trường.",en:"A customs clearance field officer represents the company at ports, border gates and depots: handling container interchange, coordinating customs inspections, checking seals, VGM and release documents, finalising declarations and solving incidents on the spot. The role gets cargo cleared and loaded on time and requires knowledge of customs procedures and container transport, quick thinking and integrity in the field."},responsibilities:{vi:["Nhận lệnh cấp container, kiểm tra tình trạng vỏ, mã ISO và biển CSC.","Giám sát đóng hàng, niêm phong và đối chiếu số seal với chứng từ.","Gửi VGM, hạ bãi container đúng giờ cắt máng của hãng tàu.","Xuất trình hồ sơ, phối hợp kiểm hóa và xử lý yêu cầu của hải quan tại hiện trường.","Lấy hàng nhập, thanh lý tờ khai và báo cáo sự cố cho bộ phận chứng từ."],en:["Collect empty containers and check condition, ISO code and CSC plate.","Supervise stuffing and sealing and match seal numbers with documents.","Submit the VGM and gate in containers before the carrier's cut-off.","Present files, coordinate inspections and handle customs requests on site.","Collect import cargo, finalise declarations and report incidents to the documentation team."]},competencies:[{name:{vi:"Nghiệp vụ container",en:"Container know-how"},desc:{vi:"Đọc mã ISO 6346, biển CSC, phân biệt loại container và kiểm tra tình trạng vỏ.",en:"Read ISO 6346 codes and CSC plates, tell container types apart and inspect boxes."}},{name:{vi:"Thủ tục hải quan hiện trường",en:"Field customs procedures"},desc:{vi:"Nắm quy trình phân luồng, kiểm hóa, giám sát và thanh lý tờ khai tại cảng.",en:"Know channel routing, inspection, supervision and declaration finalisation at the port."}},{name:{vi:"Chính xác số liệu",en:"Data accuracy"},desc:{vi:"Ghi đúng số container, số seal, VGM và đối chiếu với booking, tờ khai.",en:"Record container numbers, seal numbers and VGM correctly against booking and declaration."}},{name:{vi:"Xử lý sự cố",en:"Incident handling"},desc:{vi:"Bình tĩnh xử lý container hỏng, sai seal, trễ cắt máng và báo cáo kịp thời.",en:"Calmly handle damaged boxes, seal mismatches and late cut-offs and report promptly."}},{name:{vi:"Liêm chính hiện trường",en:"Field integrity"},desc:{vi:"Từ chối cắt seal, thêm bớt hàng hay đưa lợi ích trái quy định để kịp tàu.",en:"Refuse to cut seals, add or remove cargo or offer improper benefits to catch a vessel."}}],knowledge:{vi:["Luật Hải quan số 54/2014/QH13 và quy định về kiểm tra, giám sát hải quan tại cảng.","Công ước SOLAS chương VI quy định 2 về khối lượng toàn bộ container đã xác minh (VGM), áp dụng từ 01/7/2016.","ISO 6346 về mã chủ sở hữu, số container, chữ số kiểm tra và mã kích thước - loại.","Công ước CSC về an toàn container và biển phê duyệt an toàn gắn trên vỏ.","ISO 17712 về seal cơ khí an ninh cho container.","Quy trình giao nhận tại cảng: EIR, lệnh giao hàng (D/O), cắt máng, hạ bãi, thanh lý tờ khai."],en:["Customs Law No. 54/2014/QH13 and rules on customs inspection and supervision at ports.","SOLAS Chapter VI Regulation 2 on verified gross mass (VGM), in force since 1 July 2016.","ISO 6346 on owner codes, container numbers, check digits and size-type codes.","The CSC Convention on safe containers and the safety approval plate.","ISO 17712 on mechanical security seals for containers.","Port interchange: EIR, delivery order (D/O), cut-off, gate-in and declaration finalisation."]},tools:["VNACCS/VCIS","Port e-portal & eDO","VGM submission portal","Seal & container photo app","Weighbridge ticket","Mobile document scanner"],kpis:{vi:["Tỷ lệ container hạ bãi kịp giờ cắt máng.","Số sai lệch số seal, mã container, VGM so với chứng từ (mục tiêu bằng 0).","Thời gian thông quan trung bình tại hiện trường.","Chi phí phát sinh do lưu container, lưu bãi vì lỗi hiện trường."],en:["Share of containers gated in before cut-off.","Seal, container code or VGM mismatches with documents (target zero).","Average field clearance time.","Demurrage and storage costs caused by field errors."]},day:[{time:"06:30",vi:"Nhận container rỗng tại depot, kiểm tra vỏ, mã ISO và biển CSC.",en:"Pick up empties at the depot and check the box, ISO code and CSC plate."},{time:"08:30",vi:"Giám sát đóng hàng tại kho, chụp ảnh và bấm seal.",en:"Supervise stuffing at the warehouse, take photos and fit the seal."},{time:"11:00",vi:"Gửi VGM cho hãng tàu và chuẩn bị hồ sơ kiểm hóa.",en:"Submit the VGM to the carrier and prepare inspection files."},{time:"14:00",vi:"Phối hợp hải quan kiểm hóa container luồng đỏ tại bãi.",en:"Coordinate customs inspection of a red channel container in the yard."},{time:"16:30",vi:"Hạ bãi trước cắt máng, thanh lý tờ khai và báo cáo cho văn phòng.",en:"Gate in before cut-off, finalise the declaration and report to the office."}],mistakes:{vi:["Khai 42G1 cho container high cube, làm sai kế hoạch xếp tàu và dữ liệu khai báo.","Khai VGM chỉ gồm hàng và bao bì, quên trọng lượng vỏ container.","Cắt seal đóng thêm hàng sau kiểm hóa theo yêu cầu chủ hàng mà không làm thủ tục."],en:["Declaring 42G1 for a high cube box, corrupting stowage plans and declaration data.","Declaring a VGM with cargo and packing only, forgetting the container tare.","Cutting a seal to add cargo after inspection at the shipper's request without any procedure."]},career:[{vi:"Nhân viên giao nhận hiện trường",en:"Field forwarding assistant"},{vi:"Chuyên viên hiện trường xuất nhập khẩu",en:"Customs clearance field officer"},{vi:"Trưởng nhóm hiện trường cảng",en:"Port field team lead"},{vi:"Quản lý vận hành giao nhận & hải quan",en:"Forwarding & customs operations manager"}],glossary:[{term:"VGM",vi:"Khối lượng toàn bộ container đã xác minh, gồm hàng, vật liệu đóng gói và vỏ container.",en:"Verified gross mass of a packed container, including cargo, packing and tare."},{term:"CSC plate",vi:"Biển phê duyệt an toàn trên vỏ container, ghi trọng lượng vỏ và tổng trọng lượng tối đa.",en:"The safety approval plate on a container showing tare and maximum gross mass."},{term:"ISO 6346",vi:"Tiêu chuẩn mã hóa container: mã chủ sở hữu, số sê-ri, chữ số kiểm tra và mã kích thước - loại.",en:"The container coding standard: owner code, serial number, check digit and size-type code."},{term:"EIR",vi:"Phiếu giao nhận container ghi tình trạng vỏ, số seal khi container ra vào cảng, depot.",en:"Equipment interchange receipt recording box condition and seal number at each gate move."},{term:"Cut-off",vi:"Giờ cắt máng: thời hạn cuối hạ container, gửi VGM và chứng từ trước khi tàu chạy.",en:"The deadline to gate in containers and send VGM and documents before sailing."}],quiz:[{q:{vi:"Mã 22G1 theo ISO 6346 là loại container nào?",en:"Which container does ISO 6346 code 22G1 describe?"},options:{vi:["Container 40 feet cao","Container 20 feet hàng khô thông dụng, cao 8 feet 6 inch","Container lạnh 40 feet","Container mở nóc 20 feet"],en:["A 40-foot high cube","A 20-foot general purpose dry box, 8 feet 6 inches high","A 40-foot reefer","A 20-foot open top"]},answer:1,explain:{vi:"Ký tự 2 đầu tiên là 20 feet, ký tự 2 thứ hai là cao 8 feet 6 inch, G1 là container hàng khô thông dụng.",en:"The first 2 means 20 feet, the second 2 means 8 feet 6 inches high, and G1 is a general purpose dry box."}},{q:{vi:"Hàng 12000 kg, pallet 300 kg, vỏ container 2200 kg. VGM theo phương pháp 2 là bao nhiêu?",en:"Cargo 12000 kg, pallets 300 kg, container tare 2200 kg. What is the VGM under method 2?"},options:{vi:["12300 kg","14200 kg","12000 kg","14500 kg"],en:["12300 kg","14200 kg","12000 kg","14500 kg"]},answer:3,explain:{vi:"VGM = hàng 12000 + pallet 300 + vỏ 2200 = 14500 kg.",en:"VGM = 12000 + 300 + 2200 = 14500 kg."}},{q:{vi:"Chủ hàng đề nghị cắt seal đóng thêm hàng chưa khai sau khi đã kiểm hóa. Bạn làm gì?",en:"The shipper asks you to cut the seal and add undeclared cargo after inspection. What do you do?"},options:{vi:["Từ chối, báo cấp trên và chỉ bổ sung hàng khi đã làm thủ tục hợp lệ","Làm theo cho kịp tàu","Cắt seal nhưng chụp ảnh lưu lại","Nhờ tài xế làm hộ"],en:["Refuse, inform your lead and add cargo only after a valid procedure","Comply to make the vessel","Cut the seal but keep photos","Ask the driver to do it"]},answer:0,explain:{vi:"Đóng thêm hàng chưa khai là vi phạm pháp luật hải quan và làm sai VGM, ảnh hưởng an toàn xếp tàu.",en:"Adding undeclared cargo breaches customs law and falsifies the VGM, endangering stowage safety."}},{q:{vi:"Theo SOLAS, ai chịu trách nhiệm cung cấp VGM cho hãng tàu?",en:"Under SOLAS, who is responsible for providing the VGM to the carrier?"},options:{vi:["Cảng vụ","Thuyền trưởng","Người gửi hàng có tên trên vận đơn","Cơ quan hải quan"],en:["The port authority","The ship's master","The shipper named on the bill of lading","The customs authority"]},answer:2,explain:{vi:"SOLAS quy định người gửi hàng ghi trên vận đơn có trách nhiệm xác minh và cung cấp VGM.",en:"SOLAS makes the shipper named on the bill of lading responsible for verifying and providing the VGM."}}]}},"KK-205":{scenario:{company:"Lam Sơn Road Freight",supervisor:{name:"Đỗ Thanh Tùng",role:{vi:"Trưởng bộ phận Điều phối Vận tải",en:"Fleet Dispatch Manager"}},ref_code:"TR-5318",title:{vi:"Đúng xe. Đúng tải. Đúng chi phí chuyến.",en:"Right truck. Right load. Right trip cost."},brief:{vi:"Bạn duyệt lệnh vận chuyển TR-5318: 10,4 tấn xi măng bao từ Hải Phòng đi Vinh, 320 km mỗi chiều, xe quay về rỗng. Đội xe khả dụng: TRUCK-8T (khối lượng hàng chuyên chở cho phép 7,8 tấn), TRUCK-11T (10,2 tấn), TRUCK-15T (14,5 tấn). Đối chiếu lệnh nháp với hồ sơ đã duyệt, sửa loại xe điều động và chi phí chuyến (VND, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are approving transport order TR-5318: 10.4 tonnes of bagged cement from Hai Phong to Vinh, 320 km each way, with an empty return. Available fleet: TRUCK-8T (permitted payload 7.8 t), TRUCK-11T (10.2 t), TRUCK-15T (14.5 t). Compare the draft order with the approved file, correct the assigned vehicle type and the trip cost (VND, simulated figures), then write an evidence-based report."},reference_title:{vi:"Hồ sơ điều xe & chi phí chuyến đã duyệt · TR-5318",en:"Approved dispatch & trip cost file · TR-5318"},fields:[{id:"VEH_CLASS",label:{vi:"Loại xe điều động",en:"Assigned vehicle type"},initial:"TRUCK-11T",expected:"TRUCK-15T",choices:["TRUCK-8T","TRUCK-11T","TRUCK-15T"],reference:"Giấy kiểm định & danh sách đội xe",ref_value:{vi:"Khối lượng hàng cho phép: 8T = 7,8 t; 11T = 10,2 t; 15T = 14,5 t",en:"Permitted payload: 8T = 7.8 t; 11T = 10.2 t; 15T = 14.5 t"},hint:{vi:"Tên gọi xe không phải tải trọng: so khối lượng hàng với khối lượng chuyên chở cho phép ghi trên giấy kiểm định.",en:"A truck's name is not its payload: compare the cargo weight with the permitted payload on the inspection certificate."}},{id:"TRIP_COST",label:{vi:"Chi phí chuyến (VND)",en:"Trip cost (VND)"},initial:"2412000",expected:"4312000",reference:"Bảng tính chi phí chuyến",ref_value:{vi:"320 km có hàng + 320 km rỗng; dầu 20000 đ/lít; phí đường bộ 620000 đ/chiều (mô phỏng)",en:"320 km loaded + 320 km empty; diesel 20000 VND/l; road tolls 620000 VND each way (simulated)"},hint:{vi:"Chuyến xe gồm cả chiều về rỗng: tính nhiên liệu theo từng định mức và cộng phí đường bộ hai chiều.",en:"A trip includes the empty return: apply each fuel norm separately and add tolls for both directions."}}],sop32:{vi:"Chi phí chuyến = (km có hàng x 28 + km rỗng x 20) / 100 x giá dầu + phí đường bộ cả hai chiều; định mức 28 và 20 lít/100 km là số liệu mô phỏng.",en:"Trip cost = (loaded km x 28 + empty km x 20) / 100 x diesel price + road tolls for both directions; the norms of 28 and 20 litres per 100 km are simulated."},context:{label:"TMS / TR-5318",metrics:[{label:{vi:"Khối lượng hàng",en:"Cargo weight"},value:"10.4 t"},{label:{vi:"Quãng đường mỗi chiều",en:"Distance each way"},value:"320 km"},{label:{vi:"Giá dầu mô phỏng",en:"Simulated diesel price"},value:"20,000 VND/l"}]},crisis:{vi:"Khách hàng gọi: “Dùng xe 11 tấn cho rẻ, lố 0,2 tấn không trạm cân nào bắt. Cho tài xế chạy thẳng một mạch, không nghỉ, 5 giờ sáng hàng phải có ở công trình.”",en:"The customer calls: “Use the 11-tonne truck, it is cheaper, 0.2 t over will not be caught at any weigh station. Have the driver go non-stop, the cement must be on site by 5 a.m.”"},options:{safe:{vi:"Từ chối chở quá tải, điều xe TRUCK-15T, lập lịch nghỉ cho tài xế đúng quy định thời gian lái xe, báo trưởng bộ phận và thông báo khách giờ giao điều chỉnh.",en:"Refuse to overload, assign TRUCK-15T, schedule driver rest per driving-time rules, inform the dispatch manager and give the customer a revised delivery time."},shortcut:{vi:"Dùng xe 11 tấn theo ý khách, dặn tài xế chạy đêm tránh trạm cân và không dừng nghỉ.",en:"Use the 11-tonne truck as the customer wants and tell the driver to run at night, avoid weigh stations and skip rest stops."},wait:{vi:"Chưa điều xe, để khách và tài xế tự thỏa thuận với nhau.",en:"Hold the dispatch and let the customer and the driver sort it out themselves."}},questions:{vi:["Vì sao điều xe TRUCK-15T thay vì TRUCK-11T? Số liệu nào trên giấy kiểm định chứng minh lựa chọn của bạn?","Trình bày cách tính chi phí chuyến và rủi ro pháp lý, an toàn nếu chở quá tải hoặc để tài xế lái quá thời gian cho phép."],en:["Why did you assign TRUCK-15T instead of TRUCK-11T? Which inspection certificate data supports your choice?","Explain how you calculated the trip cost and the legal and safety risks of overloading or letting the driver exceed driving-time limits."]},hints:{vi:["Đặt lệnh nháp cạnh giấy kiểm định và đánh dấu dòng loại xe đang vượt khối lượng cho phép.","Tách quãng có hàng và quãng rỗng, áp đúng định mức rồi cộng phí đường bộ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu chở quá tải hoặc lái quá giờ phải từ chối và báo cáo."],en:["Place the draft order next to the inspection certificate and flag the vehicle line that exceeds the permitted payload.","Split loaded and empty legs, apply the right norms, then add road tolls per SOP 3.2.","Re-read SOP 4.2: any request to overload or exceed driving hours must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên điều phối vận tải nội địa lập kế hoạch và điều động đội xe tải cho các đơn hàng đường bộ: chọn loại xe phù hợp khối lượng hàng cho phép, ghép chuyến, tối ưu tuyến, bố trí tài xế, theo dõi hành trình qua thiết bị giám sát và kiểm soát chi phí chuyến. Công việc đòi hỏi nắm chắc quy định về tải trọng, thời gian lái xe, kinh doanh vận tải và luôn đặt an toàn lên trước tiến độ.",en:"A domestic transport and fleet coordinator plans and dispatches trucks for road shipments: choosing the vehicle that fits the permitted payload, consolidating loads, optimizing routes, assigning drivers, tracking trips through telematics and controlling trip costs. The role requires solid knowledge of load limits, driving-time rules and road transport business regulations, and always puts safety ahead of deadlines."},responsibilities:{vi:["Tiếp nhận đơn hàng, kiểm tra khối lượng, thể tích, loại hàng và khung giờ giao nhận yêu cầu.","Chọn loại xe theo khối lượng hàng chuyên chở cho phép, ghép chuyến và tối ưu tuyến đường.","Bố trí tài xế, lập lịch nghỉ đúng quy định thời gian lái xe và cấp lệnh vận chuyển.","Theo dõi hành trình qua thiết bị giám sát, xử lý sự cố, trễ hẹn và thông báo khách hàng.","Tính và đối soát chi phí chuyến: nhiên liệu, phí đường bộ, bốc xếp; báo cáo hiệu suất đội xe."],en:["Receive orders and check weight, volume, cargo type and the required delivery windows.","Choose vehicles by permitted payload, consolidate loads and optimize routes.","Assign drivers, schedule rest breaks within driving-time rules and issue transport orders.","Track trips via telematics, handle incidents and delays, and keep customers informed.","Calculate and reconcile trip costs (fuel, tolls, handling) and report fleet performance."]},competencies:[{name:{vi:"Lập kế hoạch điều xe",en:"Load & dispatch planning"},desc:{vi:"Ghép đơn, chọn xe và lập lịch để tối đa hệ số sử dụng tải trọng mà không vượt khối lượng cho phép.",en:"Consolidate orders, pick vehicles and schedule to maximize load factor without exceeding the permitted payload."}},{name:{vi:"Tối ưu tuyến",en:"Route optimization"},desc:{vi:"Cân đối quãng đường, giờ cấm tải, trạm thu phí và khung giờ giao nhận của khách.",en:"Balance distance, truck-ban hours, toll stations and customer delivery windows."}},{name:{vi:"Kiểm soát chi phí chuyến",en:"Trip cost control"},desc:{vi:"Tính định mức nhiên liệu, phí đường bộ, chiều rỗng và đối soát với chi phí thực tế.",en:"Apply fuel norms, tolls and empty legs, and reconcile them with actual costs."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Không chở quá tải, không ép tài xế lái quá giờ; giữ hồ sơ xe, phù hiệu và kiểm định còn hiệu lực.",en:"Never overload or push drivers past their hours; keep vehicle papers, badges and inspections valid."}},{name:{vi:"Giao tiếp vận hành",en:"Operational communication"},desc:{vi:"Phối hợp tài xế, kho, khách hàng và cập nhật trạng thái đơn kịp thời, rõ ràng.",en:"Coordinate drivers, warehouses and customers and update order status promptly and clearly."}}],knowledge:{vi:["Luật Trật tự, an toàn giao thông đường bộ 2024 (số 36/2024/QH15) và Luật Đường bộ 2024 (số 35/2024/QH15).","Quy định thời gian lái xe của người lái xe kinh doanh vận tải: không quá 4 giờ liên tục và không quá 10 giờ trong một ngày.","Quy định hiện hành về kinh doanh vận tải bằng xe ô tô: giấy phép, phù hiệu, thiết bị giám sát hành trình và lưu trữ dữ liệu.","Khối lượng hàng chuyên chở cho phép ghi trên giấy chứng nhận kiểm định, tải trọng trục và xử lý xe quá tải.","Bài toán định tuyến xe (VRP), ghép chuyến, hệ số sử dụng tải trọng và tỷ lệ chạy rỗng."],en:["Law on Road Traffic Order and Safety 2024 (No. 36/2024/QH15) and the Road Law 2024 (No. 35/2024/QH15).","Driving-time rules for commercial drivers: no more than 4 hours of continuous driving and no more than 10 hours per day.","Current regulations on road transport business: licences, vehicle badges, journey monitoring devices and data retention.","Permitted payload on the inspection certificate, axle loads and handling of overloaded vehicles.","Vehicle routing problem (VRP), load consolidation, load factor and empty-running ratio."]},tools:["Hệ thống quản lý vận tải (TMS)","Nền tảng giám sát hành trình GPS","Phần mềm tối ưu tuyến đường","Ứng dụng xác nhận giao hàng điện tử (ePOD)","Microsoft Excel"],kpis:{vi:["Tỷ lệ giao hàng đúng hẹn (OTD) theo chuyến.","Hệ số sử dụng tải trọng và tỷ lệ km chạy rỗng.","Chi phí vận tải trên mỗi tấn.km so với định mức.","Số vi phạm quá tải, quá giờ lái (mục tiêu bằng 0)."],en:["On-time delivery rate (OTD) per trip.","Load factor and share of empty kilometres.","Transport cost per tonne-km against the norm.","Overload and driving-hour violations (target zero)."]},day:[{time:"06:30",vi:"Kiểm tra xe xuất bến, tài xế, giấy tờ và tín hiệu thiết bị giám sát hành trình.",en:"Check departing trucks, drivers, papers and telematics signals."},{time:"09:00",vi:"Ghép đơn chiều về, chọn loại xe và lập lệnh vận chuyển cho ngày mai.",en:"Match backhaul orders, choose vehicle types and draft tomorrow's transport orders."},{time:"13:00",vi:"Theo dõi hành trình, xử lý xe trễ hẹn, kẹt giờ cấm tải và báo khách thời gian giao mới.",en:"Track trips, handle late trucks and truck-ban delays, and send customers new ETAs."},{time:"15:30",vi:"Đối soát chi phí chuyến: nhiên liệu, phí đường bộ, bốc xếp với định mức.",en:"Reconcile trip costs (fuel, tolls, handling) against the norms."},{time:"17:30",vi:"Chốt kế hoạch điều xe, lịch nghỉ tài xế và báo cáo hiệu suất đội xe trong ngày.",en:"Lock the dispatch plan and driver rest schedule, and report daily fleet performance."}],mistakes:{vi:["Chọn xe theo tên gọi (8 tấn, 11 tấn) thay vì khối lượng hàng cho phép trên giấy kiểm định.","Tính chi phí chuyến chỉ chiều đi, quên chiều về rỗng và phí đường bộ hai chiều.","Chiều khách ép tài xế chạy suốt đêm không nghỉ, vi phạm thời gian lái xe và gây nguy cơ tai nạn."],en:["Choosing a truck by its name (8 t, 11 t) instead of the permitted payload on the inspection certificate.","Costing only the outbound leg and forgetting the empty return and tolls in both directions.","Giving in to customers and pushing drivers through the night without rest, breaking driving-time rules and risking crashes."]},career:[{vi:"Nhân viên điều độ xe",en:"Fleet dispatch assistant"},{vi:"Chuyên viên điều phối vận tải nội địa",en:"Domestic transport coordinator"},{vi:"Trưởng nhóm điều phối đội xe",en:"Fleet operations team lead"},{vi:"Quản lý vận tải & phân phối",en:"Transport & distribution manager"}],glossary:[{term:"TMS",vi:"Hệ thống quản lý vận tải: lập kế hoạch, điều xe, theo dõi và tính chi phí cho đơn hàng.",en:"Transport management system for planning, dispatching, tracking and costing shipments."},{term:"Payload",vi:"Khối lượng hàng chuyên chở cho phép tham gia giao thông ghi trên giấy chứng nhận kiểm định.",en:"Permitted cargo weight on the road as stated on the vehicle inspection certificate."},{term:"Empty running",vi:"Quãng đường xe chạy không có hàng, thường là chiều về; cần ghép đơn để giảm.",en:"Distance driven without cargo, usually the return leg; reduced by matching backhaul loads."},{term:"Telematics",vi:"Thiết bị giám sát hành trình ghi vị trí, tốc độ, thời gian lái xe và truyền dữ liệu về hệ thống.",en:"Journey monitoring device recording position, speed and driving time and sending data to the system."},{term:"Tonne-km",vi:"Đơn vị đo khối lượng công việc vận tải: khối lượng hàng nhân quãng đường vận chuyển.",en:"Unit of transport work: cargo weight multiplied by distance carried."}],quiz:[{q:{vi:"Xe chạy 200 km có hàng (định mức 30 lít/100 km) và 200 km rỗng (20 lít/100 km). Tổng nhiên liệu là bao nhiêu?",en:"A truck runs 200 km loaded (norm 30 l/100 km) and 200 km empty (20 l/100 km). What is the total fuel?"},options:{vi:["80 lít","60 lít","100 lít","120 lít"],en:["80 litres","60 litres","100 litres","120 litres"]},answer:2,explain:{vi:"Chiều có hàng 60 lít, chiều rỗng 40 lít, tổng 100 lít; phải tính riêng từng định mức.",en:"Loaded leg 60 litres plus empty leg 40 litres gives 100 litres; each norm is applied separately."}},{q:{vi:"Căn cứ nào xác định xe có chở quá tải hay không?",en:"What determines whether a truck is overloaded?"},options:{vi:["Khối lượng hàng chuyên chở cho phép trên giấy kiểm định","Tên gọi thương mại của loại xe","Ước lượng của tài xế","Thể tích thùng xe"],en:["The permitted payload on the inspection certificate","The commercial name of the truck model","The driver's estimate","The cargo box volume"]},answer:0,explain:{vi:"Giới hạn pháp lý là khối lượng hàng cho phép ghi trên giấy chứng nhận kiểm định, không phải tên gọi xe.",en:"The legal limit is the permitted payload on the inspection certificate, not the truck's name."}},{q:{vi:"Khách yêu cầu tài xế chạy liên tục 7 giờ không nghỉ để kịp giao. Bạn làm gì?",en:"A customer wants the driver to drive 7 hours non-stop to meet the deadline. What do you do?"},options:{vi:["Đồng ý vì khách trả thêm phí","Cho chạy và dặn tắt thiết bị giám sát","Chờ tài xế tự quyết","Từ chối, bố trí lịch nghỉ hoặc tài xế thứ hai và báo khách giờ giao mới"],en:["Agree because the customer pays extra","Let him drive and switch off the tracker","Let the driver decide","Refuse, plan rest or a second driver and give the customer a new time"]},answer:3,explain:{vi:"Lái liên tục quá 4 giờ là vi phạm và nguy hiểm; phải lập lịch nghỉ hoặc đổi tài xế, báo khách thời gian thực tế.",en:"Driving over 4 hours continuously is illegal and dangerous; plan rest or a relief driver and give a realistic time."}},{q:{vi:"Chỉ số nào phản ánh trực tiếp lãng phí do xe chạy không hàng?",en:"Which indicator directly shows waste from trucks running without cargo?"},options:{vi:["Tỷ lệ giao đúng hẹn","Tỷ lệ km chạy rỗng","Số đơn mỗi ngày","Điểm hài lòng khách hàng"],en:["On-time delivery rate","Share of empty kilometres","Orders per day","Customer satisfaction score"]},answer:1,explain:{vi:"Tỷ lệ km chạy rỗng đo phần quãng đường không tạo doanh thu, cải thiện bằng ghép đơn chiều về.",en:"The empty-km ratio measures non-revenue distance and improves with backhaul matching."}}]}},"KK-206":{scenario:{company:"Mây Xanh Express Hub",supervisor:{name:"Trịnh Bảo Ngọc",role:{vi:"Trưởng nhóm Vận hành Chặng cuối",en:"Last-mile Operations Lead"}},ref_code:"LM-4410",title:{vi:"Đúng dịch vụ. Đúng cước. Đúng trạng thái.",en:"Right service. Right charge. Right status."},brief:{vi:"Một nhà bán hàng trên sàn gửi lô LM-4410 gồm 120 kiện nồi chiên không dầu, mỗi kiện nặng thực 4,2 kg, thùng 50 x 40 x 33 cm. Hệ số quy đổi khối lượng thể tích là 6000. Kiện có khối lượng tính cước trên 10 kg phải đi dịch vụ BULKY (xe tải nhỏ). Đối chiếu phiếu điều phối nháp với hồ sơ đã duyệt, sửa dịch vụ giao và tổng cước lô (VND, biểu giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"A marketplace seller ships batch LM-4410 of 120 air fryers; each carton weighs 4.2 kg and measures 50 x 40 x 33 cm. The volumetric divisor is 6000. Parcels with a chargeable weight above 10 kg must use the BULKY service (small van). Compare the draft dispatch sheet with the approved file, correct the delivery service and the batch charge (VND, simulated tariff), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phân loại dịch vụ & tính cước đã duyệt · LM-4410",en:"Approved service classification & rating file · LM-4410"},fields:[{id:"SERVICE",label:{vi:"Dịch vụ giao hàng",en:"Delivery service"},initial:"STD-BIKE",expected:"BULKY",choices:["STD-BIKE","BULKY","EXPRESS-2H"],reference:"Quy định phân loại dịch vụ",hint:{vi:"Phân loại theo khối lượng tính cước chứ không theo khối lượng thực trên cân.",en:"Classify by chargeable weight, not by the actual weight on the scale."}},{id:"BATCH_FEE",label:{vi:"Tổng cước lô (VND)",en:"Batch delivery charge (VND)"},initial:"3600000",expected:"6480000",reference:"Biểu cước giao hàng",ref_value:{vi:"2 kg đầu 18000 đ, mỗi kg tiếp theo 4000 đ; làm tròn lên kg (mô phỏng)",en:"First 2 kg 18000 VND, each extra kg 4000 VND; round up to the kg (simulated)"},hint:{vi:"Tính khối lượng thể tích dài x rộng x cao / 6000, so với khối lượng thực rồi lấy số lớn hơn.",en:"Compute volumetric weight as length x width x height / 6000, compare with actual weight and take the larger."}}],sop32:{vi:"Khối lượng tính cước = max(khối lượng thực, D x R x C (cm) / 6000), làm tròn lên kg; cước mỗi kiện theo biểu giá; tổng cước lô = cước mỗi kiện x số kiện.",en:"Chargeable weight = max(actual weight, L x W x H (cm) / 6000), rounded up to the kg; the per-parcel charge follows the tariff; batch charge = per-parcel charge x number of parcels."},context:{label:"OMS / LM-4410",metrics:[{label:{vi:"Số kiện",en:"Parcels"},value:"120"},{label:{vi:"Khối lượng thực mỗi kiện",en:"Actual weight per parcel"},value:"4.2 kg"},{label:{vi:"Kích thước thùng",en:"Carton size"},value:"50 x 40 x 33 cm"}]},crisis:{vi:"Trưởng hub nhắn lúc 21:00: “Còn 37 đơn chưa giao, cứ cập nhật hết thành ‘khách hẹn lại’ cho đẹp tỷ lệ giao lần đầu, khỏi cần gọi khách. Ngày mai sàn chấm KPI.”",en:"The hub manager messages at 21:00: “There are 37 undelivered orders, just mark them all ‘customer rescheduled’ to protect the first-attempt rate, no need to call anyone. The marketplace scores KPIs tomorrow.”"},options:{safe:{vi:"Không cập nhật trạng thái sai sự thật; ghi đúng lý do từng đơn, lên lịch giao lại sáng mai, báo trưởng nhóm vận hành và đề xuất bổ sung tài xế cho tuyến quá tải.",en:"Do not post false statuses; record the real reason for each order, schedule redelivery tomorrow morning, inform the operations lead and request extra drivers for overloaded routes."},shortcut:{vi:"Cập nhật cả 37 đơn thành ‘khách hẹn lại’ để giữ KPI, mai tính tiếp.",en:"Mark all 37 orders ‘customer rescheduled’ to keep the KPI and deal with it tomorrow."},wait:{vi:"Để nguyên 37 đơn, không cập nhật và không báo ai đến sáng mai.",en:"Leave the 37 orders untouched, update nothing and tell no one until morning."}},questions:{vi:["Vì sao lô hàng phải đi dịch vụ BULKY dù mỗi kiện chỉ nặng 4,2 kg? Hãy chứng minh bằng khối lượng tính cước.","Trình bày cách tính tổng cước lô và rủi ro với sàn, với người mua nếu cập nhật trạng thái giao hàng sai sự thật."],en:["Why must the batch use the BULKY service when each parcel weighs only 4.2 kg? Prove it with the chargeable weight.","Explain how you calculated the batch charge and the risks with the marketplace and buyers of posting false delivery statuses."]},hints:{vi:["Đặt phiếu nháp cạnh quy định phân loại dịch vụ, đánh dấu dòng dịch vụ đang chọn theo cân thực.","Quy đổi khối lượng thể tích, làm tròn lên kg rồi áp biểu cước theo SOP mục 3.2.","Đọc lại SOP mục 4.2: trạng thái đơn phải phản ánh đúng thực tế, mọi áp lực sửa trạng thái phải báo cáo."],en:["Place the draft next to the service classification rule and flag the service chosen from the scale weight.","Convert to volumetric weight, round up to the kg and apply the tariff per SOP 3.2.","Re-read SOP 4.2: order statuses must reflect reality and any pressure to alter them must be escalated."]}},learning:{summary:{vi:"Chuyên viên logistics thương mại điện tử và giao hàng chặng cuối vận hành dòng đơn từ kho fulfillment đến tay người mua: phân loại dịch vụ, tính cước, chia tuyến, điều phối tài xế, xử lý giao thất bại, hoàn hàng và đối soát tiền thu hộ (COD). Công việc đòi hỏi tư duy dữ liệu, tốc độ, minh bạch trạng thái đơn và bảo vệ dữ liệu cá nhân người nhận.",en:"An e-commerce and last-mile logistics specialist runs the order flow from the fulfillment warehouse to the buyer's door: classifying services, rating parcels, building routes, dispatching drivers, handling failed deliveries and returns, and reconciling cash on delivery (COD). The role demands data skills, speed, honest order statuses and protection of recipients' personal data."},responsibilities:{vi:["Tiếp nhận đơn từ sàn và nhà bán, phân loại dịch vụ theo khối lượng tính cước, kích thước và khu vực.","Chia tuyến, phân đơn cho tài xế theo năng lực xe và khung giờ, theo dõi tiến độ theo thời gian thực.","Xử lý đơn giao thất bại (NDR): liên hệ người nhận, hẹn giao lại hoặc chuyển hoàn đúng quy trình.","Đối soát tiền thu hộ COD với tài xế và nhà bán, phát hiện chênh lệch, thất thoát.","Phân tích tỷ lệ giao thành công lần đầu, tỷ lệ hoàn, nguyên nhân khiếu nại và đề xuất cải tiến."],en:["Receive orders from marketplaces and sellers and classify services by chargeable weight, size and zone.","Build routes, assign orders to drivers by vehicle capacity and time window, and track progress in real time.","Handle failed deliveries (NDR): contact recipients, reschedule or return to sender per procedure.","Reconcile COD cash with drivers and sellers and detect gaps or losses.","Analyze first-attempt success, return rates and complaint causes, and propose improvements."]},competencies:[{name:{vi:"Quy hoạch tuyến chặng cuối",en:"Last-mile route planning"},desc:{vi:"Chia vùng, cân tải đơn cho tài xế và tối ưu thứ tự điểm giao theo khung giờ.",en:"Zone the area, balance driver workloads and sequence stops by time window."}},{name:{vi:"Tính cước & phân loại dịch vụ",en:"Rating & service classification"},desc:{vi:"Quy đổi khối lượng thể tích, áp biểu cước và chọn dịch vụ phù hợp kích thước, giá trị hàng.",en:"Convert volumetric weight, apply tariffs and pick the service that fits size and value."}},{name:{vi:"Xử lý ngoại lệ",en:"Exception management"},desc:{vi:"Giải quyết giao thất bại, hàng hư hỏng, thất lạc và khiếu nại theo SLA.",en:"Resolve failed deliveries, damage, loss and complaints within the SLA."}},{name:{vi:"Đối soát COD",en:"COD reconciliation"},desc:{vi:"Khớp tiền thu hộ theo đơn, tài xế, ngày và xử lý chênh lệch minh bạch.",en:"Match COD cash by order, driver and day and resolve gaps transparently."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Cập nhật trạng thái đúng thực tế, bảo vệ thông tin người nhận và không làm đẹp KPI.",en:"Post true statuses, protect recipient information and never window-dress KPIs."}}],knowledge:{vi:["Luật Bưu chính 2010 (số 49/2010/QH12) và yêu cầu giấy phép kinh doanh dịch vụ bưu chính đối với dịch vụ chuyển phát.","Quy định hiện hành về thương mại điện tử và bảo vệ quyền lợi người tiêu dùng trong giao dịch trực tuyến.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: chỉ dùng họ tên, số điện thoại, địa chỉ người nhận cho mục đích giao hàng.","Khối lượng thể tích (D x R x C / hệ số quy đổi, phổ biến 5000 hoặc 6000) và nguyên tắc tính cước theo số lớn hơn.","Mô hình vận hành chặng cuối: hub-and-spoke, điểm nhận hàng (PUDO), tủ nhận hàng thông minh, giao trong ngày."],en:["Postal Law 2010 (No. 49/2010/QH12) and the postal service licence required for express delivery.","Current regulations on e-commerce and consumer protection in online transactions.","Current personal data protection rules: use recipient names, phones and addresses only for delivery purposes.","Volumetric weight (L x W x H / divisor, commonly 5000 or 6000) and charging on the greater weight.","Last-mile operating models: hub-and-spoke, pick-up and drop-off points (PUDO), smart lockers, same-day delivery."]},tools:["Hệ thống quản lý đơn hàng (OMS)","Phần mềm điều phối chặng cuối","Ứng dụng tài xế có ePOD","Máy cân đo kích thước tự động (DWS)","Bảng đối soát COD"],kpis:{vi:["Tỷ lệ giao thành công lần đầu (FADR).","Tỷ lệ giao đúng SLA cam kết với sàn.","Tỷ lệ hoàn hàng (RTO) và tỷ lệ thất lạc, hư hỏng.","Chênh lệch đối soát COD (mục tiêu bằng 0)."],en:["First-attempt delivery rate (FADR).","Share of deliveries within the marketplace SLA.","Return-to-origin (RTO) rate and loss or damage rate.","COD reconciliation gaps (target zero)."]},day:[{time:"07:00",vi:"Nhận hàng từ kho fulfillment, quét kiện, kiểm tra cân đo và phân loại dịch vụ.",en:"Receive parcels from fulfillment, scan them, check dimensions and classify services."},{time:"08:30",vi:"Chia tuyến, phân đơn cho tài xế, đánh dấu đơn hẹn giờ và đơn giá trị cao.",en:"Build routes, assign orders to drivers and flag timed and high-value orders."},{time:"12:00",vi:"Theo dõi tiến độ giao, xử lý đơn thất bại và liên hệ người nhận hẹn giao lại.",en:"Track deliveries, handle failed attempts and contact recipients to reschedule."},{time:"17:00",vi:"Đối soát COD với tài xế, xử lý chênh lệch và hàng chuyển hoàn.",en:"Reconcile COD with drivers and process gaps and returns."},{time:"20:30",vi:"Chốt trạng thái đơn trong ngày, báo cáo tỷ lệ giao thành công và kế hoạch ngày mai.",en:"Close the day's statuses and report success rates and tomorrow's plan."}],mistakes:{vi:["Tính cước theo cân thực, bỏ qua khối lượng thể tích của hàng cồng kềnh.","Chuyển hoàn ngay sau lần giao thất bại đầu tiên mà chưa liên hệ người nhận đủ số lần quy định.","Cập nhật trạng thái ảo (‘khách hẹn lại’, ‘đã giao’) để làm đẹp KPI, gây mất niềm tin và khiếu nại."],en:["Rating bulky parcels on scale weight and ignoring volumetric weight.","Returning a parcel after the first failed attempt without contacting the recipient the required number of times.","Posting fake statuses (‘customer rescheduled’, ‘delivered’) to dress up KPIs, causing distrust and complaints."]},career:[{vi:"Nhân viên điều phối bưu cục",en:"Hub dispatch assistant"},{vi:"Chuyên viên vận hành chặng cuối",en:"Last-mile operations specialist"},{vi:"Trưởng hub giao hàng",en:"Delivery hub manager"},{vi:"Quản lý logistics thương mại điện tử",en:"E-commerce logistics manager"}],glossary:[{term:"Last mile",vi:"Chặng giao cuối cùng từ hub hoặc bưu cục đến tay người nhận, thường tốn chi phí nhất.",en:"The final leg from the hub or post office to the recipient, usually the most costly."},{term:"Volumetric weight",vi:"Khối lượng quy đổi từ thể tích kiện hàng, dùng tính cước khi lớn hơn khối lượng thực.",en:"Weight derived from parcel volume, used for charging when it exceeds the actual weight."},{term:"COD",vi:"Dịch vụ thu hộ: người giao thu tiền hàng từ người mua và chuyển lại cho nhà bán.",en:"Cash on delivery: the courier collects payment from the buyer and remits it to the seller."},{term:"NDR",vi:"Báo cáo giao thất bại, ghi lý do để hẹn giao lại hoặc chuyển hoàn.",en:"Non-delivery report recording the reason, used to reschedule or return the parcel."},{term:"RTO",vi:"Hàng chuyển hoàn về nhà bán sau khi giao không thành công.",en:"Return to origin: a parcel sent back to the seller after failed delivery."}],quiz:[{q:{vi:"Kiện 60 x 40 x 40 cm, nặng thực 7 kg, hệ số quy đổi 6000. Khối lượng tính cước là bao nhiêu?",en:"A 60 x 40 x 40 cm parcel weighs 7 kg, divisor 6000. What is the chargeable weight?"},options:{vi:["7 kg","9,6 kg","12 kg","16 kg"],en:["7 kg","9.6 kg","12 kg","16 kg"]},answer:3,explain:{vi:"Khối lượng thể tích 96000 / 6000 = 16 kg, lớn hơn 7 kg nên tính cước theo 16 kg.",en:"Volumetric weight 96000 / 6000 = 16 kg exceeds 7 kg, so the parcel is charged at 16 kg."}},{q:{vi:"Cuối ngày còn nhiều đơn chưa giao, quản lý bảo cập nhật hàng loạt ‘khách hẹn lại’. Bạn làm gì?",en:"Many orders are still undelivered at day end and the manager says to mass-mark them ‘customer rescheduled’. What do you do?"},options:{vi:["Làm theo để giữ KPI","Ghi đúng lý do từng đơn, lên lịch giao lại và báo cáo","Để nguyên không cập nhật","Đánh dấu đã giao rồi giao bù"],en:["Comply to protect the KPI","Record each real reason, reschedule and escalate","Leave them without updates","Mark them delivered and deliver later"]},answer:1,explain:{vi:"Trạng thái giả làm sai dữ liệu của sàn và người mua; phải ghi đúng, xử lý giao lại và báo cáo áp lực.",en:"Fake statuses mislead the marketplace and buyers; record the truth, redeliver and escalate the pressure."}},{q:{vi:"Chỉ số FADR đo điều gì?",en:"What does FADR measure?"},options:{vi:["Tỷ lệ đơn giao thành công ngay lần đầu","Tỷ lệ đơn bị hoàn","Số đơn mỗi tài xế mỗi ngày","Thời gian xử lý tại kho"],en:["Share of orders delivered on the first attempt","Share of returned orders","Orders per driver per day","Warehouse processing time"]},answer:0,explain:{vi:"FADR là tỷ lệ đơn giao thành công ở lần đầu, phản ánh chất lượng tuyến và liên hệ người nhận.",en:"FADR is the first-attempt success rate, reflecting route quality and recipient contact."}},{q:{vi:"Mục đích chính của đối soát COD hằng ngày là gì?",en:"What is the main purpose of daily COD reconciliation?"},options:{vi:["Tính lương tài xế","Xếp hạng nhà bán","Khớp tiền thu hộ theo từng đơn và phát hiện chênh lệch kịp thời","Thay thế hóa đơn điện tử"],en:["Calculate driver pay","Rank sellers","Match collected cash to each order and catch gaps early","Replace e-invoices"]},answer:2,explain:{vi:"Đối soát hằng ngày giúp phát hiện sớm thất thoát, giữ tiền của nhà bán an toàn và minh bạch.",en:"Daily reconciliation catches losses early and keeps sellers' money safe and transparent."}}]}},"KK-231":{scenario:{company:"Hải Đăng Global Forwarding",supervisor:{name:"Lê Minh Châu",role:{vi:"Trưởng phòng Khai thác Hàng xuất",en:"Export Operations Manager"}},ref_code:"HBL-2604",title:{vi:"Đúng điều kiện cước. Đúng tấn cước.",en:"Right freight term. Right revenue ton."},brief:{vi:"Bạn phát hành vận đơn nhà HBL-2604 cho lô hàng lẻ (LCL) phụ tùng gang đúc xuất từ Hải Phòng đi Rotterdam, điều kiện FOB Hải Phòng theo Incoterms 2020; người mua chỉ định công ty bạn làm đại lý giao nhận. Phiếu cân tại kho CFS: 9600 kg; phiếu đo: 6,4 CBM. Đối chiếu HBL nháp với hồ sơ đã duyệt, sửa điều kiện thanh toán cước và cước biển LCL (USD, giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are issuing house bill HBL-2604 for an LCL shipment of cast iron parts from Hai Phong to Rotterdam, sold FOB Hai Phong under Incoterms 2020; the buyer nominated your company as forwarder. CFS weighing ticket: 9600 kg; measurement: 6.4 CBM. Compare the draft HBL with the approved file, correct the freight term and the LCL ocean freight (USD, simulated rate), then write an evidence-based report."},reference_title:{vi:"Hồ sơ lô hàng & biểu giá LCL đã duyệt · HBL-2604",en:"Approved shipment file & LCL tariff · HBL-2604"},fields:[{id:"FRT_TERM",label:{vi:"Điều kiện thanh toán cước trên HBL",en:"Freight term on the HBL"},initial:"FREIGHT PREPAID",expected:"FREIGHT COLLECT",choices:["FREIGHT PREPAID","FREIGHT COLLECT","AS ARRANGED"],reference:"Hợp đồng mua bán & booking",ref_value:{vi:"Hợp đồng: FOB Hải Phòng; người mua thuê phương tiện và trả cước chặng chính",en:"Contract: FOB Hai Phong; the buyer books and pays the main carriage"},hint:{vi:"Theo FOB, người mua chịu cước vận tải chính nên cước được thu tại nơi đến.",en:"Under FOB the buyer bears the main carriage, so freight is collected at destination."}},{id:"OCEAN_FRT",label:{vi:"Cước biển LCL (USD)",en:"LCL ocean freight (USD)"},initial:"268.8",expected:"403.2",reference:"Biểu giá LCL đã duyệt",ref_value:{vi:"42 USD/RT; 1 RT = 1 CBM hoặc 1000 kg, lấy số lớn hơn (mô phỏng)",en:"42 USD/RT; 1 RT = 1 CBM or 1000 kg, whichever is greater (simulated)"},hint:{vi:"Hàng nặng: quy trọng lượng ra tấn rồi so với số khối, tính cước theo số lớn hơn.",en:"Heavy cargo: convert weight to tonnes, compare with CBM and charge on the greater figure."}}],sop32:{vi:"Cước LCL tính theo W/M: tấn cước (RT) = max(số khối CBM, trọng lượng quy ra tấn); cước = RT x đơn giá; bài mô phỏng không làm tròn RT.",en:"LCL freight is charged W/M: revenue tons (RT) = max(CBM, weight in tonnes); freight = RT x rate; RT is not rounded in this training case."},context:{label:"FWD OPS / HBL-2604",metrics:[{label:{vi:"Trọng lượng cả bì",en:"Gross weight"},value:"9,600 kg"},{label:{vi:"Thể tích",en:"Volume"},value:"6.4 CBM"},{label:{vi:"Đơn giá mô phỏng",en:"Simulated rate"},value:"42 USD/RT"}]},crisis:{vi:"Bộ phận kinh doanh nhắn: “Khách quen, cứ khai 6400 kg trên HBL và bảng kê hàng cho cước tính theo khối. Hàng lẻ không ai cân lại đâu, tàu cắt máng chiều nay.”",en:"Sales messages you: “Loyal customer, just declare 6400 kg on the HBL and the cargo list so freight goes by volume. Nobody re-weighs LCL cargo, and the vessel cuts off this afternoon.”"},options:{safe:{vi:"Khai đúng 9600 kg theo phiếu cân, tính cước theo W/M, báo trưởng phòng; giải thích rủi ro an toàn xếp hàng, VGM và đề xuất báo giá hàng nặng riêng cho khách.",en:"Declare the true 9600 kg from the weighing ticket, charge W/M, inform the manager, explain the stowage safety and VGM risks and offer a dedicated heavy-cargo quote."},shortcut:{vi:"Khai 6400 kg trên HBL theo ý kinh doanh để kịp cắt máng và giữ khách.",en:"Declare 6400 kg on the HBL as Sales asks to make the cut-off and keep the customer."},wait:{vi:"Tạm giữ HBL, không trả lời kinh doanh và chờ khách tự gửi số liệu mới.",en:"Hold the HBL, ignore Sales and wait for the customer to send new figures."}},questions:{vi:["Vì sao HBL phải ghi FREIGHT COLLECT thay vì FREIGHT PREPAID? Điều khoản nào trong hợp đồng chứng minh?","Trình bày cách tính tấn cước theo W/M và rủi ro an toàn, pháp lý nếu khai thấp trọng lượng hàng."],en:["Why must the HBL show FREIGHT COLLECT instead of FREIGHT PREPAID? Which contract term proves it?","Explain how you calculated revenue tons under W/M and the safety and legal risks of under-declaring cargo weight."]},hints:{vi:["Đặt HBL nháp cạnh hợp đồng mua bán, đánh dấu điều kiện cước không khớp Incoterms.","So số khối với trọng lượng quy ra tấn, lấy số lớn hơn rồi nhân đơn giá theo SOP mục 3.2.","Đọc lại SOP mục 4.2: trọng lượng trên chứng từ phải đúng phiếu cân; áp lực khai sai phải báo cáo."],en:["Place the draft HBL next to the sales contract and flag the freight term that does not match the Incoterm.","Compare CBM with weight in tonnes, take the greater and multiply by the rate per SOP 3.2.","Re-read SOP 4.2: document weights must match the weighing ticket; pressure to misdeclare must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều vận quốc tế đường biển và đường hàng không tổ chức vận chuyển hàng xuất nhập khẩu cho khách: đặt chỗ với hãng tàu, hãng bay, gom hàng lẻ, phát hành vận đơn nhà (HBL, HAWB), phối hợp đại lý nước ngoài, theo dõi lô hàng và xử lý phát sinh. Công việc đòi hỏi nắm chắc Incoterms, cách tính cước từng phương thức, quy định hàng nguy hiểm và chứng từ vận tải.",en:"An ocean and air freight forwarder organizes international carriage for import and export customers: booking space with carriers and airlines, consolidating LCL cargo, issuing house bills (HBL, HAWB), coordinating overseas agents, tracking shipments and handling exceptions. The role requires solid knowledge of Incoterms, rating for each mode, dangerous goods rules and transport documents."},responsibilities:{vi:["Nhận yêu cầu vận chuyển, kiểm tra Incoterms, loại hàng, trọng lượng, thể tích và đặt chỗ với hãng tàu, hãng bay.","Phát hành vận đơn nhà HBL/HAWB, manifest và gửi chứng từ trước cho đại lý tại nơi đến.","Tính cước theo W/M cho hàng lẻ đường biển và khối lượng tính cước cho hàng không, lập giấy báo nợ.","Kiểm tra khai báo hàng nguy hiểm theo IMDG Code, IATA DGR và xác nhận VGM trước giờ cắt máng.","Theo dõi lịch trình, xử lý chậm tàu, chuyển tải, hư hỏng và thông báo khách hàng kịp thời."],en:["Take transport requests, check Incoterms, cargo type, weight and volume, and book with carriers and airlines.","Issue HBL/HAWB and manifests and send pre-alert documents to the destination agent.","Rate LCL ocean cargo on W/M and air cargo on chargeable weight, and issue debit notes.","Check dangerous goods declarations under the IMDG Code and IATA DGR and confirm VGM before cut-off.","Monitor schedules, handle delays, transshipment and damage, and update customers promptly."]},competencies:[{name:{vi:"Incoterms & điều kiện cước",en:"Incoterms & freight terms"},desc:{vi:"Xác định bên trả cước, điểm chuyển rủi ro và ghi đúng prepaid, collect trên vận đơn.",en:"Identify who pays freight and where risk passes, and show prepaid or collect correctly on the bill."}},{name:{vi:"Tính cước đa phương thức",en:"Multimodal rating"},desc:{vi:"Áp dụng W/M cho LCL, tỷ lệ 1:6000 cho hàng không, phụ phí và đơn giá theo hợp đồng.",en:"Apply W/M for LCL, the 1:6000 ratio for air, surcharges and contract rates."}},{name:{vi:"Chứng từ vận tải",en:"Transport documentation"},desc:{vi:"Lập HBL, HAWB, manifest chính xác, khớp booking, phiếu cân và chứng từ thương mại.",en:"Produce accurate HBL, HAWB and manifests matching the booking, weighing ticket and trade documents."}},{name:{vi:"Hàng nguy hiểm & an toàn",en:"Dangerous goods & safety"},desc:{vi:"Nhận diện hàng nguy hiểm, yêu cầu khai báo đúng và từ chối nhận hàng khai sai.",en:"Recognize dangerous goods, require correct declarations and refuse misdeclared cargo."}},{name:{vi:"Phối hợp mạng lưới đại lý",en:"Agent network coordination"},desc:{vi:"Làm việc với hãng tàu, hãng bay, kho CFS và đại lý nước ngoài theo múi giờ và cam kết dịch vụ.",en:"Work with carriers, airlines, CFS warehouses and overseas agents across time zones and service commitments."}}],knowledge:{vi:["Incoterms 2020 của ICC: điểm chuyển giao rủi ro, chi phí và ảnh hưởng đến điều kiện cước trên vận đơn.","Bộ luật Hàng hải Việt Nam 2015 (số 95/2015/QH13) về hợp đồng vận chuyển hàng hóa và vận đơn đường biển.","Công ước Montreal 1999 về trách nhiệm của người vận chuyển hàng không quốc tế.","Bộ luật IMDG cho hàng nguy hiểm đường biển, IATA DGR cho đường hàng không và yêu cầu VGM của Công ước SOLAS.","Nghị định 163/2017/NĐ-CP về kinh doanh dịch vụ logistics."],en:["ICC Incoterms 2020: transfer of risk and cost and its effect on the freight term on the bill.","Vietnam Maritime Code 2015 (No. 95/2015/QH13) on contracts of carriage and ocean bills of lading.","Montreal Convention 1999 on the liability of international air carriers.","IMDG Code for sea dangerous goods, IATA DGR for air, and the SOLAS VGM requirement.","Decree 163/2017/ND-CP on logistics services business."]},tools:["Phần mềm quản lý giao nhận (Forwarding ERP)","Cổng đặt chỗ trực tuyến của hãng tàu, hãng bay","Nền tảng theo dõi container và chuyến bay","VNACCS/VCIS","Microsoft Excel"],kpis:{vi:["Tỷ lệ HBL/HAWB phát hành đúng ngay lần đầu, không phải sửa.","Tỷ lệ lô hàng đi đúng chuyến đã đặt chỗ.","Số khiếu nại, chi phí phát sinh do sai chứng từ (mục tiêu bằng 0).","Thời gian gửi chứng từ trước cho đại lý sau khi tàu chạy."],en:["Share of HBL/HAWB issued right first time without amendment.","Share of shipments loaded on the booked sailing or flight.","Complaints and extra costs caused by document errors (target zero).","Time to send pre-alert documents to the agent after departure."]},day:[{time:"08:00",vi:"Kiểm tra email đại lý nước ngoài, lịch tàu, chuyến bay và các lô sắp cắt máng.",en:"Check overseas agent emails, vessel and flight schedules and shipments near cut-off."},{time:"10:00",vi:"Đặt chỗ, xác nhận booking, nhận phiếu cân, phiếu đo hàng lẻ tại kho CFS.",en:"Book space, confirm bookings and collect LCL weighing and measurement tickets from the CFS."},{time:"13:30",vi:"Lập HBL nháp, đối chiếu hợp đồng, Incoterms và gửi khách xác nhận.",en:"Draft the HBL, check it against the contract and Incoterms and send it for customer approval."},{time:"15:30",vi:"Xác nhận VGM, khai báo hàng nguy hiểm nếu có và nộp chứng từ trước giờ cắt máng.",en:"Confirm VGM, file dangerous goods declarations if any and submit documents before cut-off."},{time:"17:30",vi:"Gửi pre-alert cho đại lý nơi đến, lập giấy báo nợ cước và cập nhật hệ thống.",en:"Send the pre-alert to the destination agent, issue freight debit notes and update the system."}],mistakes:{vi:["Ghi FREIGHT PREPAID trên HBL cho lô FOB mà người mua là bên trả cước.","Tính cước hàng lẻ theo số khối cho hàng nặng thay vì theo W/M.","Chấp nhận khai thấp trọng lượng hoặc khai sai hàng nguy hiểm để rẻ cước, gây rủi ro an toàn tàu và bị xử phạt."],en:["Showing FREIGHT PREPAID on the HBL of an FOB shipment where the buyer pays freight.","Charging heavy LCL cargo by volume instead of W/M.","Accepting under-declared weights or misdeclared dangerous goods to cut freight, endangering the vessel and inviting penalties."]},career:[{vi:"Nhân viên chứng từ giao nhận",en:"Forwarding documentation assistant"},{vi:"Chuyên viên khai thác đường biển & hàng không",en:"Ocean & air operations specialist"},{vi:"Trưởng nhóm khai thác giao nhận",en:"Forwarding operations team lead"},{vi:"Quản lý vận hành giao nhận quốc tế",en:"International freight operations manager"}],glossary:[{term:"HBL",vi:"Vận đơn nhà do công ty giao nhận phát hành cho người gửi hàng của mình.",en:"House bill of lading issued by the forwarder to its own shipper."},{term:"LCL",vi:"Hàng lẻ: hàng của nhiều chủ hàng được đóng chung một container tại kho CFS.",en:"Less than container load: cargo of several shippers consolidated in one container at a CFS."},{term:"W/M",vi:"Nguyên tắc tính cước theo trọng lượng hoặc thể tích, lấy giá trị lớn hơn quy ra tấn cước.",en:"Weight or measurement rule: freight is charged on whichever gives more revenue tons."},{term:"VGM",vi:"Khối lượng toàn bộ đã xác nhận của container theo yêu cầu SOLAS trước khi xếp lên tàu.",en:"Verified gross mass of a packed container required by SOLAS before loading."},{term:"Pre-alert",vi:"Thông báo kèm bản sao chứng từ gửi đại lý nơi đến trước khi hàng tới.",en:"Advance notice with document copies sent to the destination agent before arrival."}],quiz:[{q:{vi:"Lô hàng không nặng 120 kg, thể tích 1,2 m³, hệ số 6000 cm³/kg. Khối lượng tính cước là bao nhiêu?",en:"An air shipment weighs 120 kg with a volume of 1.2 m³, divisor 6000 cm³/kg. What is the chargeable weight?"},options:{vi:["120 kg","160 kg","200 kg","320 kg"],en:["120 kg","160 kg","200 kg","320 kg"]},answer:2,explain:{vi:"1,2 m³ = 1200000 cm³; chia 6000 được 200 kg, lớn hơn 120 kg nên tính theo 200 kg.",en:"1.2 m³ = 1200000 cm³; divided by 6000 gives 200 kg, which exceeds 120 kg, so 200 kg is charged."}},{q:{vi:"Theo FOB Incoterms 2020, ai trả cước vận tải chặng chính?",en:"Under FOB Incoterms 2020, who pays the main carriage?"},options:{vi:["Người mua","Người bán","Đại lý nơi đi","Ngân hàng"],en:["The buyer","The seller","The origin agent","The bank"]},answer:0,explain:{vi:"Theo FOB, người bán giao hàng lên tàu; người mua thuê tàu và trả cước chặng chính.",en:"Under FOB the seller delivers on board; the buyer contracts and pays the main carriage."}},{q:{vi:"Khách nhờ ghi pin lithium thành ‘phụ tùng điện tử’ để khỏi khai báo hàng nguy hiểm. Bạn làm gì?",en:"A customer asks you to describe lithium batteries as ‘electronic parts’ to avoid a dangerous goods declaration. What do you do?"},options:{vi:["Ghi theo khách vì hàng ít","Từ chối, yêu cầu khai báo và đóng gói theo quy định hàng nguy hiểm, báo trưởng phòng","Gửi đi rồi báo sau","Đổi sang đường biển để khỏi khai"],en:["Write it as asked since the quantity is small","Refuse, require DG declaration and packing per the rules, and inform the manager","Ship now and report later","Switch to ocean to avoid declaring"]},answer:1,explain:{vi:"Khai sai hàng nguy hiểm có thể gây cháy nổ trên tàu, máy bay; mọi phương thức đều bắt buộc khai báo đúng.",en:"Misdeclared dangerous goods can cause fires on ships and aircraft; every mode requires a correct declaration."}},{q:{vi:"Hàng lẻ 3 CBM, nặng 4500 kg, đơn giá 40 USD/RT. Cước là bao nhiêu?",en:"LCL cargo of 3 CBM weighs 4500 kg at 40 USD/RT. What is the freight?"},options:{vi:["120 USD","160 USD","150 USD","180 USD"],en:["120 USD","160 USD","150 USD","180 USD"]},answer:3,explain:{vi:"4500 kg = 4,5 tấn lớn hơn 3 CBM nên RT = 4,5; cước = 4,5 x 40 = 180 USD.",en:"4500 kg = 4.5 t exceeds 3 CBM, so RT = 4.5; freight = 4.5 x 40 = 180 USD."}}]}},"KK-232":{scenario:{company:"Phương Nam Cargo Link",supervisor:{name:"Hoàng Thu Trang",role:{vi:"Giám đốc Kinh doanh",en:"Sales Director"}},ref_code:"QT-8826",title:{vi:"Đúng phạm vi. Đúng biên lợi nhuận.",en:"Right scope. Right margin."},brief:{vi:"Khách nhập khẩu tại Bình Dương mua máy móc từ Thượng Hải theo điều kiện EXW kho người bán, cần báo giá trọn gói một container 40'GP về cảng Cát Lái. Giá vốn mô phỏng: cước biển 1180 USD, phụ phí hãng tàu 145 USD, chi phí đầu xuất (lấy hàng, thông quan xuất) 375 USD. Biên lợi nhuận gộp mục tiêu 20% trên giá bán. Đối chiếu báo giá nháp QT-8826 với hồ sơ đã duyệt, sửa phạm vi báo giá và giá bán, rồi lập báo cáo.",en:"An importer in Binh Duong buys machinery from Shanghai on EXW seller's warehouse terms and needs an all-in quote for one 40'GP to Cat Lai port. Simulated costs: ocean freight 1180 USD, carrier surcharges 145 USD, origin charges (pickup, export clearance) 375 USD. Target gross margin is 20% of the selling price. Compare draft quote QT-8826 with the approved file, correct the quoted scope and the selling price, then write a report."},reference_title:{vi:"Hồ sơ yêu cầu khách & bảng giá vốn đã duyệt · QT-8826",en:"Approved customer request & cost sheet · QT-8826"},fields:[{id:"SCOPE_TERM",label:{vi:"Phạm vi báo giá theo Incoterms",en:"Quoted scope (Incoterms)"},initial:"FOB",expected:"EXW",choices:["EXW","FOB","CIF"],reference:"Hợp đồng mua bán của khách",ref_value:{vi:"Hợp đồng: EXW kho người bán tại Thượng Hải",en:"Contract: EXW seller's warehouse, Shanghai"},hint:{vi:"Phạm vi báo giá phải bắt đầu từ điểm người mua nhận hàng theo Incoterms của hợp đồng.",en:"The quote must start where the buyer takes delivery under the contract's Incoterm."}},{id:"SELL_USD",label:{vi:"Giá bán trọn gói (USD)",en:"All-in selling price (USD)"},initial:"2040",expected:"2125",reference:"Bảng tính giá vốn & biên lợi nhuận",ref_value:{vi:"Giá vốn: cước 1180 + phụ phí 145 + đầu xuất 375 USD; biên gộp 20% trên giá bán",en:"Cost: freight 1180 + surcharges 145 + origin 375 USD; 20% gross margin on price"},hint:{vi:"Biên lợi nhuận tính trên giá bán, không phải tỷ lệ cộng thêm trên giá vốn.",en:"Margin is a share of the selling price, not a markup on cost."}}],sop32:{vi:"Giá bán = tổng giá vốn / (1 - biên lợi nhuận gộp mục tiêu); tổng giá vốn gồm mọi chặng trong phạm vi Incoterms của khách (bài mô phỏng biên 20%).",en:"Selling price = total cost / (1 - target gross margin); total cost covers every leg within the customer's Incoterm scope (training margin 20%)."},context:{label:"CRM / QT-8826",metrics:[{label:{vi:"Cước biển mua vào",en:"Buy ocean rate"},value:"1,180 USD"},{label:{vi:"Chi phí đầu xuất",en:"Origin charges"},value:"375 USD"},{label:{vi:"Biên gộp mục tiêu",en:"Target gross margin"},value:"20%"}]},crisis:{vi:"Trưởng phòng mua hàng của khách nhắn riêng: “Thêm 50 USD/cont vào giá rồi chuyển phần đó vào tài khoản cá nhân của anh, hợp đồng cả năm 120 cont là của em.”",en:"The customer's purchasing manager messages you privately: “Add 50 USD per box to the price and transfer that part to my personal account, and the 120-box annual contract is yours.”"},options:{safe:{vi:"Từ chối khoản chi riêng, báo Giám đốc Kinh doanh và bộ phận tuân thủ; đề xuất chiết khấu sản lượng chính thức ghi trong hợp đồng với công ty khách.",en:"Refuse the side payment, report to the Sales Director and compliance, and offer an official volume rebate written into the contract with the customer company."},shortcut:{vi:"Đồng ý cộng 50 USD/cont và chuyển riêng cho anh ấy để chốt hợp đồng năm.",en:"Agree to add 50 USD per box and pay it to him privately to win the annual contract."},wait:{vi:"Không trả lời, để báo giá treo đến khi khách tự liên hệ lại.",en:"Do not reply and leave the quote pending until the customer calls back."}},questions:{vi:["Vì sao báo giá phải theo phạm vi EXW thay vì FOB? Điều khoản nào trong hợp đồng của khách chứng minh?","Trình bày cách tính giá bán theo biên lợi nhuận và cách xử lý đề nghị khoản chi riêng từ phía khách."],en:["Why must the quote follow an EXW scope instead of FOB? Which term in the customer's contract proves it?","Explain how you priced from the target margin and how you handle the customer's request for a private payment."]},hints:{vi:["Đặt báo giá nháp cạnh hợp đồng mua bán của khách, đánh dấu chặng dịch vụ bị thiếu.","Cộng đủ giá vốn mọi chặng rồi chia cho (1 - biên lợi nhuận) theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị chi riêng cho cá nhân phía khách phải từ chối và báo cáo."],en:["Place the draft quote next to the customer's sales contract and flag the missing service leg.","Add the full cost of every leg, then divide by (1 - margin) per SOP 3.2.","Re-read SOP 4.2: any request for private payments to customer staff must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên kinh doanh cước vận tải quốc tế tìm kiếm, tư vấn và chăm sóc khách hàng xuất nhập khẩu, xây dựng báo giá đường biển, đường hàng không, trọn gói theo Incoterms và quản lý biên lợi nhuận từng lô. Công việc đòi hỏi hiểu chuỗi dịch vụ giao nhận, cấu trúc cước và phụ phí, kỹ năng đàm phán và liêm chính trong quan hệ khách hàng.",en:"A freight forwarding sales executive finds, advises and serves import and export customers, builds ocean, air and door-to-door quotes based on Incoterms and manages the margin on every shipment. The role requires understanding the forwarding service chain, freight and surcharge structures, negotiation skills and integrity in customer relationships."},responsibilities:{vi:["Tìm kiếm khách hàng mới, khai thác nhu cầu, tuyến, sản lượng và Incoterms của từng hợp đồng mua bán.","Lấy giá từ hãng tàu, hãng bay, đại lý và lập báo giá đủ phạm vi, đủ phụ phí.","Tính giá bán theo biên lợi nhuận mục tiêu, trình duyệt khi vượt quyền hạn chiết khấu.","Đàm phán hợp đồng dịch vụ, điều khoản thanh toán, hạn mức tín dụng và thời gian miễn phí lưu container.","Chăm sóc khách hàng, theo dõi lô hàng cùng bộ phận khai thác và cập nhật CRM, dự báo doanh số."],en:["Prospect new customers and uncover needs, lanes, volumes and the Incoterms of each sales contract.","Source rates from carriers, airlines and agents and build quotes with full scope and surcharges.","Price to the target margin and seek approval when discounts exceed your authority.","Negotiate service contracts, payment terms, credit limits and container free time.","Serve customers, follow shipments with operations, and keep the CRM and sales forecast up to date."]},competencies:[{name:{vi:"Tư vấn giải pháp vận tải",en:"Freight solution advisory"},desc:{vi:"Đề xuất phương thức, tuyến, loại container và phạm vi dịch vụ phù hợp nhu cầu và Incoterms của khách.",en:"Recommend mode, lane, container type and service scope that fit the customer's needs and Incoterms."}},{name:{vi:"Định giá & biên lợi nhuận",en:"Pricing & margin control"},desc:{vi:"Xây dựng giá vốn đầy đủ, phân biệt biên lợi nhuận với tỷ lệ cộng thêm, kiểm soát chiết khấu.",en:"Build full costs, distinguish margin from markup and control discounts."}},{name:{vi:"Đàm phán",en:"Negotiation"},desc:{vi:"Cân bằng giá, chất lượng dịch vụ và rủi ro tín dụng để đạt thỏa thuận bền vững.",en:"Balance price, service quality and credit risk to reach sustainable deals."}},{name:{vi:"Quản lý pipeline",en:"Pipeline management"},desc:{vi:"Theo dõi cơ hội, tỷ lệ chốt và dự báo doanh số trên CRM.",en:"Track opportunities, win rates and sales forecasts in the CRM."}},{name:{vi:"Liêm chính thương mại",en:"Commercial integrity"},desc:{vi:"Từ chối hối lộ, hoa hồng ngầm; mọi ưu đãi phải chính thức và minh bạch trong hợp đồng.",en:"Refuse bribes and hidden commissions; every incentive must be official and transparent in the contract."}}],knowledge:{vi:["Incoterms 2020 và cách xác định phạm vi dịch vụ, bên trả cước cho từng điều kiện.","Cấu trúc cước và phụ phí: cước biển, BAF, THC, phí chứng từ, phụ phí mùa cao điểm, phí DEM/DET.","Nghị định 163/2017/NĐ-CP về kinh doanh dịch vụ logistics và Luật Thương mại 2005 (số 36/2005/QH11).","Bộ luật Hình sự 2015 áp dụng tội đưa, nhận hối lộ cả trong khu vực ngoài nhà nước; tham chiếu ISO 37001 về hệ thống quản lý chống hối lộ.","Phương pháp bán hàng tư vấn B2B: khai thác nhu cầu, đề xuất giá trị và quản lý chu kỳ bán hàng."],en:["Incoterms 2020 and how each term defines service scope and the freight payer.","Freight and surcharge structure: ocean freight, BAF, THC, documentation fees, peak season surcharges, DEM/DET.","Decree 163/2017/ND-CP on logistics services and the Commercial Law 2005 (No. 36/2005/QH11).","The 2015 Criminal Code applies bribery offences to the non-state sector too; ISO 37001 anti-bribery management systems as a reference.","Consultative B2B selling: needs discovery, value proposals and sales cycle management."]},tools:["Hệ thống CRM","Cổng giá cước trực tuyến của hãng tàu, hãng bay","Bảng tính giá vốn và biên lợi nhuận","Phần mềm quản lý giao nhận (Forwarding ERP)","Nền tảng theo dõi lô hàng"],kpis:{vi:["Doanh số và lợi nhuận gộp theo tháng, theo khách hàng.","Tỷ lệ chốt báo giá (win rate).","Biên lợi nhuận gộp bình quân mỗi TEU hoặc mỗi kg hàng không.","Công nợ quá hạn của khách hàng phụ trách."],en:["Monthly revenue and gross profit by customer.","Quote win rate.","Average gross margin per TEU or per air kilo.","Overdue receivables of assigned customers."]},day:[{time:"08:30",vi:"Cập nhật bảng giá hãng tàu tuần mới, phụ phí và lịch tàu các tuyến chủ lực.",en:"Update this week's carrier rates, surcharges and schedules on key lanes."},{time:"10:00",vi:"Gọi khách tiềm năng, khai thác tuyến, sản lượng, Incoterms và kế hoạch giao hàng.",en:"Call prospects to learn lanes, volumes, Incoterms and shipping plans."},{time:"13:30",vi:"Lập báo giá trọn gói, kiểm tra giá vốn, biên lợi nhuận và trình duyệt nếu cần.",en:"Build all-in quotes, check costs and margin, and seek approval when needed."},{time:"15:30",vi:"Gặp khách đàm phán điều khoản hợp đồng, thời gian miễn phí và thanh toán.",en:"Meet customers to negotiate contract terms, free time and payment."},{time:"17:30",vi:"Cập nhật CRM, dự báo doanh số tuần và phối hợp khai thác về lô hàng đang chạy.",en:"Update the CRM and weekly forecast and align with operations on live shipments."}],mistakes:{vi:["Báo giá từ cảng đi trong khi khách mua EXW, bỏ sót chi phí lấy hàng và thông quan xuất.","Nhầm biên lợi nhuận với tỷ lệ cộng thêm trên giá vốn, làm giá bán thấp hơn mục tiêu.","Chấp nhận ‘hoa hồng’ ngầm cho nhân viên phía khách để giành hợp đồng, vi phạm pháp luật và đạo đức."],en:["Quoting from the port of loading when the customer buys EXW, missing pickup and export clearance costs.","Confusing margin with markup on cost, pricing below target.","Paying hidden ‘commissions’ to customer staff to win business, breaking the law and ethics."]},career:[{vi:"Nhân viên kinh doanh logistics",en:"Logistics sales executive"},{vi:"Chuyên viên kinh doanh cước cấp cao",en:"Senior freight sales executive"},{vi:"Trưởng nhóm kinh doanh",en:"Sales team leader"},{vi:"Giám đốc kinh doanh logistics",en:"Logistics sales director"}],glossary:[{term:"All-in rate",vi:"Giá trọn gói đã bao gồm cước và các phụ phí được liệt kê trong báo giá.",en:"A price that includes freight and all surcharges listed in the quote."},{term:"BAF",vi:"Phụ phí điều chỉnh giá nhiên liệu do hãng tàu áp dụng theo biến động giá dầu.",en:"Bunker adjustment factor applied by carriers to reflect fuel price changes."},{term:"Gross margin",vi:"Biên lợi nhuận gộp: (giá bán - giá vốn) / giá bán.",en:"Gross margin: (selling price - cost) / selling price."},{term:"DEM/DET",vi:"Phí lưu container trong cảng (DEM) và ngoài cảng (DET) khi quá thời gian miễn phí.",en:"Charges for keeping a container inside the terminal (DEM) or outside it (DET) beyond free time."},{term:"Win rate",vi:"Tỷ lệ báo giá hoặc cơ hội được khách chấp nhận trên tổng số đã gửi.",en:"Share of quotes or opportunities won out of all those submitted."}],quiz:[{q:{vi:"Giá vốn 800 USD, biên lợi nhuận gộp mục tiêu 20% trên giá bán. Giá bán là bao nhiêu?",en:"Cost is 800 USD and the target gross margin is 20% of price. What is the selling price?"},options:{vi:["960 USD","1000 USD","1040 USD","820 USD"],en:["960 USD","1000 USD","1040 USD","820 USD"]},answer:1,explain:{vi:"Giá bán = 800 / (1 - 0,2) = 1000 USD; cộng thêm 20% trên giá vốn chỉ được 960 USD.",en:"Price = 800 / (1 - 0.2) = 1000 USD; a 20% markup on cost gives only 960 USD."}},{q:{vi:"Nhân viên mua hàng của khách đòi khoản chi riêng để ký hợp đồng. Bạn làm gì?",en:"A customer's buyer demands a private payment to sign the contract. What do you do?"},options:{vi:["Đồng ý nếu khoản nhỏ","Chi từ tiền cá nhân","Hứa rồi tìm cách sau","Từ chối, báo cấp trên và đề xuất chiết khấu chính thức trong hợp đồng"],en:["Agree if the amount is small","Pay from your own pocket","Promise and figure it out later","Refuse, report to your manager and offer an official contract rebate"]},answer:3,explain:{vi:"Chi tiền riêng cho người có quyền hạn trong doanh nghiệp khách là hối lộ; ưu đãi phải chính thức với pháp nhân.",en:"Paying someone with authority at the customer is bribery; incentives must go officially to the legal entity."}},{q:{vi:"Khách mua EXW, báo giá trọn gói của công ty giao nhận cần bao gồm chặng nào?",en:"The customer buys EXW. Which legs must the forwarder's all-in quote include?"},options:{vi:["Từ kho người bán, gồm lấy hàng và thông quan xuất","Chỉ cước biển cảng đến cảng","Chỉ chi phí tại nơi đến","Chỉ bảo hiểm hàng hóa"],en:["From the seller's warehouse, including pickup and export clearance","Ocean freight port to port only","Destination charges only","Cargo insurance only"]},answer:0,explain:{vi:"Theo EXW, người mua nhận hàng tại kho người bán nên mọi chi phí từ đó đều thuộc người mua.",en:"Under EXW the buyer takes delivery at the seller's premises, so all costs from there fall on the buyer."}},{q:{vi:"Phí DET phát sinh khi nào?",en:"When is a DET charge incurred?"},options:{vi:["Hàng bị kiểm hóa","Tàu chậm cập cảng","Container lưu ngoài cảng quá thời gian miễn phí","Khách trả cước trễ"],en:["Cargo is inspected","The vessel berths late","A container stays outside the terminal beyond free time","The customer pays freight late"]},answer:2,explain:{vi:"Detention tính khi container rời cảng và được giữ ở kho khách quá số ngày miễn phí.",en:"Detention applies when a container is kept outside the terminal beyond the free days."}}]}},"KK-233":{scenario:{legacy:"E"},learning:{summary:{vi:"Quản lý vận hành kho hàng và hệ thống WMS điều hành toàn bộ dòng hàng trong kho: nhận hàng, cất hàng, lưu trữ, lấy hàng, đóng gói, xuất hàng và kiểm kê, đồng thời quản trị dữ liệu vị trí và tồn kho trên WMS. Mục tiêu là tồn kho chính xác, xuất đúng hàng đúng hạn theo FIFO/FEFO, năng suất cao và an toàn tuyệt đối cho người, hàng hóa, thiết bị.",en:"A warehouse operations and WMS coordinator runs the full flow of goods in the warehouse: receiving, put-away, storage, picking, packing, shipping and stock counts, while managing location and inventory data in the WMS. The goal is accurate stock, the right goods shipped on time under FIFO/FEFO, high productivity and full safety for people, goods and equipment."},responsibilities:{vi:["Lập kế hoạch nhân lực, thiết bị cho nhận hàng và xuất hàng theo lịch đơn, lịch xe.","Kiểm soát nhận hàng: đối chiếu ASN, số lượng, lô, hạn dùng và tình trạng bao bì trước khi nhập WMS.","Quản lý vị trí lưu trữ (slotting), quy tắc FIFO/FEFO và luồng lấy hàng trên WMS.","Tổ chức kiểm kê luân phiên, xử lý chênh lệch tồn kho và báo cáo nguyên nhân gốc.","Bảo đảm an toàn xe nâng, kệ chứa, phòng cháy chữa cháy và 5S trong toàn kho."],en:["Plan labour and equipment for receiving and shipping against order and truck schedules.","Control receiving: check the ASN, quantities, lots, expiry dates and packaging before posting to the WMS.","Manage slotting, FIFO/FEFO rules and picking flows in the WMS.","Run cycle counts, resolve stock variances and report root causes.","Ensure forklift, racking, fire safety and 5S standards across the warehouse."]},competencies:[{name:{vi:"Vận hành WMS",en:"WMS operations"},desc:{vi:"Cấu hình vị trí, quy tắc cất, lấy hàng và đọc báo cáo ngoại lệ trên WMS.",en:"Configure locations, put-away and picking rules, and read WMS exception reports."}},{name:{vi:"Kiểm soát tồn kho",en:"Inventory accuracy control"},desc:{vi:"Thiết kế kiểm kê luân phiên theo ABC, truy nguyên chênh lệch và điều chỉnh có phê duyệt.",en:"Design ABC-based cycle counts, trace variances and post adjustments only with approval."}},{name:{vi:"Tối ưu năng suất kho",en:"Warehouse productivity"},desc:{vi:"Bố trí slotting, chọn phương pháp lấy hàng theo đơn, theo đợt hoặc theo vùng.",en:"Optimize slotting and choose order, batch or zone picking methods."}},{name:{vi:"An toàn & PCCC",en:"Safety & fire prevention"},desc:{vi:"Duy trì kiểm định xe nâng, tải trọng kệ, lối thoát nạn và huấn luyện an toàn định kỳ.",en:"Keep forklift inspections, rack load limits, escape routes and safety training up to date."}},{name:{vi:"Lãnh đạo ca kho",en:"Shift leadership"},desc:{vi:"Phân công, kèm cặp đội ngũ và phối hợp vận tải, mua hàng, kinh doanh.",en:"Assign and coach the team and coordinate with transport, purchasing and sales."}}],knowledge:{vi:["Nguyên tắc xuất kho FIFO, FEFO và quản lý lô, hạn dùng cho hàng có thời hạn sử dụng.","Kiểm kê luân phiên (cycle count) theo phân loại ABC và chỉ số độ chính xác tồn kho theo vị trí.","Chuẩn mã vạch GS1 (GTIN, SSCC) và quét mã trong nhận, cất, lấy, xuất hàng.","Luật An toàn, vệ sinh lao động 2015 (số 84/2015/QH13): xe nâng hàng thuộc nhóm thiết bị có yêu cầu nghiêm ngặt về an toàn, phải kiểm định theo quy định.","Quy định hiện hành về phòng cháy chữa cháy đối với kho hàng: khoảng cách xếp hàng, lối thoát nạn, hệ thống báo cháy."],en:["FIFO and FEFO issuing rules and lot and expiry management for shelf-life goods.","ABC-based cycle counting and location-level inventory accuracy.","GS1 barcode standards (GTIN, SSCC) and scanning in receiving, put-away, picking and shipping.","Occupational Safety and Health Law 2015 (No. 84/2015/QH13): forklifts are equipment with strict safety requirements and must be inspected as regulated.","Current fire safety rules for warehouses: storage clearances, escape routes and fire alarm systems."]},tools:["Hệ thống quản lý kho (WMS)","Máy quét mã vạch cầm tay (RF)","Xe nâng, xe nâng tay điện","Máy in nhãn mã vạch","Bảng điều khiển KPI kho"],kpis:{vi:["Độ chính xác tồn kho theo vị trí (mục tiêu từ 99,5%).","Tỷ lệ đơn xuất đúng, đủ, đúng hạn.","Năng suất lấy hàng (dòng/giờ) và thời gian từ nhận hàng đến sẵn sàng bán.","Số sự cố an toàn lao động (mục tiêu bằng 0)."],en:["Location-level inventory accuracy (target 99.5% or higher).","Share of orders shipped correct, complete and on time.","Picking productivity (lines per hour) and dock-to-stock time.","Workplace safety incidents (target zero)."]},day:[{time:"07:00",vi:"Họp đầu ca: an toàn, kế hoạch nhận xuất, phân công khu vực và thiết bị.",en:"Shift briefing: safety, receiving and shipping plan, zone and equipment assignments."},{time:"09:00",vi:"Giám sát nhận hàng, đối chiếu ASN, lô, hạn dùng và xử lý hàng sai lệch.",en:"Supervise receiving, check the ASN, lots and expiry dates and handle discrepancies."},{time:"11:00",vi:"Theo dõi các đợt lấy hàng trên WMS, điều chỉnh nhân lực cho đơn gấp.",en:"Monitor picking waves in the WMS and shift labour to urgent orders."},{time:"14:00",vi:"Kiểm kê luân phiên nhóm hàng A, truy nguyên chênh lệch với dữ liệu WMS.",en:"Cycle count class A items and trace variances against WMS data."},{time:"16:30",vi:"Chốt xuất hàng, kiểm tra niêm phong xe, báo cáo KPI và sự cố trong ngày.",en:"Close shipping, check truck seals and report daily KPIs and incidents."}],mistakes:{vi:["Cho xuất theo vị trí gần nhất thay vì theo FEFO, để hàng cận hạn tồn lại.","Điều chỉnh tồn kho trên WMS cho khớp số đếm mà không truy nguyên nguyên nhân và không có phê duyệt.","Cho người chưa có chứng chỉ vận hành xe nâng hoặc xếp hàng vượt tải trọng kệ để kịp chuyến."],en:["Picking from the nearest location instead of FEFO, leaving near-expiry stock behind.","Adjusting WMS stock to match the count without tracing the cause or getting approval.","Letting uncertified staff drive forklifts or overloading racks to make a truck on time."]},career:[{vi:"Nhân viên kho",en:"Warehouse associate"},{vi:"Tổ trưởng ca kho",en:"Warehouse shift supervisor"},{vi:"Quản lý vận hành kho & WMS",en:"Warehouse operations & WMS manager"},{vi:"Giám đốc trung tâm phân phối",en:"Distribution center director"}],glossary:[{term:"WMS",vi:"Hệ thống quản lý kho: điều khiển nhận, cất, lấy, xuất hàng và tồn kho theo vị trí.",en:"Warehouse management system controlling receiving, put-away, picking, shipping and location stock."},{term:"FEFO",vi:"Hết hạn trước xuất trước: ưu tiên xuất lô có hạn dùng sớm nhất.",en:"First expired, first out: the lot with the earliest expiry date ships first."},{term:"ASN",vi:"Thông báo giao hàng trước của nhà cung cấp: số lượng, lô, thời gian đến dự kiến.",en:"Advance shipping notice from the supplier with quantities, lots and expected arrival."},{term:"Slotting",vi:"Bố trí vị trí lưu trữ theo tần suất lấy hàng, kích thước và trọng lượng để tối ưu năng suất.",en:"Assigning storage locations by pick frequency, size and weight to maximize productivity."},{term:"Cycle count",vi:"Kiểm kê luân phiên từng nhóm vị trí theo lịch thay vì dừng kho kiểm kê toàn bộ.",en:"Counting groups of locations on a rolling schedule instead of shutting down for a full count."}],quiz:[{q:{vi:"Lô A hạn dùng 10/2027 nhập trước, lô B hạn dùng 03/2027 nhập sau. Theo FEFO xuất lô nào trước?",en:"Lot A (expiry 10/2027) arrived first; lot B (expiry 03/2027) arrived later. Under FEFO, which ships first?"},options:{vi:["Lô A vì nhập trước","Lô nào gần cửa hơn","Lô B vì hạn dùng sớm hơn","Chia đều hai lô"],en:["Lot A because it arrived first","Whichever is nearer the door","Lot B because it expires sooner","Split both lots evenly"]},answer:2,explain:{vi:"FEFO ưu tiên hạn dùng sớm nhất, không phụ thuộc thứ tự nhập kho.",en:"FEFO prioritizes the earliest expiry date regardless of arrival order."}},{q:{vi:"Kiểm kê 400 vị trí, có 6 vị trí sai lệch. Độ chính xác tồn kho theo vị trí là bao nhiêu?",en:"A count of 400 locations finds 6 with variances. What is location accuracy?"},options:{vi:["98,5%","99,4%","94,0%","96,5%"],en:["98.5%","99.4%","94.0%","96.5%"]},answer:0,explain:{vi:"(400 - 6) / 400 = 98,5%, thấp hơn mục tiêu 99,5% nên cần truy nguyên nguyên nhân.",en:"(400 - 6) / 400 = 98.5%, below the 99.5% target, so root causes must be traced."}},{q:{vi:"Cuối ca gấp chuyến, tổ trưởng bảo một nhân viên chưa có chứng chỉ lái xe nâng. Bạn làm gì?",en:"At shift end a supervisor tells an uncertified worker to drive a forklift to make a truck. What do you do?"},options:{vi:["Đồng ý vì chỉ một chuyến","Cho lái nhưng có người đứng xem","Để tổ trưởng tự chịu trách nhiệm","Dừng lại, bố trí người có chứng chỉ hoặc lùi chuyến và báo quản lý"],en:["Agree since it is just one load","Let him drive with someone watching","Leave it to the supervisor's responsibility","Stop it, assign a certified driver or delay the truck and inform the manager"]},answer:3,explain:{vi:"Vận hành xe nâng phải được huấn luyện, có chứng chỉ; an toàn luôn đặt trước tiến độ.",en:"Forklift operation requires training and certification; safety always comes before schedule."}},{q:{vi:"Mục đích của kiểm kê luân phiên theo ABC là gì?",en:"What is the purpose of ABC-based cycle counting?"},options:{vi:["Thay thế hoàn toàn WMS","Kiểm hàng giá trị cao thường xuyên hơn mà không dừng kho","Giảm số lượng nhân viên kho","Chỉ kiểm hàng hư hỏng"],en:["Replace the WMS entirely","Count high-value items more often without stopping operations","Reduce warehouse headcount","Count damaged goods only"]},answer:1,explain:{vi:"Nhóm A được đếm dày hơn để giữ độ chính xác cho hàng giá trị cao mà kho vẫn vận hành.",en:"Class A items are counted more often to protect accuracy on high-value stock while operations continue."}}]}},"KK-234":{scenario:{company:"Ngọc Lam Foods",supervisor:{name:"Vương Thị Hạnh",role:{vi:"Trưởng phòng Hoạch định Cung ứng",en:"Supply Planning Manager"}},ref_code:"RP-3307",title:{vi:"Đúng nhóm hàng. Đúng điểm đặt hàng.",en:"Right class. Right reorder point."},brief:{vi:"Bạn rà soát kế hoạch bổ sung RP-3307 cho SKU NL-330 nước mắm chai 500 ml. Giá trị tiêu thụ năm của SKU nằm ở mức cộng dồn 72% tổng giá trị toàn danh mục (nhóm A tính đến 80%), dù đơn giá thấp. Nhu cầu bình quân 260 chai/ngày. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa phân nhóm ABC và điểm đặt hàng lại ROP (chai, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are reviewing replenishment plan RP-3307 for SKU NL-330, 500 ml fish sauce bottles. Its annual consumption value sits at 72% cumulative of the whole portfolio value (class A runs up to 80%), even though its unit price is low. Average demand is 260 bottles per day. Compare the draft with the approved file, correct the ABC class and the reorder point ROP (bottles, simulated data), then write an evidence-based report."},reference_title:{vi:"Hồ sơ chính sách tồn kho đã duyệt · RP-3307",en:"Approved inventory policy file · RP-3307"},fields:[{id:"ABC_CLASS",label:{vi:"Phân nhóm ABC",en:"ABC class"},initial:"CLASS-C",expected:"CLASS-A",choices:["CLASS-A","CLASS-B","CLASS-C"],reference:"Bảng phân tích ABC năm",ref_value:{vi:"NL-330: giá trị cộng dồn 72%; A đến 80%, B đến 95%, C phần còn lại",en:"NL-330: cumulative value 72%; A up to 80%, B up to 95%, C the rest"},hint:{vi:"ABC xếp theo giá trị tiêu thụ năm (sản lượng x đơn giá), không theo đơn giá một chai.",en:"ABC ranks by annual consumption value (volume x unit price), not by the price of one bottle."}},{id:"ROP_QTY",label:{vi:"Điểm đặt hàng lại ROP (chai)",en:"Reorder point ROP (bottles)"},initial:"2340",expected:"2538",reference:"Thông số cung ứng SKU NL-330",ref_value:{vi:"Thời gian chờ 9 ngày; độ lệch chuẩn nhu cầu 40 chai/ngày",en:"Lead time 9 days; demand standard deviation 40 bottles/day"},hint:{vi:"ROP phải gồm tồn kho an toàn tính theo mức phục vụ của đúng nhóm ABC.",en:"The ROP must include safety stock at the service level of the correct ABC class."}}],sop32:{vi:"ROP = nhu cầu bình quân ngày x thời gian chờ + SS; SS = z x độ lệch chuẩn nhu cầu ngày x căn bậc hai thời gian chờ; z = 1,65 cho nhóm A (mức phục vụ 95%), 1,28 cho nhóm B và C.",en:"ROP = average daily demand x lead time + SS; SS = z x daily demand standard deviation x square root of lead time; z = 1.65 for class A (95% service level), 1.28 for classes B and C."},context:{label:"APS / RP-3307",metrics:[{label:{vi:"Nhu cầu bình quân (chai/ngày)",en:"Average demand (bottles/day)"},value:"260"},{label:{vi:"Thời gian chờ (ngày)",en:"Lead time (days)"},value:"9"},{label:{vi:"Mức phục vụ nhóm A",en:"Class A service level"},value:"95%"}]},crisis:{vi:"Giám đốc kinh doanh yêu cầu: “Nhập dự báo tháng 12 tăng 40% theo chỉ tiêu quý và ghi là dự báo thống kê để ban giám đốc duyệt mua hàng nhanh. Đừng nhắc chuyện hạn dùng 6 tháng.”",en:"The sales director demands: “Enter a December forecast 40% higher to match the quarterly target and label it the statistical forecast so management approves purchasing fast. Don't mention the 6-month shelf life.”"},options:{safe:{vi:"Giữ dự báo thống kê, ghi riêng đề xuất tăng của kinh doanh kèm giả định; trình cuộc họp S&OP và trưởng phòng hoạch định, nêu rõ rủi ro hàng cận hạn và chi phí tồn kho.",en:"Keep the statistical forecast, log Sales' uplift separately with its assumptions, and take it to the S&OP meeting and planning manager with the expiry and holding-cost risks."},shortcut:{vi:"Nhập dự báo tăng 40% và ghi là dự báo thống kê như yêu cầu để kịp duyệt mua.",en:"Enter the 40% uplift and label it statistical as asked so purchasing gets approved in time."},wait:{vi:"Không cập nhật dự báo, chờ kinh doanh tự nhập vào hệ thống.",en:"Do not update the forecast and wait for Sales to enter it themselves."}},questions:{vi:["Vì sao SKU NL-330 thuộc CLASS-A dù đơn giá thấp? Số liệu nào trong bảng ABC chứng minh?","Trình bày cách tính tồn kho an toàn, ROP và cách xử lý khi bị yêu cầu ghi số chỉ tiêu thành dự báo thống kê."],en:["Why is SKU NL-330 CLASS-A despite its low unit price? Which ABC data proves it?","Explain how you calculated safety stock and the ROP, and how you handle a request to label a target as the statistical forecast."]},hints:{vi:["Đặt bản nháp cạnh bảng phân tích ABC, đánh dấu dòng phân nhóm đang dựa vào đơn giá.","Tính SS bằng hệ số z của đúng nhóm hàng rồi cộng nhu cầu trong thời gian chờ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dự báo phải minh bạch nguồn gốc; điều chỉnh theo ý kiến phải ghi rõ và trình S&OP."],en:["Place the draft next to the ABC analysis and flag the class line based on unit price.","Compute SS with the z of the correct class, then add lead-time demand per SOP 3.2.","Re-read SOP 4.2: forecasts must show their source; judgmental overrides must be logged and taken to S&OP."]}},learning:{summary:{vi:"Chuyên viên hoạch định nhu cầu và tồn kho dự báo nhu cầu theo SKU, kênh, vùng; thiết lập tồn kho an toàn, điểm đặt hàng và lập kế hoạch bổ sung để cân bằng mức phục vụ khách hàng với vốn lưu động. Công việc đòi hỏi tư duy thống kê, làm chủ dữ liệu bán hàng, phối hợp kinh doanh, sản xuất, mua hàng qua quy trình S&OP và trung thực tuyệt đối với số liệu.",en:"A demand and inventory planner forecasts demand by SKU, channel and region, sets safety stock and reorder points, and builds replenishment plans that balance customer service with working capital. The role calls for statistical thinking, command of sales data, coordination with sales, production and purchasing through S&OP, and full honesty with the numbers."},responsibilities:{vi:["Làm sạch dữ liệu bán ra, xây dựng dự báo thống kê theo SKU, kênh và vùng.","Tổ chức đồng thuận dự báo với kinh doanh, marketing trong chu trình S&OP hằng tháng.","Phân loại ABC/XYZ, thiết lập tồn kho an toàn, điểm đặt hàng và mức tồn tối đa.","Lập kế hoạch bổ sung, đề xuất đơn mua hoặc lệnh sản xuất theo năng lực và thời gian chờ.","Theo dõi độ chính xác dự báo, độ lệch, tồn kho chậm luân chuyển và hàng cận hạn."],en:["Clean sales history and build statistical forecasts by SKU, channel and region.","Run forecast consensus with sales and marketing in the monthly S&OP cycle.","Classify ABC/XYZ and set safety stock, reorder points and maximum levels.","Plan replenishment and propose purchase or production orders within capacity and lead times.","Track forecast accuracy, bias, slow-moving stock and near-expiry items."]},competencies:[{name:{vi:"Dự báo thống kê",en:"Statistical forecasting"},desc:{vi:"Chọn mô hình trung bình trượt, san bằng mũ hoặc mùa vụ phù hợp mẫu hình nhu cầu.",en:"Choose moving average, exponential smoothing or seasonal models that fit the demand pattern."}},{name:{vi:"Chính sách tồn kho",en:"Inventory policy design"},desc:{vi:"Tính tồn kho an toàn, ROP, mức tối thiểu tối đa theo mức phục vụ mục tiêu.",en:"Calculate safety stock, ROP and min-max levels for target service levels."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Làm sạch dữ liệu, loại nhiễu khuyến mãi, hết hàng và đo WMAPE, độ lệch dự báo.",en:"Clean data, remove promotion and stock-out noise, and measure WMAPE and bias."}},{name:{vi:"Điều phối S&OP",en:"S&OP facilitation"},desc:{vi:"Dẫn dắt cuộc họp đồng thuận, ghi rõ giả định và người chịu trách nhiệm.",en:"Lead consensus meetings and record assumptions and owners."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Tách bạch dự báo thống kê với chỉ tiêu kinh doanh, không trình số sai nguồn gốc.",en:"Keep statistical forecasts separate from sales targets and never misstate a number's source."}}],knowledge:{vi:["Phương pháp dự báo chuỗi thời gian: trung bình trượt, san bằng mũ, Holt-Winters cho dữ liệu mùa vụ.","Chỉ số đo dự báo: MAPE, WMAPE, độ lệch (bias) và tín hiệu theo dõi (tracking signal).","Công thức tồn kho an toàn theo mức phục vụ: SS = z x σ x √LT, với z ≈ 1,65 tương ứng mức phục vụ 95%.","Phân tích ABC theo giá trị tiêu thụ và XYZ theo hệ số biến thiên nhu cầu.","Quy trình S&OP và mô hình tham chiếu SCOR của ASCM.","Mô hình đặt hàng EOQ và các hệ thống bổ sung liên tục, định kỳ, min-max."],en:["Time-series forecasting: moving average, exponential smoothing and Holt-Winters for seasonal data.","Forecast metrics: MAPE, WMAPE, bias and tracking signal.","Service-level safety stock: SS = z x σ x √LT, with z ≈ 1.65 for a 95% service level.","ABC analysis by consumption value and XYZ by coefficient of variation.","The S&OP process and the ASCM SCOR reference model.","EOQ and continuous, periodic and min-max replenishment systems."]},tools:["Hệ thống hoạch định nâng cao (APS)","Mô-đun hoạch định của ERP","Excel và Power Query","Python hoặc R cho thống kê","Công cụ trực quan hóa dữ liệu (BI)"],kpis:{vi:["Độ chính xác dự báo theo WMAPE và độ lệch dự báo.","Mức phục vụ: tỷ lệ đáp ứng đơn hàng (fill rate).","Số ngày tồn kho và giá trị hàng chậm luân chuyển.","Tỷ lệ hàng hủy do hết hạn (mục tiêu giảm liên tục)."],en:["Forecast accuracy (WMAPE) and forecast bias.","Service level measured as order fill rate.","Days of inventory and value of slow-moving stock.","Share of stock written off for expiry (target continuous reduction)."]},day:[{time:"08:00",vi:"Cập nhật dữ liệu bán ra, tồn kho, đơn mua đang về và cảnh báo hết hàng.",en:"Refresh sales, stock and inbound purchase data and review stock-out alerts."},{time:"09:30",vi:"Chạy dự báo thống kê, rà soát ngoại lệ do khuyến mãi, hết hàng, mùa vụ.",en:"Run the statistical forecast and review exceptions from promotions, stock-outs and seasonality."},{time:"13:30",vi:"Họp đồng thuận dự báo với kinh doanh, marketing; ghi rõ giả định điều chỉnh.",en:"Hold forecast consensus with sales and marketing and log every override assumption."},{time:"15:00",vi:"Tính lại tồn kho an toàn, ROP và đề xuất đơn bổ sung cho nhóm A.",en:"Recalculate safety stock and ROP and propose replenishment for class A items."},{time:"17:00",vi:"Báo cáo độ chính xác dự báo, rủi ro thiếu hàng và hàng cận hạn.",en:"Report forecast accuracy, stock-out risks and near-expiry items."}],mistakes:{vi:["Phân loại ABC theo đơn giá thay vì giá trị tiêu thụ năm.","Đặt ROP bằng nhu cầu trong thời gian chờ, quên tồn kho an toàn.","Ghi chỉ tiêu kinh doanh thành dự báo thống kê, gây mua thừa và hủy hàng hết hạn."],en:["Classifying ABC by unit price instead of annual consumption value.","Setting the ROP at lead-time demand only and forgetting safety stock.","Labelling sales targets as the statistical forecast, causing overbuying and expiry write-offs."]},career:[{vi:"Nhân viên phân tích tồn kho",en:"Inventory analyst"},{vi:"Chuyên viên hoạch định nhu cầu & tồn kho",en:"Demand & inventory planner"},{vi:"Trưởng nhóm S&OP",en:"S&OP lead"},{vi:"Giám đốc hoạch định chuỗi cung ứng",en:"Supply chain planning director"}],glossary:[{term:"ROP",vi:"Điểm đặt hàng lại: mức tồn kho mà khi chạm tới phải phát đơn bổ sung.",en:"Reorder point: the stock level at which a replenishment order must be raised."},{term:"Safety stock",vi:"Tồn kho an toàn để bù biến động của nhu cầu và thời gian chờ.",en:"Buffer stock that covers variability in demand and lead time."},{term:"S&OP",vi:"Hoạch định bán hàng và vận hành: quy trình hằng tháng cân bằng cung và cầu.",en:"Sales and operations planning: a monthly process that balances supply and demand."},{term:"WMAPE",vi:"Sai số phần trăm tuyệt đối bình quân có trọng số theo sản lượng.",en:"Weighted mean absolute percentage error, weighted by volume."},{term:"Lead time",vi:"Thời gian chờ từ lúc đặt hàng đến khi hàng sẵn sàng sử dụng.",en:"Time from placing an order until the goods are available for use."}],quiz:[{q:{vi:"Nhu cầu 100 đơn vị/ngày, thời gian chờ 4 ngày, độ lệch chuẩn 20 đơn vị/ngày, z = 1,65. ROP là bao nhiêu?",en:"Demand is 100 units/day, lead time 4 days, standard deviation 20 units/day, z = 1.65. What is the ROP?"},options:{vi:["400","420","433","466"],en:["400","420","433","466"]},answer:3,explain:{vi:"Tồn kho an toàn SS = 1,65 x 20 x √4 = 66; ROP = 100 x 4 + 66 = 466 đơn vị.",en:"SS = 1.65 x 20 x √4 = 66; ROP = 100 x 4 + 66 = 466."}},{q:{vi:"Phân tích ABC dựa trên tiêu chí nào?",en:"What criterion does ABC analysis use?"},options:{vi:["Đơn giá sản phẩm","Giá trị tiêu thụ năm (sản lượng x đơn giá)","Kích thước bao bì","Thời gian chờ"],en:["Unit price","Annual consumption value (volume x unit price)","Package size","Lead time"]},answer:1,explain:{vi:"ABC xếp hạng theo giá trị tiêu thụ năm; hàng đơn giá thấp nhưng bán nhiều vẫn có thể thuộc nhóm A.",en:"ABC ranks by annual consumption value; a cheap item that sells in volume can still be class A."}},{q:{vi:"Kinh doanh yêu cầu ghi chỉ tiêu thành dự báo thống kê. Bạn làm gì?",en:"Sales asks you to label their target as the statistical forecast. What do you do?"},options:{vi:["Làm theo vì kinh doanh chịu trách nhiệm","Không nói gì và tự giảm số liệu xuống","Tách bạch hai con số, ghi giả định và trình S&OP","Xóa dữ liệu lịch sử cho khớp"],en:["Comply because Sales is accountable","Say nothing and quietly cut the numbers","Keep both numbers separate, log assumptions and take it to S&OP","Delete history so it matches"]},answer:2,explain:{vi:"Dự báo phải minh bạch nguồn gốc; điều chỉnh theo ý kiến được phép nhưng phải ghi rõ và được S&OP phê duyệt.",en:"Forecasts must show their source; judgmental overrides are allowed only when logged and approved in S&OP."}},{q:{vi:"Dự báo liên tục cao hơn thực tế bán ra thường dẫn tới điều gì?",en:"What does a forecast that is persistently above actual sales usually cause?"},options:{vi:["Tồn kho dư thừa và tăng rủi ro hết hạn","Thiếu hàng thường xuyên","Giảm chi phí lưu kho","Tăng độ chính xác dự báo"],en:["Excess stock and higher expiry risk","Frequent stock-outs","Lower holding costs","Higher forecast accuracy"]},answer:0,explain:{vi:"Dự báo thiên cao kéo đơn mua tăng, tồn kho dư, tốn vốn và dễ hủy hàng cận hạn.",en:"An over-forecast inflates purchases and stock, ties up cash and drives expiry write-offs."}}]}},"KK-235":{scenario:{company:"Tuyết Sơn Cold Chain",supervisor:{name:"Mai Đức Thắng",role:{vi:"Trưởng phòng Đảm bảo Chất lượng Chuỗi lạnh",en:"Cold Chain QA Manager"}},ref_code:"CC-7152",title:{vi:"Đúng nhiệt độ. Đúng dữ liệu. Đúng quyết định.",en:"Right temperature. Right data. Right decision."},brief:{vi:"Container lạnh CC-7152 chở 22 tấn cá tra phi lê đông lạnh từ kho Cần Thơ đến cảng Cát Lái, nhiệt độ cài đặt -20°C, ngưỡng cảnh báo -15°C. Logger ghi mỗi 5 phút; trên hành trình có 3 đợt vượt ngưỡng do máy phát mất điện. Nhiệt độ lõi đo khi nhận là -16,5°C. Đối chiếu biên bản bàn giao nháp với hồ sơ đã duyệt, sửa quyết định xử lý lô và tổng thời gian vượt ngưỡng (phút), rồi lập báo cáo có căn cứ.",en:"Reefer container CC-7152 carries 22 tonnes of frozen pangasius fillets from a Can Tho cold store to Cat Lai port, setpoint -20°C, alarm threshold -15°C. The logger records every 5 minutes; the trip had 3 excursions caused by genset power loss. Core temperature at receipt was -16.5°C. Compare the draft handover record with the approved file, correct the lot disposition and the total excursion time (minutes), then write an evidence-based report."},reference_title:{vi:"Hồ sơ nhiệt độ & quy trình sai lệch đã duyệt · CC-7152",en:"Approved temperature record & excursion procedure · CC-7152"},fields:[{id:"DISPOSITION",label:{vi:"Quyết định xử lý lô",en:"Lot disposition"},initial:"RELEASE",expected:"QUARANTINE",choices:["RELEASE","QUARANTINE","REJECT"],reference:"Quy trình xử lý sai lệch nhiệt độ",ref_value:{vi:"Vượt -15°C cộng dồn trên 60 phút: cách ly chờ QA; lõi trên -12°C: loại bỏ",en:"Above -15°C for over 60 cumulative minutes: quarantine for QA; core above -12°C: reject"},hint:{vi:"Quyết định dựa trên tổng thời gian vượt ngưỡng cộng dồn và nhiệt độ lõi, không dựa vào đợt dài nhất.",en:"Decide on cumulative excursion time and core temperature, not on the longest single event."}},{id:"EXC_MIN",label:{vi:"Tổng thời gian vượt ngưỡng (phút)",en:"Total excursion time (minutes)"},initial:"45",expected:"115",reference:"Báo cáo logger hành trình",ref_value:{vi:"Số bản ghi trên -15°C: đợt 1 có 9, đợt 2 có 6, đợt 3 có 8; chu kỳ ghi 5 phút",en:"Readings above -15°C: event 1 has 9, event 2 has 6, event 3 has 8; logging interval 5 minutes"},hint:{vi:"Cộng dồn mọi đợt vượt ngưỡng trên toàn hành trình rồi nhân với chu kỳ ghi.",en:"Add up every excursion over the whole trip, then multiply by the logging interval."}}],sop32:{vi:"Thời gian vượt ngưỡng = tổng số bản ghi vượt ngưỡng của mọi đợt trong hành trình x chu kỳ ghi của logger; so tổng này với giới hạn trong quy trình xử lý sai lệch.",en:"Excursion time = total readings above the threshold across all events of the trip x logger interval; compare this total with the limit in the excursion procedure."},context:{label:"CCMS / CC-7152",metrics:[{label:{vi:"Nhiệt độ cài đặt",en:"Setpoint"},value:"-20°C"},{label:{vi:"Ngưỡng cảnh báo",en:"Alarm threshold"},value:"-15°C"},{label:{vi:"Nhiệt độ lõi khi nhận",en:"Core temperature at receipt"},value:"-16.5°C"}]},crisis:{vi:"Kinh doanh nhắn: “Tàu chạy tối nay, khách đang chờ. Cắt đoạn dữ liệu logger, chỉ in báo cáo đợt 45 phút rồi cho xuất, đừng cách ly làm gì cho lỡ chuyến.”",en:"Sales messages you: “The vessel sails tonight and the customer is waiting. Cut the logger data, print only the 45-minute event and release it, don't quarantine and miss the sailing.”"},options:{safe:{vi:"Không chỉnh sửa dữ liệu logger; cách ly lô, báo Trưởng phòng QA và khách theo thỏa thuận; đề xuất đo lõi, lấy mẫu đánh giá nhanh và chuẩn bị đổi chuyến nếu cần.",en:"Do not alter logger data; quarantine the lot, inform the QA manager and the customer as agreed, and propose core checks, rapid sampling and a rebooking if needed."},shortcut:{vi:"Cắt bớt dữ liệu logger, in báo cáo đợt 45 phút và cho xuất lô kịp tàu.",en:"Trim the logger data, print the 45-minute event only and release the lot for the sailing."},wait:{vi:"Để container chờ ở bãi, không cập nhật và không báo QA cho đến khi tàu đi.",en:"Leave the container in the yard, update nothing and tell QA nothing until the vessel leaves."}},questions:{vi:["Vì sao lô CC-7152 phải QUARANTINE thay vì RELEASE? Dữ liệu logger nào chứng minh?","Trình bày cách tính tổng thời gian vượt ngưỡng và rủi ro an toàn thực phẩm, pháp lý nếu chỉnh sửa dữ liệu logger."],en:["Why must lot CC-7152 go to QUARANTINE instead of RELEASE? Which logger data proves it?","Explain how you calculated total excursion time and the food safety and legal risks of altering logger data."]},hints:{vi:["Đặt biên bản nháp cạnh quy trình xử lý sai lệch, đánh dấu dòng quyết định đang dựa vào một đợt.","Cộng số bản ghi vượt ngưỡng của cả ba đợt rồi nhân chu kỳ ghi theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu nhiệt độ là bằng chứng gốc, mọi áp lực sửa hoặc cắt dữ liệu phải báo cáo."],en:["Place the draft record next to the excursion procedure and flag the decision based on a single event.","Add the readings above threshold from all three events and multiply by the interval per SOP 3.2.","Re-read SOP 4.2: temperature data is original evidence; any pressure to edit or cut it must be escalated."]}},learning:{summary:{vi:"Chuyên viên logistics chuỗi lạnh bảo đảm thực phẩm đông lạnh, hàng mát và dược phẩm được bảo quản, vận chuyển trong dải nhiệt độ yêu cầu từ kho đến điểm nhận. Công việc gồm lập kế hoạch thiết bị lạnh, kiểm tra trước chuyến, giám sát logger, xử lý sai lệch nhiệt độ và lưu hồ sơ truy xuất. Yêu cầu cốt lõi là hiểu an toàn thực phẩm, quy trình kiểm soát nhiệt độ và tôn trọng tuyệt đối dữ liệu gốc.",en:"A cold chain logistics specialist ensures that frozen food, chilled goods and pharmaceuticals are stored and moved within their required temperature range from warehouse to consignee. The work covers planning refrigerated equipment, pre-trip inspections, logger monitoring, handling temperature excursions and keeping traceability records. The core requirements are food safety knowledge, temperature control discipline and absolute respect for original data."},responsibilities:{vi:["Lập kế hoạch xe lạnh, container lạnh và kho lạnh theo loại hàng, dải nhiệt độ và thời gian hành trình.","Kiểm tra trước chuyến (PTI), cài đặt nhiệt độ, làm lạnh trước thiết bị và kiểm tra logger đã hiệu chuẩn.","Giám sát nhiệt độ theo thời gian thực, xử lý cảnh báo, sự cố mất điện và hỏng máy lạnh.","Đánh giá sai lệch nhiệt độ, cách ly lô và phối hợp QA quyết định giải phóng hoặc loại bỏ.","Lưu hồ sơ nhiệt độ, biên bản bàn giao và báo cáo truy xuất cho khách hàng, cơ quan chức năng."],en:["Plan reefer trucks, reefer containers and cold stores by product, temperature range and trip time.","Run pre-trip inspections (PTI), set temperatures, pre-cool equipment and check calibrated loggers.","Monitor temperatures in real time and handle alarms, power loss and refrigeration failures.","Assess excursions, quarantine lots and work with QA on release or rejection.","Keep temperature records and handover reports and provide traceability to customers and authorities."]},competencies:[{name:{vi:"Kiểm soát nhiệt độ",en:"Temperature control"},desc:{vi:"Nắm dải nhiệt độ của từng nhóm hàng và cách xếp hàng để không khí lạnh lưu thông.",en:"Know each product group's range and how to stow so that cold air circulates."}},{name:{vi:"Phân tích dữ liệu logger",en:"Logger data analysis"},desc:{vi:"Đọc đường cong nhiệt độ, tính thời gian vượt ngưỡng cộng dồn và nhận diện nguyên nhân.",en:"Read temperature curves, compute cumulative excursion time and identify causes."}},{name:{vi:"Quản lý sai lệch",en:"Excursion management"},desc:{vi:"Cách ly, điều tra, đánh giá tác động và đề xuất hành động khắc phục, phòng ngừa (CAPA).",en:"Quarantine, investigate, assess impact and propose corrective and preventive actions (CAPA)."}},{name:{vi:"An toàn thực phẩm",en:"Food safety"},desc:{vi:"Áp dụng HACCP, vệ sinh thiết bị và kiểm soát nhiễm chéo trong vận chuyển.",en:"Apply HACCP, equipment hygiene and cross-contamination control in transport."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Giữ dữ liệu nhiệt độ nguyên vẹn, đầy đủ, truy xuất được; từ chối chỉnh sửa trái phép.",en:"Keep temperature data complete, unaltered and traceable; refuse unauthorized edits."}}],knowledge:{vi:["Luật An toàn thực phẩm 2010 (số 55/2010/QH12) và trách nhiệm bảo quản, vận chuyển thực phẩm.","Hệ thống HACCP và các nguyên tắc chung về vệ sinh thực phẩm của Codex Alimentarius.","Dải nhiệt độ phổ biến: hàng đông lạnh từ -18°C trở xuống, hàng mát khoảng 0-5°C, đa số vắc xin 2-8°C.","Thực hành tốt bảo quản và phân phối (GSP, GDP) đối với dược phẩm, vắc xin cần chuỗi lạnh.","Hiệp định ATP của Liên Hợp Quốc về thiết bị vận chuyển thực phẩm dễ hư hỏng.","Hiệu chuẩn thiết bị đo nhiệt độ, bố trí logger và kiểm tra trước chuyến (PTI) container lạnh."],en:["Food Safety Law 2010 (No. 55/2010/QH12) and duties for storing and transporting food.","HACCP and the Codex Alimentarius general principles of food hygiene.","Common ranges: frozen goods at -18°C or below, chilled goods about 0-5°C, most vaccines 2-8°C.","Good storage and distribution practices (GSP, GDP) for cold chain medicines and vaccines.","The UN ATP Agreement on equipment for carrying perishable foodstuffs.","Calibration of temperature instruments, logger placement and reefer pre-trip inspection (PTI)."]},tools:["Data logger nhiệt độ và phần mềm đọc dữ liệu","Hệ thống giám sát nhiệt độ từ xa (IoT)","Nhiệt kế đo lõi đã hiệu chuẩn","Bộ điều khiển máy lạnh container","Hệ thống quản lý kho lạnh (WMS)"],kpis:{vi:["Số sai lệch nhiệt độ trên 100 chuyến.","Tỷ lệ lô bị loại bỏ do hỏng chuỗi lạnh (mục tiêu bằng 0).","Tỷ lệ chuyến có đầy đủ dữ liệu logger, truy xuất được.","Thời gian phản hồi cảnh báo nhiệt độ."],en:["Temperature excursions per 100 trips.","Share of lots rejected due to cold chain failure (target zero).","Share of trips with complete, traceable logger data.","Response time to temperature alarms."]},day:[{time:"06:00",vi:"Kiểm tra PTI container lạnh, làm lạnh trước thùng xe và cài đặt logger cho chuyến sáng.",en:"Run reefer PTIs, pre-cool truck bodies and set loggers for morning trips."},{time:"08:30",vi:"Giám sát xếp hàng tại cửa kho lạnh, kiểm tra nhiệt độ lõi và thời gian mở cửa.",en:"Supervise loading at the cold store dock, check core temperatures and door-open time."},{time:"11:00",vi:"Theo dõi bảng giám sát từ xa, xử lý cảnh báo vượt ngưỡng trên các tuyến.",en:"Watch the remote monitoring dashboard and handle threshold alarms on all routes."},{time:"14:00",vi:"Rà soát dữ liệu logger chuyến đã về, lập báo cáo sai lệch và đề xuất CAPA.",en:"Review logger data from returned trips, write excursion reports and propose CAPA."},{time:"17:00",vi:"Bàn giao ca, lưu hồ sơ nhiệt độ và cập nhật trạng thái cách ly, giải phóng lô.",en:"Hand over the shift, file temperature records and update quarantine and release status."}],mistakes:{vi:["Chỉ xét đợt vượt ngưỡng dài nhất, bỏ qua thời gian vượt ngưỡng cộng dồn cả hành trình.","Cho xe lạnh nhận hàng khi chưa làm lạnh trước thùng hoặc xếp hàng chặn luồng gió.","Cắt, sửa dữ liệu logger hoặc giải phóng lô sai lệch để kịp chuyến, gây rủi ro an toàn thực phẩm."],en:["Looking only at the longest excursion and ignoring cumulative time over the whole trip.","Loading a reefer before pre-cooling or stowing cargo that blocks the airflow.","Cutting or editing logger data or releasing a deviating lot to make a sailing, risking food safety."]},career:[{vi:"Nhân viên giám sát chuỗi lạnh",en:"Cold chain monitoring assistant"},{vi:"Chuyên viên logistics chuỗi lạnh",en:"Cold chain logistics specialist"},{vi:"Trưởng nhóm đảm bảo chất lượng chuỗi lạnh",en:"Cold chain QA lead"},{vi:"Quản lý vận hành chuỗi lạnh",en:"Cold chain operations manager"}],glossary:[{term:"Excursion",vi:"Sai lệch nhiệt độ: khoảng thời gian hàng nằm ngoài dải nhiệt độ cho phép.",en:"Temperature excursion: a period when goods are outside the allowed range."},{term:"PTI",vi:"Kiểm tra trước chuyến đối với container lạnh: máy lạnh, cảm biến, độ kín và vệ sinh.",en:"Pre-trip inspection of a reefer: refrigeration unit, sensors, seals and cleanliness."},{term:"Data logger",vi:"Thiết bị tự ghi nhiệt độ theo chu kỳ, là bằng chứng gốc của hành trình.",en:"Device that records temperature at set intervals and serves as original trip evidence."},{term:"Pre-cooling",vi:"Làm lạnh trước thùng xe hoặc container đến nhiệt độ cài đặt trước khi xếp hàng.",en:"Cooling the truck body or container to setpoint before loading."},{term:"Quarantine",vi:"Cách ly lô hàng, tạm dừng sử dụng hoặc xuất bán cho đến khi QA đánh giá xong.",en:"Holding a lot from use or sale until QA completes its assessment."}],quiz:[{q:{vi:"Logger ghi mỗi 10 phút, có 4 bản ghi vượt ngưỡng ở đợt 1 và 3 bản ghi ở đợt 2. Tổng thời gian vượt ngưỡng là bao nhiêu?",en:"A logger records every 10 minutes, with 4 readings above threshold in event 1 and 3 in event 2. What is the total excursion time?"},options:{vi:["70 phút","40 phút","30 phút","7 phút"],en:["70 minutes","40 minutes","30 minutes","7 minutes"]},answer:0,explain:{vi:"Cộng dồn 4 + 3 = 7 bản ghi, nhân chu kỳ 10 phút được 70 phút.",en:"Add 4 + 3 = 7 readings and multiply by the 10-minute interval to get 70 minutes."}},{q:{vi:"Dải nhiệt độ bảo quản phổ biến của đa số vắc xin là bao nhiêu?",en:"What is the usual storage range for most vaccines?"},options:{vi:["-25 đến -15°C","15-25°C","2-8°C","0-30°C"],en:["-25 to -15°C","15-25°C","2-8°C","0-30°C"]},answer:2,explain:{vi:"Đa số vắc xin bảo quản 2-8°C; một số loại đặc thù cần đông lạnh sâu theo hướng dẫn nhà sản xuất.",en:"Most vaccines are kept at 2-8°C; some special products need deep-frozen storage per the manufacturer."}},{q:{vi:"Kinh doanh đề nghị cắt dữ liệu logger để lô sai lệch kịp tàu. Bạn làm gì?",en:"Sales asks you to cut logger data so a deviating lot makes the vessel. What do you do?"},options:{vi:["Cắt dữ liệu vì chỉ vượt ngưỡng ngắn","Cho xuất rồi báo QA sau","Chờ tàu đi rồi mới báo","Giữ nguyên dữ liệu, cách ly lô và báo QA, khách hàng"],en:["Cut it since the excursion was short","Release now and tell QA later","Report only after the vessel leaves","Keep the data intact, quarantine the lot and inform QA and the customer"]},answer:3,explain:{vi:"Dữ liệu nhiệt độ là bằng chứng an toàn thực phẩm; chỉnh sửa là gian lận và có thể gây hại cho người tiêu dùng.",en:"Temperature data is food safety evidence; editing it is fraud and can harm consumers."}},{q:{vi:"Vì sao phải làm lạnh trước thùng xe trước khi xếp hàng đông lạnh?",en:"Why must a truck body be pre-cooled before loading frozen goods?"},options:{vi:["Để tiết kiệm nhiên liệu khi chạy","Vì máy lạnh xe chủ yếu duy trì nhiệt độ, không được thiết kế để hạ nhiệt hàng","Để tăng trọng lượng hàng","Để giảm thời gian thông quan"],en:["To save fuel on the road","Because the unit is built to maintain temperature, not to pull down warm cargo","To increase cargo weight","To shorten customs clearance"]},answer:1,explain:{vi:"Thùng ấm làm hàng tăng nhiệt ngay khi xếp; máy lạnh vận tải chỉ giữ nhiệt độ, không hạ nhiệt nhanh cho hàng.",en:"A warm body heats cargo on loading; transport units hold temperature and are not designed to pull it down."}}]}},"KK-236":{scenario:{company:"Đại Lộc Precision Manufacturing",supervisor:{name:"Nguyễn Hoài Nam",role:{vi:"Trưởng phòng Mua hàng",en:"Procurement Manager"}},ref_code:"RFQ-2419",title:{vi:"Đúng nhà cung cấp. Đúng tổng chi phí.",en:"Right supplier. Right total cost."},brief:{vi:"Bạn chấm RFQ-2419 mua 5000 vỏ ổ bi gang. Báo giá: V-118 41000 đ/cái, đã gồm vận chuyển; V-204 42500 đ/cái, vận chuyển 6 triệu đ/lô; V-377 40200 đ/cái, phí làm khuôn một lần 18 triệu đ, vận chuyển 4 triệu đ. Chất lượng và tiến độ ba bên tương đương. Đối chiếu đề xuất nháp với hồ sơ đã duyệt, sửa nhà cung cấp trúng chọn và tổng chi phí (VND, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are evaluating RFQ-2419 for 5000 cast iron bearing housings. Quotes: V-118 41000 VND each, freight included; V-204 42500 VND each, freight 6 million VND per lot; V-377 40200 VND each, one-off tooling 18 million VND, freight 4 million VND. Quality and lead time are equivalent. Compare the draft recommendation with the approved file, correct the awarded supplier and the total cost (VND, simulated figures), then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá báo giá & AVL đã duyệt · RFQ-2419",en:"Approved bid evaluation & AVL file · RFQ-2419"},fields:[{id:"SUPPLIER",label:{vi:"Nhà cung cấp trúng chọn",en:"Awarded supplier"},initial:"V-377",expected:"V-204",choices:["V-118","V-204","V-377"],reference:"Danh sách nhà cung cấp được duyệt",ref_value:{vi:"AVL: V-204, V-377 còn hiệu lực; V-118 quá hạn đánh giá lại, tạm ngừng giao dịch",en:"AVL: V-204, V-377 valid; V-118 overdue for re-audit, suspended"},hint:{vi:"Chỉ chọn trong AVL, rồi so tổng chi phí sở hữu chứ không so đơn giá.",en:"Choose only from the AVL, then compare total cost of ownership rather than unit price."}},{id:"TCO_VND",label:{vi:"Tổng chi phí phương án chọn (VND)",en:"Total cost of the award (VND)"},initial:"201000000",expected:"218500000",reference:"Bảng so sánh tổng chi phí",ref_value:{vi:"Số lượng 5000 cái; cộng phí khuôn, vận chuyển vào giá hàng của từng nhà cung cấp",en:"Quantity 5000 pcs; add tooling and freight to each supplier's goods value"},hint:{vi:"Tổng chi phí = đơn giá x số lượng + chi phí một lần + vận chuyển; tính cho cả hai nhà cung cấp hợp lệ.",en:"Total cost = unit price x quantity + one-off costs + freight; compute it for both eligible suppliers."}}],sop32:{vi:"Tổng chi phí sở hữu = đơn giá x số lượng + chi phí một lần (khuôn, thử mẫu) + vận chuyển; chọn nhà cung cấp trong AVL có tổng chi phí thấp nhất khi chất lượng, tiến độ tương đương.",en:"Total cost of ownership = unit price x quantity + one-off costs (tooling, samples) + freight; award the AVL supplier with the lowest total when quality and lead time are equal."},context:{label:"e-Procurement / RFQ-2419",metrics:[{label:{vi:"Số lượng (cái)",en:"Quantity (pcs)"},value:"5,000"},{label:{vi:"Số báo giá nhận được",en:"Quotes received"},value:"3"},{label:{vi:"Ngưỡng trình Tổng giám đốc (VND)",en:"CEO approval threshold (VND)"},value:"100,000,000"}]},crisis:{vi:"Giám đốc xưởng nhắn: “Chọn V-118 đi, chỗ người quen của anh. Cứ tách thành 3 đơn dưới 100 triệu để khỏi trình Tổng giám đốc, AVL tính sau.”",en:"The plant manager messages you: “Pick V-118, they are my acquaintances. Split it into 3 orders under 100 million so it skips the CEO, and sort out the AVL later.”"},options:{safe:{vi:"Từ chối tách đơn và mua ngoài AVL; báo Trưởng phòng Mua hàng về xung đột lợi ích, trình duyệt V-204 đúng ma trận phân quyền; nếu muốn dùng V-118 thì đề nghị đánh giá lại trước.",en:"Refuse to split the order or buy outside the AVL; report the conflict of interest to the procurement manager, route V-204 through the approval matrix, and require a re-audit before V-118 is used."},shortcut:{vi:"Chọn V-118 và tách thành 3 đơn dưới 100 triệu đ theo ý giám đốc xưởng.",en:"Award V-118 and split it into 3 orders under 100 million VND as the plant manager wants."},wait:{vi:"Treo hồ sơ RFQ, không trình ai để giám đốc xưởng tự quyết.",en:"Park the RFQ file and escalate nothing, leaving the plant manager to decide."}},questions:{vi:["Vì sao trao thầu cho V-204 thay vì V-377 có đơn giá thấp nhất? Bảng tổng chi phí nào chứng minh?","Trình bày cách tính tổng chi phí sở hữu và rủi ro tuân thủ khi tách đơn hoặc mua từ nhà cung cấp ngoài AVL."],en:["Why award V-204 instead of V-377, which has the lowest unit price? Which total cost table proves it?","Explain how you calculated total cost of ownership and the compliance risks of splitting orders or buying outside the AVL."]},hints:{vi:["Đặt đề xuất nháp cạnh danh sách AVL, loại nhà cung cấp không còn hiệu lực trước khi so giá.","Cộng đơn giá x số lượng, phí khuôn và vận chuyển cho từng nhà cung cấp theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không tách đơn để né phân quyền phê duyệt; xung đột lợi ích phải khai báo."],en:["Place the draft next to the AVL and remove suppliers that are no longer valid before comparing prices.","Add unit price x quantity, tooling and freight for each supplier per SOP 3.2.","Re-read SOP 4.2: never split orders to avoid approval limits; conflicts of interest must be declared."]}},learning:{summary:{vi:"Chuyên viên mua hàng và quản lý nhà cung cấp tìm nguồn, mời báo giá, đánh giá và lựa chọn nhà cung cấp, đàm phán hợp đồng, phát hành đơn mua và theo dõi hiệu suất giao hàng, chất lượng. Mục tiêu là mua đúng chất lượng, đúng thời điểm với tổng chi phí sở hữu tối ưu, đồng thời bảo đảm minh bạch, đúng phân quyền và không có xung đột lợi ích.",en:"A procurement and vendor management specialist sources suppliers, runs RFQs, evaluates and selects vendors, negotiates contracts, issues purchase orders and tracks delivery and quality performance. The aim is to buy the right quality at the right time at the best total cost of ownership while staying transparent, within approval limits and free of conflicts of interest."},responsibilities:{vi:["Tìm nguồn, mời báo giá (RFQ) và đánh giá năng lực nhà cung cấp mới.","So sánh báo giá theo tổng chi phí sở hữu, tiêu chí kỹ thuật và trình duyệt theo ma trận phân quyền.","Đàm phán giá, điều khoản thanh toán, giao hàng, bảo hành và soạn hợp đồng mua bán.","Phát hành đơn mua, theo dõi tiến độ giao hàng và phối hợp kiểm tra chất lượng đầu vào.","Đánh giá định kỳ nhà cung cấp, cập nhật danh sách AVL và quản lý rủi ro nguồn cung."],en:["Source suppliers, issue RFQs and assess the capability of new vendors.","Compare bids on total cost of ownership and technical criteria and route approvals through the authority matrix.","Negotiate price, payment, delivery and warranty terms and draft purchase contracts.","Issue purchase orders, expedite deliveries and coordinate incoming quality checks.","Review suppliers periodically, maintain the AVL and manage supply risk."]},competencies:[{name:{vi:"Tìm nguồn chiến lược",en:"Strategic sourcing"},desc:{vi:"Phân tích thị trường cung, phân nhóm vật tư theo ma trận Kraljic và chọn chiến lược mua phù hợp.",en:"Analyze supply markets, segment categories with the Kraljic matrix and choose the right sourcing strategy."}},{name:{vi:"Phân tích tổng chi phí",en:"Total cost analysis"},desc:{vi:"Tính TCO gồm giá, khuôn, vận chuyển, chất lượng, tồn kho để so sánh công bằng.",en:"Build TCO including price, tooling, freight, quality and inventory for a fair comparison."}},{name:{vi:"Đàm phán hợp đồng",en:"Contract negotiation"},desc:{vi:"Thương lượng giá và điều khoản rủi ro như phạt chậm giao, bảo hành có lợi cho doanh nghiệp.",en:"Negotiate price and risk terms such as late delivery penalties and warranties in the company's favour."}},{name:{vi:"Quản lý hiệu suất nhà cung cấp",en:"Supplier performance management"},desc:{vi:"Đo OTIF, tỷ lệ lỗi, tốc độ phản hồi và dẫn dắt cải tiến với nhà cung cấp.",en:"Measure OTIF, defect rates and responsiveness and drive improvement with suppliers."}},{name:{vi:"Liêm chính mua hàng",en:"Procurement integrity"},desc:{vi:"Khai báo xung đột lợi ích, tuân thủ phân quyền, từ chối quà tặng và lợi ích không chính đáng.",en:"Declare conflicts of interest, respect approval limits and refuse improper gifts or benefits."}}],knowledge:{vi:["ISO 9001:2015 điều 8.4 về kiểm soát quá trình, sản phẩm và dịch vụ do bên ngoài cung cấp.","Luật Thương mại 2005 (số 36/2005/QH11) và Bộ luật Dân sự 2015 (số 91/2015/QH13) về hợp đồng mua bán hàng hóa.","Luật Đấu thầu 2023 (số 22/2023/QH15) cho mua sắm sử dụng vốn nhà nước; doanh nghiệp tư nhân tham chiếu nguyên tắc cạnh tranh, minh bạch.","ISO 20400:2017 về mua sắm bền vững và đánh giá nhà cung cấp theo tiêu chí môi trường, xã hội.","Kiểm soát nội bộ trong mua hàng: phân quyền phê duyệt, tách bạch nhiệm vụ, đối chiếu ba bên đơn mua, phiếu nhập, hóa đơn."],en:["ISO 9001:2015 clause 8.4 on control of externally provided processes, products and services.","Commercial Law 2005 (No. 36/2005/QH11) and Civil Code 2015 (No. 91/2015/QH13) on sales contracts.","Bidding Law 2023 (No. 22/2023/QH15) for state-funded procurement; private firms follow its principles of competition and transparency.","ISO 20400:2017 on sustainable procurement and supplier assessment against environmental and social criteria.","Purchasing internal controls: approval authority, segregation of duties and three-way match of PO, goods receipt and invoice."]},tools:["Hệ thống mua hàng điện tử (e-Procurement)","Mô-đun mua hàng của ERP","Bảng so sánh báo giá và TCO","Phiếu đánh giá nhà cung cấp (scorecard)","Hệ thống quản lý hợp đồng"],kpis:{vi:["Mức tiết kiệm chi phí so với ngân sách hoặc giá cơ sở.","Tỷ lệ giao hàng đúng hạn, đủ số lượng (OTIF) của nhà cung cấp.","Tỷ lệ chi tiêu qua nhà cung cấp trong AVL và có hợp đồng.","Thời gian từ yêu cầu mua đến phát hành đơn mua."],en:["Cost savings against budget or baseline price.","Supplier on-time in-full (OTIF) delivery rate.","Share of spend with AVL suppliers under contract.","Cycle time from purchase requisition to purchase order."]},day:[{time:"08:00",vi:"Rà soát yêu cầu mua mới, kiểm tra ngân sách, quy cách kỹ thuật và mức độ khẩn.",en:"Review new requisitions and check budget, specifications and urgency."},{time:"09:30",vi:"Gửi RFQ, trao đổi kỹ thuật với nhà cung cấp và làm rõ điều khoản báo giá.",en:"Send RFQs, discuss technical points with suppliers and clarify quote terms."},{time:"13:30",vi:"Lập bảng so sánh tổng chi phí, trình duyệt theo ma trận phân quyền.",en:"Build the total cost comparison and route it through the approval matrix."},{time:"15:30",vi:"Đàm phán hợp đồng, đôn đốc đơn mua trễ hạn và xử lý hàng lỗi với QC.",en:"Negotiate contracts, chase late orders and resolve defects with QC."},{time:"17:00",vi:"Cập nhật scorecard nhà cung cấp, AVL và báo cáo tiết kiệm chi phí.",en:"Update supplier scorecards and the AVL and report cost savings."}],mistakes:{vi:["Chọn nhà cung cấp theo đơn giá thấp nhất mà bỏ qua chi phí khuôn, vận chuyển, chất lượng.","Phát hành đơn mua cho nhà cung cấp ngoài AVL hoặc đã quá hạn đánh giá lại.","Tách nhỏ đơn mua để né ngưỡng phê duyệt hoặc ưu ái người quen, vi phạm kiểm soát nội bộ."],en:["Choosing the lowest unit price while ignoring tooling, freight and quality costs.","Issuing POs to suppliers outside the AVL or overdue for re-audit.","Splitting orders to dodge approval limits or to favour acquaintances, breaching internal controls."]},career:[{vi:"Nhân viên mua hàng",en:"Purchasing assistant"},{vi:"Chuyên viên mua hàng & quản lý nhà cung cấp",en:"Procurement & vendor management specialist"},{vi:"Trưởng nhóm tìm nguồn chiến lược",en:"Strategic sourcing lead"},{vi:"Giám đốc mua hàng",en:"Chief procurement officer"}],glossary:[{term:"RFQ",vi:"Yêu cầu báo giá gửi nhiều nhà cung cấp với cùng quy cách, số lượng và điều kiện.",en:"Request for quotation sent to several suppliers with the same specification, quantity and terms."},{term:"AVL",vi:"Danh sách nhà cung cấp được phê duyệt sau đánh giá năng lực, chất lượng.",en:"Approved vendor list of suppliers qualified after capability and quality assessment."},{term:"TCO",vi:"Tổng chi phí sở hữu: giá mua cộng mọi chi phí phát sinh trong vòng đời mua và sử dụng.",en:"Total cost of ownership: purchase price plus all costs over the buying and usage life cycle."},{term:"Three-way match",vi:"Đối chiếu ba bên giữa đơn mua, phiếu nhập kho và hóa đơn trước khi thanh toán.",en:"Matching the purchase order, goods receipt and invoice before payment."},{term:"DOA",vi:"Ma trận phân quyền phê duyệt theo giá trị và loại giao dịch.",en:"Delegation of authority matrix setting approval rights by value and transaction type."}],quiz:[{q:{vi:"NCC A: 100000 đ/cái x 1000 cái, vận chuyển 5 triệu đ. NCC B: 97000 đ/cái, phí khuôn 6 triệu đ, vận chuyển 3 triệu đ. Phương án nào rẻ hơn về tổng chi phí?",en:"Supplier A: 100000 VND each x 1000 pcs, freight 5 million VND. Supplier B: 97000 VND each, tooling 6 million VND, freight 3 million VND. Which is cheaper in total?"},options:{vi:["NCC B, vì đơn giá thấp hơn","Hai phương án bằng nhau","NCC A, rẻ hơn 1 triệu đ","Không đủ dữ liệu"],en:["Supplier B, because its unit price is lower","Both are equal","Supplier A, cheaper by 1 million VND","Not enough data"]},answer:2,explain:{vi:"A = 100 + 5 = 105 triệu đ; B = 97 + 6 + 3 = 106 triệu đ, nên A rẻ hơn 1 triệu đ.",en:"A = 100 + 5 = 105 million VND; B = 97 + 6 + 3 = 106 million VND, so A is cheaper by 1 million."}},{q:{vi:"Đối chiếu ba bên (three-way match) là gì?",en:"What is a three-way match?"},options:{vi:["Khớp đơn mua, phiếu nhập kho và hóa đơn trước khi thanh toán","So sánh ba báo giá","Ba người cùng ký hợp đồng","Kiểm tra ba lô hàng mẫu"],en:["Matching PO, goods receipt and invoice before payment","Comparing three quotes","Three people signing the contract","Inspecting three sample lots"]},answer:0,explain:{vi:"Ba chứng từ phải khớp về số lượng, đơn giá trước khi thanh toán để ngăn sai sót và gian lận.",en:"The three documents must agree on quantity and price before payment to prevent errors and fraud."}},{q:{vi:"Người đề nghị mua muốn tách đơn để dưới ngưỡng duyệt của Tổng giám đốc. Bạn làm gì?",en:"A requester wants to split an order to stay below the CEO approval limit. What do you do?"},options:{vi:["Đồng ý vì vẫn mua đúng hàng","Từ chối, gộp đúng nhu cầu và trình duyệt theo ma trận phân quyền","Tách đơn nhưng ghi chú lại","Chuyển cho kế toán quyết định"],en:["Agree since the goods are right","Refuse, consolidate the real need and route it through the approval matrix","Split it but add a note","Let accounting decide"]},answer:1,explain:{vi:"Tách đơn để né phê duyệt là vi phạm kiểm soát nội bộ; nhu cầu thực phải được trình đúng cấp.",en:"Splitting to avoid approval breaches internal control; the real need must go to the right authority."}},{q:{vi:"Điều khoản nào hướng dẫn kiểm soát sản phẩm, dịch vụ do bên ngoài cung cấp trong hệ thống quản lý chất lượng?",en:"Which clause covers control of externally provided products and services in a quality management system?"},options:{vi:["ISO 14001 điều 6.1","ISO 45001 điều 5.4","ISO/IEC 27001 phụ lục A","ISO 9001:2015 điều 8.4"],en:["ISO 14001 clause 6.1","ISO 45001 clause 5.4","ISO/IEC 27001 Annex A","ISO 9001:2015 clause 8.4"]},answer:3,explain:{vi:"ISO 9001:2015 điều 8.4 yêu cầu đánh giá, lựa chọn, theo dõi và đánh giá lại nhà cung cấp bên ngoài.",en:"ISO 9001:2015 clause 8.4 requires evaluating, selecting, monitoring and re-evaluating external providers."}}]}},"KK-237":{scenario:{company:"Vịnh Ngọc Container Terminal",supervisor:{name:"Phan Văn Lực",role:{vi:"Trưởng ca Điều độ Bãi",en:"Yard Planning Shift Supervisor"}},ref_code:"YP-0517",title:{vi:"Đúng khu bãi. Đúng phí lưu bãi.",en:"Right yard block. Right storage charge."},brief:{vi:"Container 20' chứa sơn dung môi, hàng nguy hiểm IMDG loại 3, dỡ xuống bãi ngày 03/11 và chủ hàng lấy ra ngày 14/11. Sơ đồ bãi có block G04 (hàng khô thường), DG1 (hàng nguy hiểm, có tách biệt và thiết bị chữa cháy), RF2 (hàng lạnh có ổ cắm điện). Đối chiếu kế hoạch bãi nháp YP-0517 với hồ sơ đã duyệt, sửa block xếp container và phí lưu bãi (VND, biểu giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"A 20' container of solvent-based paint, IMDG class 3 dangerous goods, was discharged to the yard on 03/11 and collected by the consignee on 14/11. The yard has block G04 (general dry cargo), DG1 (dangerous goods, segregated, with firefighting equipment) and RF2 (reefers with power plugs). Compare draft yard plan YP-0517 with the approved file, correct the yard block and the storage charge (VND, simulated tariff), then write an evidence-based report."},reference_title:{vi:"Sơ đồ bãi & biểu cước lưu bãi đã duyệt · YP-0517",en:"Approved yard map & storage tariff · YP-0517"},fields:[{id:"YARD_BLOCK",label:{vi:"Block xếp container",en:"Assigned yard block"},initial:"G04",expected:"DG1",choices:["G04","DG1","RF2"],reference:"Sơ đồ bãi & quy định hàng nguy hiểm",hint:{vi:"Container hàng nguy hiểm phải xếp ở khu chuyên dụng có tách biệt theo IMDG, không xếp chung hàng thường.",en:"Dangerous goods containers belong in a dedicated area segregated per IMDG, never among general cargo."}},{id:"STORAGE_VND",label:{vi:"Phí lưu bãi (VND)",en:"Storage charge (VND)"},initial:"270000",expected:"630000",reference:"Biểu cước lưu bãi",ref_value:{vi:"Miễn phí 5 ngày; 45000 đ/ngày cho 20' thường; hàng nguy hiểm phụ thu 100% (mô phỏng)",en:"5 free days; 45000 VND/day for a standard 20'; dangerous goods surcharge 100% (simulated)"},hint:{vi:"Đếm cả ngày dỡ và ngày lấy ra, trừ ngày miễn phí rồi áp hệ số hàng nguy hiểm.",en:"Count both the discharge day and the gate-out day, deduct free days, then apply the dangerous goods factor."}}],sop32:{vi:"Số ngày lưu bãi tính cả ngày dỡ xuống và ngày lấy ra; phí lưu bãi = (số ngày lưu - số ngày miễn phí) x đơn giá ngày x (1 + tỷ lệ phụ thu hàng nguy hiểm).",en:"Storage days include both the discharge day and the gate-out day; storage charge = (storage days - free days) x daily rate x (1 + dangerous goods surcharge rate)."},context:{label:"TOS / YP-0517",metrics:[{label:{vi:"Ngày dỡ xuống bãi",en:"Discharge date"},value:"03/11"},{label:{vi:"Ngày lấy ra",en:"Gate-out date"},value:"14/11"},{label:{vi:"Loại IMDG",en:"IMDG class"},value:"3"}]},crisis:{vi:"Tổ trưởng bốc xếp nhắn: “Block DG1 gần đầy, để tạm container sơn ở G04 cạnh dãy hàng lạnh qua đêm, mai chuyển. Đừng cập nhật TOS cho đỡ rắc rối.”",en:"The stevedoring foreman messages you: “DG1 is almost full, park the paint box in G04 next to the reefer row overnight and move it tomorrow. Don't update the TOS, it's less hassle.”"},options:{safe:{vi:"Không xếp hàng nguy hiểm sai khu; bố trí vị trí còn trống ở DG1 hoặc khu dự phòng hàng nguy hiểm được duyệt, cập nhật TOS đúng thực tế, báo trưởng ca và cán bộ an toàn.",en:"Do not misplace dangerous goods; use a free slot in DG1 or the approved DG overflow area, update the TOS accurately and inform the shift supervisor and the safety officer."},shortcut:{vi:"Để tạm container ở G04 qua đêm và không cập nhật TOS như tổ trưởng đề nghị.",en:"Park the container in G04 overnight and leave the TOS unchanged as the foreman suggests."},wait:{vi:"Để container nằm trên xe đầu kéo chờ đến sáng, không báo ai.",en:"Leave the container on the terminal tractor until morning and tell no one."}},questions:{vi:["Vì sao container phải xếp ở DG1 thay vì G04? Quy định tách biệt nào chứng minh?","Trình bày cách tính phí lưu bãi và rủi ro an toàn, pháp lý nếu xếp hàng nguy hiểm sai khu hoặc không cập nhật TOS."],en:["Why must the container go to DG1 instead of G04? Which segregation rule proves it?","Explain how you calculated the storage charge and the safety and legal risks of misplacing dangerous goods or not updating the TOS."]},hints:{vi:["Đặt kế hoạch nháp cạnh sơ đồ bãi đã duyệt, đánh dấu container hàng nguy hiểm đang ở khu thường.","Đếm ngày lưu bãi theo SOP mục 3.2, trừ ngày miễn phí rồi áp phụ thu hàng nguy hiểm.","Đọc lại SOP mục 4.2: vị trí hàng nguy hiểm phải đúng khu và đúng dữ liệu TOS; áp lực làm tắt phải báo cáo."],en:["Place the draft plan next to the approved yard map and flag the DG container sitting in a general block.","Count storage days per SOP 3.2, deduct free days and apply the dangerous goods surcharge.","Re-read SOP 4.2: DG positions must be in the right area and match TOS data; shortcut pressure must be escalated."]}},learning:{summary:{vi:"Chuyên viên khai thác cảng và bãi container lập kế hoạch bãi, điều độ thiết bị xếp dỡ, kiểm soát giao nhận container qua cổng và giám sát hàng lạnh, hàng nguy hiểm trên hệ thống quản lý khai thác cảng (TOS). Mục tiêu là giải phóng tàu nhanh, bãi thông thoáng, dữ liệu vị trí chính xác, tính phí đúng biểu cước và tuyệt đối an toàn cho người, hàng hóa, thiết bị.",en:"A port and container yard operations officer plans the yard, dispatches handling equipment, controls container gate transactions and monitors reefers and dangerous goods in the terminal operating system (TOS). The goal is fast vessel turnaround, a fluid yard, accurate position data, correct tariff charging and full safety for people, cargo and equipment."},responsibilities:{vi:["Lập kế hoạch bãi theo tàu, hãng tàu, loại container, trọng lượng và cảng đích.","Điều độ thiết bị xếp dỡ: cẩu bờ, cẩu khung bánh lốp, xe nâng container, xe đầu kéo nội bộ.","Kiểm soát giao nhận qua cổng: lệnh giao hàng, tình trạng thủ tục hải quan, niêm phong, hư hỏng vỏ.","Giám sát container lạnh cắm điện và container hàng nguy hiểm theo khu tách biệt.","Đối chiếu dữ liệu TOS với thực tế, tính phí lưu bãi và báo cáo năng suất khai thác."],en:["Plan the yard by vessel, carrier, container type, weight and port of discharge.","Dispatch handling equipment: ship-to-shore cranes, RTGs, reach stackers and terminal tractors.","Control gate transactions: delivery orders, customs status, seals and container damage.","Monitor plugged-in reefers and DG containers in their segregated areas.","Reconcile TOS data with the yard, calculate storage charges and report productivity."]},competencies:[{name:{vi:"Lập kế hoạch bãi",en:"Yard planning"},desc:{vi:"Phân khu, xếp tầng theo trọng lượng và cảng đích để giảm đảo chuyển, tăng năng suất.",en:"Zone and stack by weight and destination to cut rehandles and raise productivity."}},{name:{vi:"Điều độ thiết bị",en:"Equipment dispatch"},desc:{vi:"Cân đối cẩu, xe nội bộ theo kế hoạch tàu và giờ cao điểm tại cổng.",en:"Balance cranes and tractors against vessel plans and gate peaks."}},{name:{vi:"Hàng nguy hiểm & an toàn",en:"Dangerous goods & safety"},desc:{vi:"Áp dụng quy tắc tách biệt IMDG, khu bãi chuyên dụng và quy trình ứng phó sự cố.",en:"Apply IMDG segregation, dedicated yard areas and emergency response procedures."}},{name:{vi:"Chính xác dữ liệu TOS",en:"TOS data accuracy"},desc:{vi:"Cập nhật vị trí, trạng thái, niêm phong theo thời gian thực, không để lệch hệ thống.",en:"Update positions, statuses and seals in real time so the system never drifts from reality."}},{name:{vi:"Phối hợp đa bên",en:"Multi-party coordination"},desc:{vi:"Làm việc với hãng tàu, hải quan, chủ hàng, đơn vị vận tải và đội bốc xếp.",en:"Work with carriers, customs, cargo owners, hauliers and stevedoring teams."}}],knowledge:{vi:["Bộ luật IMDG của IMO: phân loại hàng nguy hiểm và bảng tách biệt khi xếp, lưu container.","Yêu cầu VGM theo Công ước SOLAS đối với container xuất khẩu trước khi xếp lên tàu.","Luật Hải quan 2014 (số 54/2014/QH13): hàng chỉ được đưa ra khỏi khu vực giám sát hải quan khi đủ điều kiện về thủ tục.","ISO 6346 về mã hiệu container và ISO 668 về kích thước, khối lượng tối đa của container.","Bộ luật ISPS về an ninh tàu biển và bến cảng.","Chỉ số khai thác: số lần nâng hạ mỗi giờ của cẩu, thời gian lưu bãi, hệ số sử dụng bãi theo TEU."],en:["The IMO IMDG Code: dangerous goods classes and segregation tables for stowing and storing containers.","The SOLAS VGM requirement for export containers before loading.","Customs Law 2014 (No. 54/2014/QH13): goods may leave the customs-controlled area only when formalities are met.","ISO 6346 on container identification and ISO 668 on container dimensions and maximum gross mass.","The ISPS Code on ship and port facility security.","Terminal indicators: crane moves per hour, dwell time and yard utilization in TEU."]},tools:["Hệ thống quản lý khai thác cảng (TOS)","Cổng tự động nhận dạng số container, biển số (OCR)","Thiết bị đầu cuối trên cẩu và xe nội bộ (VMT)","Hệ thống giám sát container lạnh","Phần mềm lập sơ đồ xếp tàu"],kpis:{vi:["Năng suất cẩu bờ (số lần nâng hạ mỗi giờ).","Thời gian lưu bãi bình quân và hệ số sử dụng bãi.","Thời gian xe chờ tại cổng và trong bãi.","Tỷ lệ sai lệch vị trí giữa TOS và thực tế (mục tiêu bằng 0)."],en:["Quay crane productivity (moves per hour).","Average dwell time and yard utilization.","Truck turnaround time at the gate and in the yard.","Position mismatches between TOS and the yard (target zero)."]},day:[{time:"06:30",vi:"Nhận ca, rà soát tình trạng bãi, container lạnh, hàng nguy hiểm và kế hoạch tàu trong ngày.",en:"Take over the shift and review yard status, reefers, dangerous goods and today's vessel plan."},{time:"08:00",vi:"Lập kế hoạch bãi cho tàu sắp cập, phân khu theo cảng đích và trọng lượng.",en:"Plan the yard for the next vessel, zoning by destination and weight."},{time:"11:00",vi:"Điều độ thiết bị giờ cao điểm cổng, xử lý xe chờ lâu và container sai vị trí.",en:"Dispatch equipment during gate peaks and fix long truck waits and misplaced boxes."},{time:"14:00",vi:"Kiểm tra khu DG, khu lạnh; đối chiếu dữ liệu TOS với kiểm đếm thực tế.",en:"Inspect the DG and reefer areas and reconcile TOS data with a physical check."},{time:"17:30",vi:"Tính phí lưu bãi các lô giao trong ngày, bàn giao ca và báo cáo năng suất.",en:"Calculate storage for today's deliveries, hand over the shift and report productivity."}],mistakes:{vi:["Xếp container hàng nguy hiểm vào khu hàng thường hoặc cạnh khu lạnh, vi phạm tách biệt.","Tính ngày lưu bãi không đếm ngày dỡ hoặc ngày lấy ra, bỏ sót phụ thu hàng nguy hiểm.","Di chuyển container mà không cập nhật TOS, gây mất dấu container và rủi ro an toàn."],en:["Placing DG containers among general cargo or next to reefers, breaching segregation.","Leaving out the discharge or gate-out day when counting storage, or missing the DG surcharge.","Moving containers without updating the TOS, losing track of boxes and creating safety risks."]},career:[{vi:"Nhân viên kiểm đếm bãi",en:"Yard checker"},{vi:"Chuyên viên điều độ bãi container",en:"Container yard planner"},{vi:"Trưởng ca khai thác",en:"Operations shift manager"},{vi:"Giám đốc khai thác cảng",en:"Terminal operations director"}],glossary:[{term:"TOS",vi:"Hệ thống quản lý khai thác cảng: kế hoạch tàu, bãi, cổng và thiết bị.",en:"Terminal operating system for vessel, yard, gate and equipment planning."},{term:"TEU",vi:"Đơn vị tương đương container 20 feet, dùng đo sức chứa bãi và tàu.",en:"Twenty-foot equivalent unit used to measure yard and vessel capacity."},{term:"Dwell time",vi:"Thời gian lưu bãi của container từ khi dỡ xuống đến khi lấy ra.",en:"Time a container stays in the yard from discharge to gate-out."},{term:"Segregation",vi:"Tách biệt: khoảng cách hoặc ngăn cách bắt buộc giữa các loại hàng nguy hiểm không tương thích.",en:"Required distance or separation between incompatible dangerous goods."},{term:"Reefer plug",vi:"Ổ cắm điện cấp nguồn cho container lạnh tại bãi.",en:"Power outlet that supplies a refrigerated container in the yard."}],quiz:[{q:{vi:"Container dỡ ngày 05, lấy ra ngày 12 cùng tháng, miễn phí 4 ngày, tính cả ngày dỡ và ngày lấy. Số ngày tính phí là bao nhiêu?",en:"A container is discharged on the 5th and collected on the 12th, with 4 free days and both days counted. How many days are charged?"},options:{vi:["3 ngày","4 ngày","7 ngày","8 ngày"],en:["3 days","4 days","7 days","8 days"]},answer:1,explain:{vi:"Từ ngày 05 đến 12 tính cả hai đầu là 8 ngày; trừ 4 ngày miễn phí còn 4 ngày tính phí.",en:"From the 5th to the 12th inclusive is 8 days; minus 4 free days leaves 4 chargeable days."}},{q:{vi:"Văn bản nào quy định tách biệt hàng nguy hiểm khi vận chuyển container đường biển?",en:"Which instrument sets segregation rules for dangerous goods in sea container transport?"},options:{vi:["Incoterms 2020","UCP 600","ISO 9001","Bộ luật IMDG"],en:["Incoterms 2020","UCP 600","ISO 9001","The IMDG Code"]},answer:3,explain:{vi:"Bộ luật IMDG của IMO quy định phân loại, đóng gói, ghi nhãn và tách biệt hàng nguy hiểm.",en:"The IMO IMDG Code governs classification, packing, labelling and segregation of dangerous goods."}},{q:{vi:"Khu DG đầy, tổ trưởng đề nghị để tạm container hàng nguy hiểm ở khu thường và không cập nhật TOS. Bạn làm gì?",en:"The DG area is full and a foreman proposes parking a DG box in a general block without updating the TOS. What do you do?"},options:{vi:["Từ chối, bố trí khu DG hoặc khu dự phòng được duyệt, cập nhật TOS và báo trưởng ca","Đồng ý vì chỉ qua đêm","Để trên xe đầu kéo, không báo ai","Cập nhật TOS sau khi đã chuyển đi"],en:["Refuse, use the DG area or approved overflow, update the TOS and inform the supervisor","Agree since it is only overnight","Leave it on a tractor and tell no one","Update the TOS after it is moved"]},answer:0,explain:{vi:"Xếp sai khu làm mất tách biệt và che giấu vị trí hàng nguy hiểm khi có sự cố cháy nổ.",en:"Wrong placement breaks segregation and hides the DG position from responders in a fire."}},{q:{vi:"Vì sao phải xếp container theo trọng lượng và cảng đích?",en:"Why stack containers by weight and port of discharge?"},options:{vi:["Để giảm phí lưu bãi","Để tăng số container lạnh","Để giảm đảo chuyển và bảo đảm ổn định khi xếp tàu","Để rút ngắn thủ tục hải quan"],en:["To reduce storage charges","To increase reefer count","To cut rehandles and support vessel stability","To shorten customs formalities"]},answer:2,explain:{vi:"Xếp đúng thứ tự giúp lấy container theo kế hoạch xếp tàu mà không đảo chuyển, giữ ổn định tàu.",en:"Proper stacking lets boxes be picked in loading order without rehandles and supports vessel stability."}}]}},"KK-238":{scenario:{company:"Sao Việt Home Retail",supervisor:{name:"Tạ Quốc Bảo",role:{vi:"Trưởng nhóm Phân tích Chuỗi cung ứng",en:"Supply Chain Analytics Lead"}},ref_code:"SCA-1124",title:{vi:"Đúng mẫu số. Đúng số ngày tồn kho.",en:"Right denominator. Right days of inventory."},brief:{vi:"Bạn hoàn thiện báo cáo SCA-1124 về số ngày tồn kho (DIO) ngành hàng gia dụng quý III (92 ngày). Số liệu: doanh thu 36,8 tỷ đ, giá vốn hàng bán 27,6 tỷ đ, tồn kho đầu kỳ 10,86 tỷ đ, cuối kỳ 12,54 tỷ đ (ghi theo giá vốn). Đối chiếu bản nháp với hồ sơ phương pháp đã duyệt, sửa cơ sở mẫu số và giá trị DIO (ngày, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are finalizing report SCA-1124 on days of inventory (DIO) for the household goods category in Q3 (92 days). Data: revenue 36.8 billion VND, cost of goods sold 27.6 billion VND, opening inventory 10.86 billion VND, closing 12.54 billion VND (carried at cost). Compare the draft with the approved methodology file, correct the denominator basis and the DIO value (days, simulated data), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phương pháp chỉ số tồn kho đã duyệt · SCA-1124",en:"Approved inventory metric methodology · SCA-1124"},fields:[{id:"DIO_BASIS",label:{vi:"Mẫu số dùng tính DIO",en:"DIO denominator basis"},initial:"REVENUE",expected:"COGS",choices:["REVENUE","COGS","PURCHASES"],reference:"Từ điển chỉ số chuỗi cung ứng",hint:{vi:"Tồn kho ghi theo giá vốn nên mẫu số phải cùng cơ sở giá vốn, không dùng doanh thu đã gồm lãi gộp.",en:"Inventory is carried at cost, so the denominator must be on a cost basis, not revenue that includes gross profit."}},{id:"DIO_DAYS",label:{vi:"Số ngày tồn kho DIO (ngày)",en:"Days of inventory DIO (days)"},initial:"29.25",expected:"39",reference:"Phiếu phương pháp tính DIO",ref_value:{vi:"Tồn kho bình quân = (đầu kỳ + cuối kỳ) / 2; kỳ phân tích 92 ngày",en:"Average inventory = (opening + closing) / 2; analysis period 92 days"},hint:{vi:"Lấy tồn kho bình quân chia giá vốn của kỳ rồi nhân số ngày trong kỳ.",en:"Divide average inventory by the period's cost of goods sold, then multiply by the days in the period."}}],sop32:{vi:"DIO = tồn kho bình quân / giá vốn hàng bán của kỳ x số ngày của kỳ; tồn kho bình quân = (đầu kỳ + cuối kỳ) / 2; tử số và mẫu số phải cùng cơ sở giá vốn.",en:"DIO = average inventory / cost of goods sold for the period x days in the period; average inventory = (opening + closing) / 2; numerator and denominator must share the cost basis."},context:{label:"BI / SCA-1124",metrics:[{label:{vi:"Giá vốn quý III (tỷ đ)",en:"Q3 COGS (VND billion)"},value:"27.6"},{label:{vi:"Doanh thu quý III (tỷ đ)",en:"Q3 revenue (VND billion)"},value:"36.8"},{label:{vi:"Số ngày trong kỳ",en:"Days in period"},value:"92"}]},crisis:{vi:"Giám đốc tài chính nhờ: “Loại 1,8 tỷ đ hàng chậm luân chuyển khỏi tồn kho bình quân trong bản trình ngân hàng để DIO xuống dưới 35 ngày. Chỉ là bản trình bày thôi, không cần ghi chú.”",en:"The CFO asks: “Take 1.8 billion VND of slow-moving stock out of average inventory in the bank presentation so DIO drops below 35 days. It's only a presentation, no footnote needed.”"},options:{safe:{vi:"Giữ DIO đầy đủ theo phương pháp đã duyệt, trình bày riêng nhóm hàng chậm luân chuyển và kế hoạch xử lý; báo Trưởng nhóm phân tích, không phát hành số liệu loại trừ mà không công bố rõ.",en:"Keep the full DIO per the approved method, show slow-moving stock separately with a reduction plan, inform the analytics lead and never publish an exclusion without clear disclosure."},shortcut:{vi:"Loại 1,8 tỷ đ khỏi tồn kho bình quân và không ghi chú, cho kịp gửi ngân hàng.",en:"Remove the 1.8 billion VND from average inventory without a note to meet the bank deadline."},wait:{vi:"Gửi cả hai bản số liệu cho giám đốc tài chính tự chọn bản trình ngân hàng.",en:"Send both versions to the CFO and let them pick one for the bank."}},questions:{vi:["Vì sao DIO phải tính trên COGS thay vì doanh thu? Số liệu nào trong báo cáo chứng minh?","Trình bày cách tính DIO đã sửa và rủi ro khi loại trừ hàng chậm luân chuyển khỏi số liệu trình ngân hàng mà không công bố."],en:["Why must DIO use COGS instead of revenue? Which figures in the report prove it?","Explain how you calculated the corrected DIO and the risk of excluding slow-moving stock from bank figures without disclosure."]},hints:{vi:["Đặt bản nháp cạnh từ điển chỉ số, kiểm tra tử số và mẫu số có cùng cơ sở giá trị hay không.","Tính tồn kho bình quân rồi chia giá vốn bình quân mỗi ngày theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi điều chỉnh số liệu phải minh bạch, ghi rõ phạm vi và báo cáo người phê duyệt."],en:["Place the draft next to the metric dictionary and check whether numerator and denominator share a value basis.","Compute average inventory, then divide by average daily COGS per SOP 3.2.","Re-read SOP 4.2: every data adjustment must be transparent, scoped and reported to the approver."]}},learning:{summary:{vi:"Chuyên viên phân tích chuỗi cung ứng thu thập, làm sạch và phân tích dữ liệu mua hàng, tồn kho, vận tải, giao hàng để đo hiệu quả chuỗi, tìm nguyên nhân gốc và đề xuất cải tiến bằng mô hình định lượng. Công việc đòi hỏi chuẩn hóa định nghĩa chỉ số, kỹ năng SQL, thống kê, trực quan hóa và sự trung thực tuyệt đối với dữ liệu khi trình bày cho ban điều hành.",en:"A supply chain analyst collects, cleans and analyzes purchasing, inventory, transport and delivery data to measure chain performance, find root causes and recommend improvements with quantitative models. The role requires standardized metric definitions, SQL, statistics and visualization skills, and complete honesty with data when presenting to leadership."},responsibilities:{vi:["Xây dựng và duy trì từ điển chỉ số: OTIF, fill rate, DIO, vòng quay tồn kho, chi phí logistics.","Trích xuất, làm sạch dữ liệu từ ERP, WMS, TMS và kiểm soát chất lượng dữ liệu.","Phân tích nguyên nhân gốc của thiếu hàng, giao trễ, tồn kho dư bằng Pareto, hồi quy, phân khúc.","Mô hình hóa kịch bản mạng lưới kho, chính sách tồn kho, chi phí vận tải để hỗ trợ quyết định.","Thiết kế bảng điều khiển, báo cáo định kỳ và trình bày khuyến nghị cho ban điều hành."],en:["Build and maintain the metric dictionary: OTIF, fill rate, DIO, inventory turns, logistics cost.","Extract and clean data from ERP, WMS and TMS and control data quality.","Analyze root causes of stock-outs, late deliveries and excess stock with Pareto, regression and segmentation.","Model scenarios for warehouse networks, inventory policies and transport costs to support decisions.","Design dashboards and recurring reports and present recommendations to leadership."]},competencies:[{name:{vi:"Chuẩn hóa chỉ số",en:"KPI definition"},desc:{vi:"Định nghĩa tử số, mẫu số, cơ sở giá trị và kỳ tính nhất quán cho mọi báo cáo.",en:"Define numerator, denominator, value basis and period consistently across every report."}},{name:{vi:"Phân tích định lượng",en:"Quantitative analysis"},desc:{vi:"Dùng thống kê, hồi quy, mô phỏng và tối ưu hóa để lượng hóa các phương án.",en:"Use statistics, regression, simulation and optimization to quantify options."}},{name:{vi:"Kỹ thuật dữ liệu cơ bản",en:"Data engineering basics"},desc:{vi:"Viết SQL, kết nối nguồn ERP, WMS, TMS và kiểm soát chất lượng dữ liệu.",en:"Write SQL, connect ERP, WMS and TMS sources and control data quality."}},{name:{vi:"Kể chuyện bằng dữ liệu",en:"Data storytelling"},desc:{vi:"Trực quan hóa rõ ràng, nêu giả định, giới hạn và khuyến nghị hành động.",en:"Visualize clearly and state assumptions, limits and recommended actions."}},{name:{vi:"Liêm chính phân tích",en:"Analytical integrity"},desc:{vi:"Không chọn lọc, loại trừ dữ liệu để làm đẹp kết quả; công bố đầy đủ phạm vi và phương pháp.",en:"Never cherry-pick or exclude data to flatter results; disclose scope and method in full."}}],knowledge:{vi:["Mô hình tham chiếu SCOR của ASCM và các thuộc tính hiệu quả chuỗi cung ứng: độ tin cậy, khả năng đáp ứng, chi phí, hiệu quả tài sản.","Chỉ số vốn lưu động: DIO, vòng quay tồn kho, chu kỳ chuyển đổi tiền (cash-to-cash).","Chuẩn mực kế toán VAS 02 và IAS 2 về hàng tồn kho: ghi theo giá gốc, lập dự phòng khi giá trị thuần có thể thực hiện được thấp hơn.","Phương pháp phân tích: Pareto, hồi quy, phân khúc ABC/XYZ, kiểm định giả thuyết và mô phỏng Monte Carlo.","Tối ưu hóa mạng lưới và quy hoạch tuyến tính cho bài toán vị trí kho, phân bổ vận tải."],en:["The ASCM SCOR reference model and supply chain performance attributes: reliability, responsiveness, cost and asset efficiency.","Working capital metrics: DIO, inventory turns and the cash-to-cash cycle.","VAS 02 and IAS 2 on inventories: carried at cost, with a write-down when net realizable value is lower.","Analytical methods: Pareto, regression, ABC/XYZ segmentation, hypothesis testing and Monte Carlo simulation.","Network optimization and linear programming for warehouse location and transport allocation."]},tools:["SQL","Python (pandas) hoặc R","Công cụ BI và bảng điều khiển","Excel nâng cao (Power Query, Solver)","Phần mềm thiết kế mạng lưới chuỗi cung ứng"],kpis:{vi:["Tỷ lệ báo cáo đúng hạn, không phải đính chính số liệu.","Giá trị tiết kiệm hoặc cải thiện từ khuyến nghị đã triển khai.","Mức độ áp dụng từ điển chỉ số trong các báo cáo chính thức.","Thời gian từ câu hỏi kinh doanh đến phân tích có kết luận."],en:["Share of reports delivered on time with no data corrections.","Savings or improvements from implemented recommendations.","Adoption of the metric dictionary in official reports.","Time from business question to a conclusive analysis."]},day:[{time:"08:30",vi:"Kiểm tra luồng dữ liệu đêm qua từ ERP, WMS, TMS và các cảnh báo chất lượng dữ liệu.",en:"Check overnight data loads from ERP, WMS and TMS and data quality alerts."},{time:"10:00",vi:"Phân tích nguyên nhân giao trễ tuần trước bằng Pareto theo kho, tuyến, nhà cung cấp.",en:"Analyze last week's late deliveries with Pareto by warehouse, lane and supplier."},{time:"13:30",vi:"Mô hình hóa kịch bản thay đổi chính sách tồn kho và ước tính tác động vốn lưu động.",en:"Model inventory policy scenarios and estimate the working capital impact."},{time:"15:30",vi:"Trao đổi với vận hành, tài chính để thống nhất định nghĩa và giả định chỉ số.",en:"Align metric definitions and assumptions with operations and finance."},{time:"17:00",vi:"Cập nhật bảng điều khiển, viết tóm tắt phát hiện và khuyến nghị cho trưởng nhóm.",en:"Refresh dashboards and write a summary of findings and recommendations for the lead."}],mistakes:{vi:["Tính DIO hoặc vòng quay tồn kho bằng doanh thu trong khi tồn kho ghi theo giá vốn.","Dùng tồn kho cuối kỳ thay cho tồn kho bình quân khi tồn kho biến động mạnh.","Âm thầm loại trừ dữ liệu bất lợi để kết quả đẹp hơn, làm sai lệch quyết định của ban điều hành."],en:["Computing DIO or inventory turns on revenue while inventory is carried at cost.","Using closing inventory instead of average inventory when stock swings widely.","Quietly excluding unfavourable data to improve results, misleading leadership decisions."]},career:[{vi:"Nhân viên phân tích dữ liệu vận hành",en:"Operations data analyst"},{vi:"Chuyên viên phân tích chuỗi cung ứng",en:"Supply chain analyst"},{vi:"Chuyên gia phân tích chuỗi cung ứng cấp cao",en:"Senior supply chain analytics specialist"},{vi:"Trưởng phòng phân tích & chiến lược chuỗi cung ứng",en:"Head of supply chain analytics & strategy"}],glossary:[{term:"DIO",vi:"Số ngày tồn kho: tồn kho bình quân chia giá vốn hàng bán bình quân mỗi ngày.",en:"Days inventory outstanding: average inventory divided by average daily cost of goods sold."},{term:"OTIF",vi:"Tỷ lệ đơn giao vừa đúng hạn vừa đủ số lượng trên tổng số đơn.",en:"Share of orders delivered both on time and in full out of all orders."},{term:"COGS",vi:"Giá vốn hàng bán: chi phí của số hàng đã bán trong kỳ.",en:"Cost of goods sold: the cost of the goods sold in the period."},{term:"Cash-to-cash",vi:"Chu kỳ chuyển đổi tiền: DIO + DSO - DPO, đo số ngày vốn bị giữ trong vận hành.",en:"Cash conversion cycle: DIO + DSO - DPO, the days cash is tied up in operations."},{term:"Pareto",vi:"Phân tích 80/20 để xác định số ít nguyên nhân gây ra phần lớn vấn đề.",en:"80/20 analysis identifying the few causes behind most of the problem."}],quiz:[{q:{vi:"Giá vốn cả năm 365 tỷ đ, tồn kho bình quân 40 tỷ đ. DIO là bao nhiêu ngày?",en:"Annual COGS is 365 billion VND and average inventory 40 billion VND. What is DIO?"},options:{vi:["40 ngày","9,1 ngày","36,5 ngày","73 ngày"],en:["40 days","9.1 days","36.5 days","73 days"]},answer:0,explain:{vi:"Giá vốn mỗi ngày 1 tỷ đ; DIO = 40 / 365 x 365 = 40 ngày.",en:"Daily COGS is 1 billion VND; DIO = 40 / 365 x 365 = 40 days."}},{q:{vi:"200 đơn: 180 đúng hạn, 176 đủ hàng, 168 vừa đúng hạn vừa đủ hàng. OTIF là bao nhiêu?",en:"Of 200 orders, 180 were on time, 176 in full and 168 both. What is OTIF?"},options:{vi:["90%","88%","84%","79,2%"],en:["90%","88%","84%","79.2%"]},answer:2,explain:{vi:"OTIF chỉ đếm đơn đạt cả hai điều kiện: 168 / 200 = 84%, không nhân hai tỷ lệ riêng.",en:"OTIF counts orders meeting both conditions: 168 / 200 = 84%, not the product of two rates."}},{q:{vi:"Giám đốc nhờ bỏ nhóm hàng tồn lâu khỏi số liệu trình ngân hàng mà không ghi chú. Bạn làm gì?",en:"A director asks you to drop slow-moving stock from bank figures without a note. What do you do?"},options:{vi:["Làm theo vì chỉ là bản trình bày","Giữ số liệu đầy đủ, trình bày riêng nhóm hàng tồn lâu và báo người phê duyệt","Gửi hai bản để giám đốc tự chọn","Xóa dữ liệu gốc cho khớp"],en:["Comply since it is only a presentation","Keep full figures, show slow movers separately and inform the approver","Send two versions and let the director choose","Delete the source data to match"]},answer:1,explain:{vi:"Loại trừ không công bố làm sai lệch thông tin cho bên cho vay; mọi điều chỉnh phải minh bạch.",en:"Undisclosed exclusions mislead lenders; every adjustment must be transparent."}},{q:{vi:"Theo VAS 02, hàng tồn kho được ghi nhận theo cơ sở nào?",en:"Under VAS 02, on what basis is inventory recognized?"},options:{vi:["Giá bán dự kiến","Giá thị trường cao nhất","Giá trị sổ sách tùy chọn","Giá gốc; lập dự phòng nếu giá trị thuần có thể thực hiện được thấp hơn"],en:["Expected selling price","Highest market price","Any chosen book value","Cost, with a write-down if net realizable value is lower"]},answer:3,explain:{vi:"VAS 02 yêu cầu ghi theo giá gốc; khi giá trị thuần có thể thực hiện được thấp hơn thì ghi theo giá trị này qua dự phòng.",en:"VAS 02 requires cost; when net realizable value is lower, inventory is written down to it through a provision."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(3)})(window.KKR);
